if not string.split then
    string.split = function(s, sep)
        sep = sep or ","
        local result = {}
        local sepLen = #sep
        local start = 1
        while true do
            local i = string.find(s, sep, start, true)
            if not i then
                result[#result + 1] = string.sub(s, start)
                break
            end
            result[#result + 1] = string.sub(s, start, i - 1)
            start = i + sepLen
        end
        return result
    end
end
if not os.date then
    os.date = function(fmt, t)
        t = t or os.time()
        if fmt == "*t" then
            local s = t % 60
            local m = math.floor(t / 60) % 60
            local h = math.floor(t / 3600) % 24
            local d = math.floor(t / 86400)
            local y = 1970 + math.floor(d / 365)
            local mo = math.floor((d % 365) / 30) + 1
            return { hour = h, min = m, sec = s, day = (d % 30) + 1, month = mo, year = y, wday = (d % 7) + 1, yday = d % 365 + 1 }
        end
        local s = t % 60
        local m = math.floor(t / 60) % 60
        local h = math.floor(t / 3600) % 24
        local result = fmt or "%H:%M:%S"
        result = result:gsub("%%H", string.format("%02d", h))
        result = result:gsub("%%M", string.format("%02d", m))
        result = result:gsub("%%S", string.format("%02d", s))
        result = result:gsub("%%Y", tostring(1970 + math.floor(t / 31536000)))
        result = result:gsub("%%d", string.format("%02d", math.floor(t / 86400) % 30 + 1))
        result = result:gsub("%%m", string.format("%02d", math.floor(t / 2592000) % 12 + 1))
        result = result:gsub("%%b", "---")
        return result
    end
end
local function SafeClipboard(text)
    text = tostring(text or "")
    local fns = { setclipboard, toclipboard, rbxsetclipboard,
                  (syn and syn.toclipboard),
                  (typeof(_G) == "table" and _G.setclipboard) }
    for _, fn in ipairs(fns) do
        if typeof(fn) == "function" then
            local ok = pcall(fn, text)
            if ok then return true end
        end
    end
    return false
end
local function _SafeEnum(enumType, member)
    local ok, v = pcall(function() return Enum[enumType][member] end)
    return ok and v or nil
end
