if type(task) ~= "table" then task = {} end
if type(task.wait) ~= "function" then
    task.wait = function(t)
        t = tonumber(t) or 0
        local start = tick()
        if t > 0 then
            while tick() - start < t do
                game:GetService("RunService").Heartbeat:Wait()
            end
        end
        return tick() - start
    end
end
if type(task.spawn) ~= "function" then
    task.spawn = function(fn, ...)
        local args = { ... }
        return coroutine.wrap(function() fn(table.unpack(args)) end)()
    end
end
if type(task.delay) ~= "function" then
    task.delay = function(t, fn, ...)
        local args = { ... }
        return coroutine.wrap(function()
            task.wait(t)
            fn(table.unpack(args))
        end)()
    end
end
if type(task.defer) ~= "function" then
    task.defer = function(fn, ...)
        local args = { ... }
        return coroutine.wrap(function()
            game:GetService("RunService").Heartbeat:Wait()
            fn(table.unpack(args))
        end)()
    end
end
if type(task.cancel) ~= "function" then
    task.cancel = function(thread)
        if type(thread) == "thread" and coroutine.status(thread) ~= "dead" then
            if coroutine.close then
                pcall(coroutine.close, thread)
            else
                pcall(function() coroutine.resume(thread) end)
            end
        end
    end
end
