_ZL.smoothLerp = function(a, b, t)
    a, b, t = tonumber(a) or 0, tonumber(b) or 0, tonumber(t) or 0
    return a + (b - a) * (1 - math.exp(-t * 5))
end
_ZL.throttle = function(signal, interval, fn)
    local last = 0
    return signal:Connect(function(...)
        local n = tick()
        if n - last >= interval then last = n
        fn(...) end
    end)
end
_ZL.lagStats = {
    fpsHistory = {},
    avgFPS = 120,
    lagStreak = 0,
    normalStreak = 0,
    lastGCTime = 0,
    gcInterval = 120,
    lowQuality = false,
    frameSkipCounter = 0,
    frameSkipRate = 0,
    janitorLastRun = 0,
}
local _COOLDOWN = {
    shadow    = 45,
    particle  = 25,
    streaming = 30,
    lod       = 20,
}
local _STATE = {
    shadow    = { supressed = false, lockedUntil = 0, origShadow = nil },
    particle  = { supressed = false, lockedUntil = 0, affected = {}, cachedDescendants = {} },
    streaming = { tightened = false, lockedUntil = 0, origMin = nil, origTarget = nil },
    lod       = { active = false, lockedUntil = 0, connections = {} },
}
local function _canToggle(kind)
    return tick() >= (_STATE[kind].lockedUntil or 0)
end
local function _lockToggle(kind, duration)
    _STATE[kind].lockedUntil = tick() + (duration or 20)
end
_ZL.autoLagManager = function(dt)
    local s   = _ZL.lagStats
    local fps = 1 / math.max(dt, 0.001)
    table.insert(s.fpsHistory, 1, fps)
    if #s.fpsHistory > 40 then table.remove(s.fpsHistory) end
    local sum = 0
    for _, v in ipairs(s.fpsHistory) do sum = sum + v end
    s.avgFPS = sum / #s.fpsHistory
    if s.avgFPS < 18 then
        s.lagStreak    = s.lagStreak + 1
        s.normalStreak = math.max(0, s.normalStreak - 1)
    elseif s.avgFPS > 50 then
        s.normalStreak = s.normalStreak + 1
        s.lagStreak    = math.max(0, s.lagStreak - 1)
    else
        s.lagStreak    = math.max(0, s.lagStreak - 0.4)
        s.normalStreak = math.max(0, s.normalStreak - 0.4)
    end
    if s.lagStreak >= 3 and not s.lowQuality then
        s.lowQuality    = true
        s.frameSkipRate = 1
        if _canToggle("streaming") then
            _ZL.tightenStreaming()
            _lockToggle("streaming", _COOLDOWN.streaming)
        end
        warn("[JEYHUB-ZL] FPS rendah ("..math.floor(s.avgFPS).."). Mode hemat aktif.")
    end
    if s.lagStreak >= 8 then
        s.frameSkipRate = 2
        if _canToggle("particle") then
            _ZL.suppressParticles()
            _lockToggle("particle", _COOLDOWN.particle)
        end
    end
    if s.lagStreak >= 15 then
        if _canToggle("lod") then
            _ZL.applyCharLOD()
            _lockToggle("lod", _COOLDOWN.lod)
        end
        local now = tick()
        if now - s.lastGCTime > 20 then
            s.lastGCTime = now
            task.defer(function()
                pcall(function() collectgarbage("step", 300) end)
            end)
        end
    end
    if s.normalStreak >= 5 and s.frameSkipRate > 0 then
        s.frameSkipRate = math.max(0, s.frameSkipRate - 1)
        s.normalStreak = 0
    end
    if s.normalStreak >= 10 then
        if _canToggle("lod") then _ZL.restoreCharLOD() end
    end
    if s.normalStreak >= 18 then
        if _canToggle("particle") then _ZL.restoreParticles() end
    end
    if s.normalStreak >= 30 then
        if _canToggle("streaming") then _ZL.restoreStreaming() end
        if s.lowQuality then
            s.lowQuality = false
            warn("[JEYHUB-ZL] FPS stabil. Semua mode hemat dimatikan.")
        end
    end
    local now = tick()
    if now - s.lastGCTime > s.gcInterval and s.avgFPS > 25 then
        s.lastGCTime = now
        task.defer(function()
            local before = collectgarbage("count")
            pcall(function() collectgarbage("step", 400) end)
            local freed = before - collectgarbage("count")
            if freed > 200 then
                warn("[JEYHUB-ZL] Auto-GC membebaskan "..math.floor(freed).." KB")
            end
        end)
    end
    if now - s.janitorLastRun > 15 then
        s.janitorLastRun = now
        if getgenv and getgenv().JEYHUB_CONNECTIONS then
            local alive = {}
            for _, conn in pairs(getgenv().JEYHUB_CONNECTIONS) do
                if typeof(conn) == "RBXScriptConnection" and conn.Connected then
                    table.insert(alive, conn)
                end
            end
            getgenv().JEYHUB_CONNECTIONS = alive
        end
    end
end
_ZL.shouldSkipFrame = function()
    local s = _ZL.lagStats
    if s.frameSkipRate <= 0 then return false end
    s.frameSkipCounter = s.frameSkipCounter + 1
    local cycle = s.frameSkipRate + 1
    return (s.frameSkipCounter % cycle) ~= 0
end
