    if not st.supressed or not _canToggle("shadow") then return end
    st.supressed = false
    pcall(function()
        local lighting = game:GetService("Lighting")
        lighting.GlobalShadows = (st.origShadow ~= nil) and st.origShadow or true
        pcall(function() lighting.ShadowSoftness = 1 end)
        pcall(function() lighting.EnvironmentDiffuseScale = 1 end)
        pcall(function() lighting.EnvironmentSpecularScale = 1 end)
        warn("[JEYHUB-ZL] Shadow dipulihkan.")
    end)
