_ZL.suppressParticles = function()
    local st = _STATE.particle
    if st.supressed or not _canToggle("particle") then return end
    st.supressed = true
    task.spawn(function()
        local ok, desc = pcall(function()
            return game:GetService("Workspace"):GetDescendants()
        end)
        if not ok or type(desc) ~= "table" then
            st.supressed = false
            return
        end
        local count   = 0
        local total   = #desc
        local i       = 1
        local CHUNK   = 30
        local MAX_HIT = 150
        while i <= total and count < MAX_HIT do
            local chunkEnd = math.min(i + CHUNK - 1, total)
            for j = i, chunkEnd do
                local v = desc[j]
                if v and v.Parent then
                    local ok2, isParticle = pcall(function()
                        return v:IsA("ParticleEmitter") or v:IsA("Trail") or v:IsA("Beam")
                    end)
                    if ok2 and isParticle then
                        local ok3, enabled = pcall(function() return v.Enabled end)
                        if ok3 and enabled then
                            pcall(function() v.Enabled = false end)
                            table.insert(st.affected, { obj = v, prev = true })
                            count = count + 1
                            if count >= MAX_HIT then break end
                        end
                    end
                end
            end
            i = chunkEnd + 1
            if i <= total then
                game:GetService("RunService").Heartbeat:Wait()
            end
        end
        st.cachedDescendants = {}
        if count > 0 then warn("[JEYHUB-ZL] "..count.." partikel dimatikan sementara.") end
    end)
end
_ZL.restoreParticles = function()
    local st = _STATE.particle
    if not st.supressed or not _canToggle("particle") then return end
    st.supressed = false
    task.defer(function()
        for _, entry in ipairs(st.affected) do
            pcall(function()
                if entry.obj and entry.obj.Parent then entry.obj.Enabled = entry.prev end
            end)
        end
        st.affected = {}
        warn("[JEYHUB-ZL] Partikel dipulihkan.")
    end)
end
_ZL.tightenStreaming = function()
    local st = _STATE.streaming
    if st.tightened or not _canToggle("streaming") then return end
    st.tightened = true
    pcall(function()
        local ws = game:GetService("Workspace")
        if not ws.StreamingEnabled then return end
        st.origMin    = ws.StreamingMinRadius
