_ZL.applyCharLOD = function()
    local st = _STATE.lod
    if st.active or not _canToggle("lod") then return end
    st.active = true
    task.defer(function()
        local Plrs  = game:GetService("Players")
        local lp    = Plrs.LocalPlayer
        local lpChar = lp and lp.Character
        local lpRoot = lpChar and lpChar:FindFirstChild("HumanoidRootPart")
        local count = 0
        for _, plr in ipairs(Plrs:GetPlayers()) do
            if plr ~= lp and plr.Character then
                local root = plr.Character:FindFirstChild("HumanoidRootPart")
                if root and lpRoot and (root.Position - lpRoot.Position).Magnitude > 60 then
                    local anim = plr.Character:FindFirstChildWhichIsA("Animator")
                    if anim then
                        pcall(function() anim.PlaybackSpeed = 0 end)
                        table.insert(st.connections, { anim = anim })
                        count = count + 1
                    end
                end
            end
        end
        if count > 0 then warn("[JEYHUB-ZL] LOD aktif " .. _CHR.EM_DASH .. " "..count.." animator diperlambat.") end
    end)
end
_ZL.restoreCharLOD = function()
    local st = _STATE.lod
    if not st.active or not _canToggle("lod") then return end
    st.active = false
    task.defer(function()
        for _, entry in ipairs(st.connections) do
            pcall(function()
                if entry.anim and entry.anim.Parent then entry.anim.PlaybackSpeed = 1 end
            end)
        end
        st.connections = {}
        warn("[JEYHUB-ZL] LOD karakter dinonaktifkan.")
    end)
end
