local _JEYHUB_SNOW_REGISTRY = {}
local _JEYHUB_SNOW_STARTED  = false
local function _SnowMasterStart()
    if _JEYHUB_SNOW_STARTED or not RunService then return end
    _JEYHUB_SNOW_STARTED = true
    local _fps      = 60
    local _fpsEMA   = 60
    local _UDim2    = UDim2.new
    local _mrand    = math.random
    local _snowSin  = math.sin
    local _snowPI2  = math.pi * 2
    local _snowExp  = math.exp
    local _snowRand = math.random
    local _snowClamp = math.clamp
    local _initDone = false
    local function _InitFlakeExtended()
        for _, sys in ipairs(_JEYHUB_SNOW_REGISTRY) do
            for _, f in ipairs(sys.flakes) do
                if not f._smooth then
                    f._smooth  = true
                    f._vx      = 0
                    f._vy      = 0
                    f._rx      = f.x
                    f._ry      = f.y
                    f._phase   = _snowRand() * _snowPI2
                    f._sway    = _snowRand() * 0.00028 + 0.00012
                    f._swayF   = _snowRand() * 0.20 + 0.12
                end
            end
        end
    end
    RunService.RenderStepped:Connect(function(dt)
        if not IsCurrentRun() then return end
        local safeDt   = math.max(dt, 0.0001)
        local frameFPS = 1 / safeDt
        _fpsEMA = _fpsEMA * 0.88 + frameFPS * 0.12
        _fps    = _fpsEMA
        if _fps < 10 then return end
        local cdt = safeDt * (1 - _snowExp(-safeDt * 24))
        cdt = _snowClamp(cdt, 0.0001, 0.025)
        local now = tick()
        if not _initDone and #_JEYHUB_SNOW_REGISTRY > 0 then
            _initDone = true
            _InitFlakeExtended()
        end
        for si = 1, #_JEYHUB_SNOW_REGISTRY do
            local sys = _JEYHUB_SNOW_REGISTRY[si]
            if sys.guardFn() then
                local fl  = sys.flakes
                local sy  = sys.sy
                local sx  = sys.sx
                local mxY = sys.mxY
                local rsY = sys.rsY
                for i = 1, #fl do
                    local f = fl[i]
                    if f._smooth then
                        local sway = _snowSin(now * f._swayF * _snowPI2 + f._phase) * f._sway * sx
                        local tvx = (f.drift + sway) * sx
                        local tvy = f.speed * sy
                        local lerpK = 1 - _snowExp(-cdt * 18)
                        f._vx = f._vx + (tvx - f._vx) * lerpK
                        f._vy = f._vy + (tvy - f._vy) * lerpK
                        local ny = f.y + f._vy * cdt
                        local nx = f.x + f._vx * cdt
                        if ny > mxY then
                            ny = rsY
                            nx = _snowRand()
                            f._vx = 0
                            f._vy = 0
                            f._rx = nx
                            f._ry = ny
                        end
                        if nx < -0.02 then nx = 1.02 elseif nx > 1.02 then nx = -0.02 end
                        f.y = ny
                        f.x = nx
                        local rk = 1 - _snowExp(-cdt * 55)
                        f._rx = f._rx + (nx - f._rx) * rk
                        f._ry = f._ry + (ny - f._ry) * rk
                        f.frame.Position = _UDim2(f._rx, 0, f._ry, 0)
                    else
                        local ny = f.y + f.speed * cdt * sy
                        local nx = f.x + f.drift * cdt * sx
                        if ny > mxY then ny = rsY
                        nx = _mrand() end
                        if nx < -0.02 then nx = 1.02 elseif nx > 1.02 then nx = -0.02 end
                        f.y = ny
                        f.x = nx
                        f.frame.Position = _UDim2(nx, 0, ny, 0)
                    end
                end
            end
        end
    end)
end
