                and typeof(KillFunc) == "function" and not _acKill then
                _acKill = KillFunc
                pcall(function()
                    hookfunction(_acKill, function(Info)
                    end)
                end)
                table.insert(_acHooked, _acKill)
            end
        end
    end
    pcall(function()
        local _dbgOld
        _dbgOld = hookfunction(getrenv().debug.info, newcclosure(function(a, ...)
            local LevelOrFunc = a
            if _acDetected and LevelOrFunc == _acDetected then
