local function New(class, props, children)
    if type(class) ~= "string" or class == "" then
        local okFolder, folder = pcall(Instance.new, "Folder")
        if okFolder and folder then return folder end
        return {}
    end
    local ok, inst = pcall(Instance.new, class)
    if not ok or not inst then
        local okFolder, folder = pcall(Instance.new, "Folder")
        if okFolder and folder then return folder end
        return {}
    end
    pcall(function()
        local isGui = inst:IsA("GuiObject")
        if isGui then inst.BorderSizePixel = 0 end
        if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
            inst.RichText = true
        end
        if props then
            for k, v in pairs(props) do
                pcall(function() inst[k] = v end)
            end
        end
        if children then
            for _, c in ipairs(children) do
                pcall(function() c.Parent = inst end)
            end
        end
    end)
    return inst
end
local _UI_SMOOTH_T   = 2.1
local _UI_EASING     = Enum.EasingStyle.Exponential
local _UI_EASING_DIR = Enum.EasingDirection.Out
local _tweenInfoCache = {}
local function GetTweenInfo(time, style, dir)
    local t = (time or 0.2) * _UI_SMOOTH_T
    local s = style or _UI_EASING
    local d = dir or _UI_EASING_DIR
    if s == Enum.EasingStyle.Quint then s = _UI_EASING end
    if s == Enum.EasingStyle.Quart then s = _UI_EASING end
    local key = t .. "_" .. tostring(s) .. "_" .. tostring(d)
    if not _tweenInfoCache[key] then
        _tweenInfoCache[key] = TweenInfo.new(t, s, d)
    end
    return _tweenInfoCache[key]
end
local function Tween(inst, time, style, dir, props)
    if not inst or not props then return nil end
    local info = GetTweenInfo(time, style, dir)
    local ok, tw = pcall(TweenService.Create, TweenService, inst, info, props)
    if ok and tw then
        tw:Play()
        return tw
    end
    pcall(function()
        for k, v in pairs(props) do inst[k] = v end
    end)
    return nil
end
local _loopTweenInfoCache = {}
local function LoopTween(inst, time, props, style)
    if not inst or not props then return nil end
    local ok, result = pcall(function()
        local t = time or 3
        local s = style or Enum.EasingStyle.Sine
        local key = t .. "_" .. tostring(s)
        if not _loopTweenInfoCache[key] then
            _loopTweenInfoCache[key] = TweenInfo.new(t * _UI_SMOOTH_T, s, Enum.EasingDirection.InOut, -1, true, 0)
        end
        local tw = TweenService:Create(inst, _loopTweenInfoCache[key], props)
        tw:Play()
        return tw
    end)
    if ok then return result end
    return nil
end
