    local btn = New("TextButton", {
        Text = config.ButtonText or "Run",
        Font = Enum.Font.GothamMedium,
        TextSize = 12,
        TextColor3 = Color3.fromRGB(10, 10, 10),
        AutoButtonColor = false,
        BackgroundColor3 = Color3.new(1, 1, 1),
        Size = UDim2.new(0, 56, 0, 24),
        Position = UDim2.new(1, -64, 0.5, -12),
        Parent = root,
    })
    Round(btn, 6)
    local btnGradient = New("UIGradient", {
        Color = ColorSequence.new(BUTTON_COLOR, BUTTON_COLOR_DARK),
        Rotation = 135,
        Parent = btn,
    })
    local sheen = New("Frame", {
        Size = UDim2.new(1, 0, 0.5, 0),
        BackgroundColor3 = Color3.new(0.9961, 0.9961, 0.9961),
