    end
    local svBox = New("Frame", {
        Size = UDim2.new(1, 0, 0, 70),
        BackgroundColor3 = Color3.fromRGB(23, 23, 23),
        ZIndex = 6,
        Parent = popup,
    })
    Round(svBox, 6)
    local satGradient = New("UIGradient", {
        Color = ColorSequence.new(Color3.fromRGB(254, 254, 254), Color3.fromRGB(254, 254, 254)),
