    Round(svCursorShadow, 6)
    local svCursor = New("Frame", {
        Size = UDim2.new(0,8,0,8), AnchorPoint = Vector2.new(0.5,0.5),
        Position = UDim2.new(1,0,0,0), BackgroundColor3 = Color3.new(0.9961, 0.9961, 0.9961),
        ZIndex = 7, Parent = svBox,
    })
    Round(svCursor, 4)
    Stroke(svCursor, Color3.new(0.0000, 0.0000, 0.0000), 1, 0)
    local hueBar = New("Frame", {
        Size = UDim2.new(1, 0, 0, 14),
        Position = UDim2.new(0, 0, 0, 78),
        ZIndex = 6,
        Parent = popup,
    })
    Round(hueBar, 6)
    New("UIGradient", {
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0.00, Color3.fromRGB(23, 23, 23)),
            ColorSequenceKeypoint.new(0.17, Color3.fromRGB(230, 230, 230)),
            ColorSequenceKeypoint.new(0.33, Color3.fromRGB(135, 135, 135)),
            ColorSequenceKeypoint.new(0.50, Color3.fromRGB(172, 172, 172)),
            ColorSequenceKeypoint.new(0.67, Color3.fromRGB(7, 7, 7)),
            ColorSequenceKeypoint.new(0.83, Color3.fromRGB(32, 32, 32)),
