    })
    local hueCursor = New("Frame", {
        Size = UDim2.new(0,3,1,4), AnchorPoint = Vector2.new(0.5,0.5),
        Position = UDim2.new(0,0,0.5,0), BackgroundColor3 = Color3.new(0.9961, 0.9961, 0.9961),
        ZIndex = 7, Parent = hueBar,
    })
    Round(hueCursor, 2)
    local hexLabel = New("TextLabel", {
        Text = "", Font = Enum.Font.GothamMedium, TextSize = 10,
        TextColor3 = Palette.Text, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.new(0, 0, 0, 98), Size = UDim2.new(1, 0, 0, 14),
        ZIndex = 6, Parent = popup,
    })
    local rgbLabel = New("TextLabel", {
        Text = "", Font = Enum.Font.Gotham, TextSize = 9,
        TextColor3 = Palette.SubText, BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.new(0, 0, 0, 114), Size = UDim2.new(1, 0, 0, 14),
        ZIndex = 6, Parent = popup,
    })
    local okInitHSV, hue, sat, val = pcall(function() return current:ToHSV() end)
    if not okInitHSV then hue, sat, val = 0.75, 1, 1 end
