    local function MakePagesSnowFlake(randomY)
        local sz    = math.random(2, 5)
        local xPos  = math.random(0, 1000) / 1000
        local yPos  = randomY and (math.random(0, 1000) / 1000) or (-math.random(10, 150) / 1000)
        local speed = math.random(8, 22) / 1000
        local drift = (math.random(-10, 10)) / 10000
        local alpha = math.random(35, 70) / 100
        local flake = New("Frame", {
            Size                   = UDim2.new(0, sz, 0, sz),
            Position               = UDim2.new(xPos, 0, yPos, 0),
            AnchorPoint            = Vector2.new(0.5, 0.5),
            BackgroundColor3       = Color3.new(1, 1, 1),
            BackgroundTransparency = alpha,
            ZIndex                 = 200,
            Parent                 = pagesSnowCanvas,
        })
        New("UICorner", { CornerRadius = UDim.new(1, 0), Parent = flake })
        return { frame = flake, x = xPos, y = yPos, speed = speed, drift = drift }
    end
