function Library.new(title, subtitle)
    local ok, result = pcall(Library.newImpl, title, subtitle)
    if ok and result then return result end
    warn("[JEYHUB] Window creation failed entirely (caught safely):", result)
    return setmetatable({ Tabs = {}, CurrentTab = nil }, Library)
end
local function GetSidebarTooltip(library)
    if library.SidebarTooltip then return library.SidebarTooltip end
    if not library.Main then return nil end
    local tooltip = New("TextLabel", {
        Font = Enum.Font.GothamMedium, TextSize = 11,
        TextColor3 = Palette.Text,
        BackgroundColor3 = Palette.Glass,
        BackgroundTransparency = 0.05,
        AutomaticSize = _AutomaticSizeX or Enum.AutomaticSize.X,
        Size = UDim2.new(0, 0, 0, 24),
        Visible = false,
        ZIndex = 50,
        TextXAlignment = Enum.TextXAlignment.Center,
        Parent = library.Main,
    })
    Round(tooltip, 6)
    Stroke(tooltip, Palette.Accent, 1, 0.4)
    Pad(tooltip, 8, 8, 0, 0)
    library.SidebarTooltip = tooltip
    return tooltip
end
function Library:CreateTabImpl(name)
    if not self.Sidebar then
        return {
            CreateSection = function() return setmetatable({ Body = Instance.new("Folder") }, Section) end,
            OnBuild = function() end,
        }
    end
    name = tostring(name or "Tab")
    local accent = TabAccents[name] or Palette.Accent
    local btn = New("TextButton", {
        Size = UDim2.new(1, 0, 0, 38),
        BackgroundColor3 = Palette.Element,
        BackgroundTransparency = 0.2,
        Text = "",
        Parent = self.Sidebar,
    })
    Round(btn, 9)
    local btnGlow = Stroke(btn, accent, 1, 1)
    local tick = New("Frame", {
        Size = UDim2.new(0, 3, 0, 16),
        Position = UDim2.new(0, 3, 0.5, -8),
        BackgroundColor3 = accent,
        BackgroundTransparency = 1,
        Parent = btn,
    })
    Round(tick, 2)
    New("UIGradient", {
        Color = ColorSequence.new(accent, Color3.new(0.9961, 0.9961, 0.9961)),
        Rotation = 90,
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0),
            NumberSequenceKeypoint.new(1, 0.5),
        }),
        Parent = tick,
    })
    local icon  = TabIcons[name]
    local label = nil
    if icon == "__search_icon__" then
        local iconHolder = New("Frame", {
            Size            = UDim2.fromOffset(18, 18),
            AnchorPoint     = Vector2.new(0.5, 0.5),
            Position        = UDim2.new(0.5, 2, 0.5, 0),
            BackgroundTransparency = 1,
            Parent          = btn,
        })
        local ring = New("Frame", {
            Size                 = UDim2.fromOffset(11, 11),
            Position             = UDim2.new(0, 0, 0, 0),
            BackgroundTransparency = 1,
            Parent               = iconHolder,
