            end)
            library._pageOutTween = Tween(prevPage, OUT_TIME, Enum.EasingStyle.Exponential, Enum.EasingDirection.In, {
                Position = SLIDE_OFF,
            })
            local capturedToken = myToken
            task.delay(OUT_TIME + 0.06, function()
                if library._tabSwitchToken ~= capturedToken then return end
                if capturedPrev.Page then
                    pcall(function()
                        capturedPrev.Page.Visible  = false
                        capturedPrev.Page.Position = UDim2.new(0, 0, 0, 0)
                        capturedPrev.Page.ZIndex   = 1
                    end)
                end
                library._pageOutTween = nil
            end)
        end
        pcall(function()
            page.Position = SLIDE_OFF
            page.Visible  = true
            page.ZIndex   = 3
        end)
        library._pageActiveTween = Tween(page, IN_TIME, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out, {
            Position = UDim2.new(0, 0, 0, 0),
        })
        local capturedToken2 = myToken
        task.delay(IN_TIME + 0.06, function()
            if library._tabSwitchToken ~= capturedToken2 then return end
            pcall(function()
                if page and page.Parent then
