    local function _RebuildFavList()
        for _, ch in ipairs(favScroll:GetChildren()) do
            if ch:IsA("TextButton") then pcall(function() ch:Destroy() end) end
        end
        local n = _FavCount()
        favEmptyLbl.Visible = (n == 0)
        local rows  = math.min(n, 5)
        local dropH = (rows > 0) and (rows * 30 - 4 + 14) or 36
        favDropdown.Size = UDim2.new(1, -20, 0, dropH)
        favListBtn.Text = (_favDropdownOpen and CHR_FAV_OPEN or CHR_FAV_CLOSE)
            .. " Favorit (" .. tostring(n) .. ")"
        local order = 2
        local _favNeedsSave = false
        for uid, info in pairs(JH_Favorites) do
            local _uid  = uid
            local _info = info
            local function _isRawId(s) return type(s) == "string" and s:match("^%d+$") ~= nil end
            local _resolvedName        = _info.name
            local _resolvedDisplayName = _info.displayName
            local _liveP; pcall(function()
                if Players then _liveP = Players:GetPlayerByUserId(_uid) end
            end)
            if _liveP then
                _resolvedName        = _liveP.Name
                _resolvedDisplayName = (_liveP.DisplayName ~= "" and _liveP.DisplayName) or _liveP.Name
            else
                local _c = PlayerCache and PlayerCache[_uid]
                local _s = _c and _c.snapshot
                if _s then
                    if type(_s.name) == "string" and not _isRawId(_s.name) then
                        _resolvedName = _s.name
                    end
                    if type(_s.displayName) == "string" and not _isRawId(_s.displayName) then
                        _resolvedDisplayName = _s.displayName
                    end
                end
            end
            if _resolvedName ~= _info.name or _resolvedDisplayName ~= _info.displayName then
                _info.name        = _resolvedName
                _info.displayName = _resolvedDisplayName
                JH_Favorites[_uid] = _info
                _favNeedsSave = true
            end
            local _showDisplayName = _resolvedDisplayName or _resolvedName or tostring(_uid)
            local _showUsername    = _resolvedName or tostring(_uid)
            local entry = New("TextButton", {
                BackgroundColor3 = Palette.Element,
                BackgroundTransparency = 0.2,
                Size = UDim2.new(1, 0, 0, 26),
