                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                ZIndex = 13,
                Parent = entry,
            })
            local STATUS_TEXT  = {
                inmap   = "In Map",
                ingame  = "In Game",
                inweb   = "In Web",
                offline = "Offline",
                unknown = "...",
            }
            local STATUS_COLOR = {
                inmap   = Color3.fromRGB(74,  222, 128),
                ingame  = Color3.fromRGB(250, 204, 21),
                inweb   = Color3.fromRGB(96,  165, 250),
                offline = Color3.fromRGB(120, 120, 120),
                unknown = Color3.fromRGB(80,  80,  80),
            }
            local statusLbl = New("TextLabel", {
                BackgroundTransparency = 1,
