                TextSize = 7,
                TextXAlignment = Enum.TextXAlignment.Right,
                TextTruncate   = Enum.TextTruncate.AtEnd,
                ZIndex = 13,
                Parent = entry,
            })
            local function _SetStatus(key)
                pcall(function()
                    statusLbl.Text       = STATUS_TEXT[key]  or STATUS_TEXT.unknown
                    statusLbl.TextColor3 = STATUS_COLOR[key] or STATUS_COLOR.unknown
                end)
            end
            local _cache = PlayerCache and PlayerCache[_uid]
            if _liveP then
                _SetStatus("inmap")
                if _cache then _cache.online = true end
            elseif _cache and _cache.online then
                _SetStatus("inmap")
            elseif _cache and _cache.presenceType ~= nil then
                local pt = _cache.presenceType
                if     pt == 0 then _SetStatus("offline")
                elseif pt == 1 then _SetStatus("inweb")
                elseif pt == 2 then _SetStatus("ingame")
                else               _SetStatus("offline")
                end
            else
                local _entryRef2  = entry
                local _statusRef  = statusLbl
                local _capUid2    = _uid
                task.spawn(function()
                    local _nowLive = false
                    pcall(function()
                        if Players then _nowLive = Players:GetPlayerByUserId(_capUid2) ~= nil end
                    end)
                    if _nowLive then
                        local sv0 = false
                        pcall(function() sv0 = _entryRef2.Parent ~= nil end)
                        if sv0 then _SetStatus("inmap") end
                        if PlayerCache and PlayerCache[_capUid2] then
                            PlayerCache[_capUid2].online = true
                        end
                        return
                    end
                    local ok, resp = pcall(DoHttpRequestGlobal, {
                        Url     = "https://presence.roblox.com/v1/presence/users",
                        Method  = "POST",
                        Headers = { ["Content-Type"] = "application/json" },
                        Body    = '{"userIds":[' .. tostring(_capUid2) .. ']}',
                    })
                    if not ok or type(resp) ~= "table" then return end
                    local body = resp.Body or resp.body or ""
                    if type(body) ~= "string" or body == "" then return end
                    local okD, data = pcall(function() return HttpService:JSONDecode(body) end)
                    if not okD or type(data) ~= "table" then return end
                    if type(data.userPresences) ~= "table" or #data.userPresences == 0 then return end
                    local pType = tonumber(data.userPresences[1].userPresenceType)
                    if PlayerCache then
                        if not PlayerCache[_capUid2] then
                            PlayerCache[_capUid2] = { online = false }
                        end
                        PlayerCache[_capUid2].presenceType = pType
                    end
                    local stillValid = false
                    pcall(function() stillValid = _entryRef2.Parent ~= nil end)
                    if not stillValid then return end
                    local _stillLive = false
                    pcall(function()
                        if Players then _stillLive = Players:GetPlayerByUserId(_capUid2) ~= nil end
                    end)
                    if _stillLive then
                        _SetStatus("inmap")
                    elseif pType == 0 then _SetStatus("offline")
                    elseif pType == 1 then _SetStatus("inweb")
                    elseif pType == 2 then _SetStatus("ingame")
                    else               _SetStatus("offline")
                    end
                end)
            end
            if _isRawId(_resolvedName) then
                local _entryRef = entry
                local _dispRef  = _dispLbl
                local _userRef  = _userLbl
                local _capUid   = _uid
                task.spawn(function()
                    local body = SafeHttpGet(
                        "https://users.roblox.com/v1/users/" .. tostring(_capUid)
                    )
                    if not body then return end
                    local okD, d = pcall(function()
                        return HttpService:JSONDecode(body)
                    end)
                    if not okD or type(d) ~= "table" then return end
                    local fetchedName = type(d.name) == "string" and d.name ~= "" and d.name
                    if not fetchedName then return end
                    local fetchedDisplay = (type(d.displayName) == "string"
                                           and d.displayName ~= ""
                                           and d.displayName) or fetchedName
                    local stillValid = false
                    pcall(function() stillValid = _entryRef.Parent ~= nil end)
                    if stillValid then
                        pcall(function() _dispRef.Text = fetchedDisplay end)
                        pcall(function() _userRef.Text = "@" .. fetchedName end)
                    end
                    if JH_Favorites[_capUid] then
                        JH_Favorites[_capUid].name        = fetchedName
                        JH_Favorites[_capUid].displayName = fetchedDisplay
                        _SaveFavorites()
                    end
                end)
            end
            local remBtn = New("TextButton", {
                BackgroundTransparency = 1,
                Position = UDim2.new(1, -24, 0.5, -9),
                Size = UDim2.new(0, 20, 0, 18),
                Font = Enum.Font.GothamBold,
                Text = _CHR.MULTIPLY,
                TextColor3 = Color3.fromRGB(220, 80, 80),
                TextSize = 11,
                ZIndex = 14,
                Parent = entry,
            })
            SafeConnect(GetSignal(entry, "MouseButton1Click"), function()
                _favDropdownOpen = false
                favDropdown.Visible = false
                favListBtn.Text = CHR_FAV_CLOSE .. " Favorit (" .. tostring(_FavCount()) .. ")"
                local _navUid = _uid
                task.defer(function()
                    for i, uid2 in ipairs(TargetPlayers) do
                        if uid2 == _navUid then
                            CurrentTargetIndex = i
                            H.UpdateTargetUI()
                            task.defer(function()
                                if ApplySpectateCamera then ApplySpectateCamera() end
                            end)
                            return
                        end
                    end
                    if not PlayerCache[_navUid] then
                        PlayerCache[_navUid] = {
                            online   = false,
                            snapshot = {
                                userId      = _navUid,
                                name        = _info.name,
                                displayName = _info.displayName,
                            },
                        }
                    end
                    if not PlayerCache[_navUid].snapshot.name or PlayerCache[_navUid].snapshot.name == tostring(_navUid) then
                        PlayerCache[_navUid].snapshot.name        = _info.name
                        PlayerCache[_navUid].snapshot.displayName = _info.displayName
                    end
                    if not H.seenInOfflineOrder(_navUid) then
                        table.insert(OfflineOrder, _navUid)
                    end
                    H.RefreshPlayerList()
                    local found = false
                    for i, uid2 in ipairs(TargetPlayers) do
                        if uid2 == _navUid then
                            CurrentTargetIndex = i
                            H.UpdateTargetUI()
                            task.defer(function()
                                if ApplySpectateCamera then ApplySpectateCamera() end
                            end)
                            found = true
                            break
                        end
                    end
                    if not found then
                        H.UpdateTargetUI()
                    end
                end)
            end)
            SafeConnect(GetSignal(remBtn, "MouseButton1Click"), function()
                JH_Favorites[_uid] = nil
                _SaveFavorites()
                _RebuildFavList()
                if H._joinTargetUserId == _uid then
                    starBtn.Text = CHR_STAR_EMPTY .. " Favorit"
                    starBtn.TextColor3 = Palette.SubText
                end
            end)
            order = order + 1
        end
        if _favNeedsSave then _SaveFavorites() end
    end
    SafeConnect(GetSignal(favListBtn, "MouseButton1Click"), function()
        _favDropdownOpen = not _favDropdownOpen
        if _favDropdownOpen then _RebuildFavList() end
        favDropdown.Visible = _favDropdownOpen
        favListBtn.Text = (_favDropdownOpen and CHR_FAV_OPEN or CHR_FAV_CLOSE)
            .. " Favorit (" .. tostring(_FavCount()) .. ")"
    end)
    SafeConnect(GetSignal(starBtn, "MouseButton1Click"), function()
        local uid = H._joinTargetUserId
        if not uid then return end
        if JH_Favorites[uid] then
            JH_Favorites[uid] = nil
            starBtn.Text = CHR_STAR_EMPTY .. " Favorit"
            starBtn.TextColor3 = Palette.SubText
        else
            local c    = PlayerCache and PlayerCache[uid]
            local snap = c and c.snapshot
            local _liveP; pcall(function() _liveP = Players and Players:GetPlayerByUserId(uid) end)
            local _pName = (_liveP and _liveP.Name)
                        or (snap and type(snap.name) == "string" and snap.name ~= tostring(uid) and snap.name)
                        or (snap and snap.name)
                        or tostring(uid)
            local _pDisplayName = (_liveP and _liveP.DisplayName ~= "" and _liveP.DisplayName)
                               or (snap and type(snap.displayName) == "string" and snap.displayName ~= tostring(uid) and snap.displayName)
                               or (snap and snap.displayName)
                               or _pName
            JH_Favorites[uid] = {
                name        = _pName,
                displayName = _pDisplayName,
            }
            starBtn.Text = CHR_STAR_FILLED .. " Difavoritkan"
            starBtn.TextColor3 = Color3.fromRGB(250, 204, 21)
            if _pName == tostring(uid) then
                local _capStarUid = uid
                task.spawn(function()
                    local body = SafeHttpGet(
                        "https://users.roblox.com/v1/users/" .. tostring(_capStarUid)
                    )
                    if not body then return end
                    local okD, d = pcall(function() return HttpService:JSONDecode(body) end)
                    if not okD or type(d) ~= "table" then return end
                    local fetchedName = type(d.name) == "string" and d.name ~= "" and d.name
                    if not fetchedName then return end
                    local fetchedDisplay = (type(d.displayName) == "string"
                                           and d.displayName ~= ""
                                           and d.displayName) or fetchedName
                    if JH_Favorites[_capStarUid] then
                        JH_Favorites[_capStarUid].name        = fetchedName
                        JH_Favorites[_capStarUid].displayName = fetchedDisplay
                        _SaveFavorites()
                        if _favDropdownOpen then _RebuildFavList() end
                    end
                end)
            end
        end
        _SaveFavorites()
        favListBtn.Text = (_favDropdownOpen and CHR_FAV_OPEN or CHR_FAV_CLOSE)
            .. " Favorit (" .. tostring(_FavCount()) .. ")"
        if _favDropdownOpen then _RebuildFavList() end
    end)
