    function H.MakeChip(parent, text, bg, glowColor)
        local chip = New("Frame", {
            BackgroundColor3 = bg or accent,
            BackgroundTransparency = 0.05,
            Size = UDim2.new(0, 0, 0, 16),
            AutomaticSize = _AutomaticSizeX or Enum.AutomaticSize.X,
            Visible = false,
            Parent = parent,
        })
        Round(chip, 8)
        New("UIPadding", { PaddingLeft = UDim.new(0, 7), PaddingRight = UDim.new(0, 7), Parent = chip })
        local chipGrad = New("UIGradient", {
            Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)),
                ColorSequenceKeypoint.new(1, Color3.new(0.55, 0.55, 0.55)),
            }),
            Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0.22),
                NumberSequenceKeypoint.new(1, 0.04),
            }),
            Rotation = 90,
            Parent = chip,
        })
        New("UIStroke", {
            Color = glowColor or bg or accent,
            Thickness = 1,
            Transparency = 0.38,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            Parent = chip,
        })
        local chipLabel = New("TextLabel", {
            BackgroundTransparency = 1,
            Size = UDim2.new(0, 0, 1, 0),
            AutomaticSize = _AutomaticSizeX or Enum.AutomaticSize.X,
            Font = Enum.Font.GothamBold,
            Text = text or "",
            TextColor3 = Color3.new(1, 1, 1),
            TextSize = 8,
            Parent = chip,
        })
        return chip, chipLabel, chipGrad
    end
