    function H.AddGameRow(order, label)
        local rowFrame = New("Frame", {
            Size = UDim2.new(1, 0, 0, 40),
            BackgroundColor3 = Palette.Glass,
            BackgroundTransparency = 0.5,
            LayoutOrder = order,
            Parent = infoCard,
        })
        Round(rowFrame, 10)
        Stroke(rowFrame, accent, 1, 0.75)
        Pad(rowFrame, 10, 10, 6, 6)
        New("TextLabel", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 12),
            Font = Enum.Font.GothamBold,
            Text = string.upper(label),
            TextColor3 = Palette.SubText,
            TextSize = 8,
            TextXAlignment = Enum.TextXAlignment.Left,
            Parent = rowFrame,
        })
        local gameLbl = New("TextLabel", {
            BackgroundTransparency = 1,
            Position = UDim2.new(0, 0, 0, 15),
            Size = UDim2.new(1, -68, 0, 17),
            Font = Enum.Font.GothamBold,
            Text = "-",
            TextColor3 = Palette.Text,
            TextSize = 10.5,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            Parent = rowFrame,
        })
        local joinBtn = New("TextButton", {
            Position = UDim2.new(1, -62, 0, 13),
            Size = UDim2.new(0, 62, 0, 20),
            BackgroundColor3 = Color3.fromRGB(22, 163, 74),
            Font = Enum.Font.GothamBold,
            Text = "\xE2\x96\xB6  JOIN",
            TextColor3 = Color3.fromRGB(187, 247, 208),
            TextSize = 9,
            Visible = false,
            Parent = rowFrame,
        })
        Round(joinBtn, 6)
        New("UIStroke", {
            Color = Color3.fromRGB(74, 222, 128),
            Thickness = 1,
            Transparency = 0.38,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            Parent = joinBtn,
        })
        AddButtonHover(joinBtn)
        SafeConnect(GetSignal(joinBtn, "MouseButton1Click"), function()
            local uid = H._joinTargetUserId
            local c   = uid and PlayerCache and PlayerCache[uid]
            if not c then return end
            local placeId = c.presencePlaceId
            local gameId  = c.presenceGameId
            task.spawn(function()
                local ok_svc, TpSvc = pcall(function() return game:GetService("TeleportService") end)
                if not ok_svc or not TpSvc then return end
                local lp = game:GetService("Players").LocalPlayer
                if not lp then return end
                local teleportStarted = false
                local monitorConn
                pcall(function()
                    monitorConn = lp.OnTeleport:Connect(function(state)
                        if state == Enum.TeleportState.Started
                        or state == Enum.TeleportState.InProgress
                        or state == Enum.TeleportState.RequestedFromServer then
                            teleportStarted = true
                        end
                    end)
                end)
                local isSameGame = (placeId ~= nil and placeId == game.PlaceId)
                if placeId and gameId then
                    pcall(function()
                        TpSvc:TeleportToPlaceInstance(placeId, gameId, lp)
                    end)
                end
                task.wait(isSameGame and 2 or 6)
                pcall(function()
                    if monitorConn then monitorConn:Disconnect() end
                end)
                if teleportStarted then return end
                if not isSameGame and placeId then
                    pcall(function()
                        TpSvc:Teleport(placeId, lp)
                    end)
                    task.wait(3)
                    if teleportStarted then return end
                end
                if uid then
                    pcall(function()
                        TpSvc:TeleportFollowUser(uid)
                    end)
                end
            end)
        end)
        table.insert(statToggleFrames, rowFrame)
        return gameLbl, joinBtn, rowFrame
    end
