        task.spawn(function()
        task.wait(SOCIAL_FETCH_DEBOUNCE)
        if myGen ~= profileGen then return end
        lastSocialFetchTick[userId] = tick()
        UsersQueue.Enqueue(function()
            local body = SafeHttpGet("https://users.roblox.com/v1/users/" .. tostring(userId))
            local bioText = nil
