        PresenceQueue.Enqueue(function()
            local text_status, text_lastonline, text_lastgame = nil, nil, nil
            local PRESENCE_TYPES = { [0]="Offline", [1]="On Website", [2]="In-Game", [3]="In Studio", [4]="Invisible" }
            local ok, resp = pcall(DoHttpRequestGlobal, {
                Url     = "https://presence.roblox.com/v1/presence/users",
                Method  = "POST",
                Headers = { ["Content-Type"] = "application/json" },
                Body    = (HttpService and pcall(function() return HttpService:JSONEncode({ userIds = { userId } }) end) and HttpService:JSONEncode({ userIds = { userId } }))
                          or ('{"userIds":[' .. tostring(userId) .. ']}'),
            })
            local parsed_pType        = nil
            local parsed_gameName     = nil
            local parsed_placeId      = nil
            local parsed_gameId       = nil
            local parsed_universeId   = nil
            local parsed_joinable     = false
            if ok and type(resp) == "table" then
                local body = resp.Body or resp.body or ""
                if type(body) == "string" and body ~= "" then
                    local okD, data = pcall(function() return HttpService:JSONDecode(body) end)
                    if okD and type(data) == "table" and type(data.userPresences) == "table" and #data.userPresences > 0 then
                        local p = data.userPresences[1]
                        local pType = tonumber(p.userPresenceType)
                        parsed_pType = pType
                        text_status = PRESENCE_TYPES[pType] or ("Type " .. tostring(pType))
                        if type(p.lastOnline) == "string" and p.lastOnline ~= "" then
                            local yr,mo,dy,hr,mn = p.lastOnline:match("(%d+)-(%d+)-(%d+)T(%d+):(%d+)")
                            text_lastonline = yr and (yr.."/"..mo.."/"..dy.." "..hr..":"..mn.." UTC") or p.lastOnline
                        else
                            text_lastonline = "Unknown"
                        end
                        if type(p.lastLocation) == "string" and p.lastLocation ~= "" then
                            parsed_gameName = p.lastLocation
                        end
                        if type(p.placeId) == "number" and p.placeId ~= 0 then
                            parsed_placeId = p.placeId
                        end
                        if type(p.gameId) == "string" and p.gameId ~= "" and p.gameId ~= "0" then
                            parsed_gameId = p.gameId
                        end
                        if type(p.universeId) == "number" and p.universeId ~= 0 then
                            parsed_universeId = p.universeId
                        end
                        parsed_joinable = (pType == 2 and parsed_placeId ~= nil and parsed_gameId ~= nil)
                        local locParts = {}
                        if parsed_gameName then table.insert(locParts, parsed_gameName) end
                        if parsed_placeId  then table.insert(locParts, "PlaceId: " .. tostring(parsed_placeId)) end
                        if parsed_gameId   then table.insert(locParts, "Server: " .. parsed_gameId) end
                        if parsed_universeId then table.insert(locParts, "UniverseId: " .. tostring(parsed_universeId)) end
                        text_lastgame = (#locParts > 0) and table.concat(locParts, " | ") or "None / Private"
                    end
                end
            end
            if myGen == profileGen then
                local c = PlayerCache and PlayerCache[userId]
                if c then
                    c.presenceType      = parsed_pType
                    c.presenceGameName  = parsed_gameName
                    c.presencePlaceId   = parsed_placeId
                    c.presenceGameId    = parsed_gameId
                    c.presenceUniverseId = parsed_universeId
                    c.presenceJoinable  = parsed_joinable
                end
                if Stats.statPresenceStatus     then Stats.statPresenceStatus.Text     = text_status    or "Unavailable" end
                if Stats.statPresenceLastOnline then Stats.statPresenceLastOnline.Text = text_lastonline or "Unavailable" end
                if Stats.statPresenceLastGame   then Stats.statPresenceLastGame.Text   = text_lastgame   or "Unavailable" end
                if PersistExtendedField then
                    PersistExtendedField(userId, "presenceStatus",    text_status    or "-")
                    PersistExtendedField(userId, "presenceLastOnline", text_lastonline or "-")
                    PersistExtendedField(userId, "presenceLastGame",   text_lastgame   or "-")
                end
                pcall(function()
                    H.RefreshGameRow(userId)
                    local cc = PlayerCache and PlayerCache[userId]
                    if cc and not cc.online and acctStatusChip and parsed_pType ~= nil then
                        local PRESENCE_LABELS = { [0]="OFFLINE", [1]="ON WEB", [2]="IN-GAME", [3]="IN STUDIO", [4]="INVISIBLE" }
                        local PRESENCE_BG     = { [0]=Color3.fromRGB(185,28,28), [1]=Color3.fromRGB(37,99,235), [2]=Color3.fromRGB(22,163,74), [3]=Color3.fromRGB(109,40,217), [4]=Color3.fromRGB(64,64,64) }
                        local PRESENCE_TEXT   = { [0]=Color3.fromRGB(254,202,202), [1]=Color3.fromRGB(147,197,253), [2]=Color3.fromRGB(187,247,208), [3]=Color3.fromRGB(196,181,253), [4]=Color3.fromRGB(180,180,180) }
                        local PRESENCE_GLOW   = { [0]=Color3.fromRGB(248,113,113), [1]=Color3.fromRGB(96,165,250), [2]=Color3.fromRGB(74,222,128), [3]=Color3.fromRGB(167,139,250), [4]=Color3.fromRGB(120,120,120) }
                        acctStatusChip.Visible = true
                        acctStatusChipLabel.Text = _CHR.BULLET .. " " .. (PRESENCE_LABELS[parsed_pType] or "UNKNOWN")
                        acctStatusChip.BackgroundColor3 = PRESENCE_BG[parsed_pType]   or Color3.fromRGB(60,60,60)
                        acctStatusChipLabel.TextColor3  = PRESENCE_TEXT[parsed_pType] or Color3.fromRGB(200,200,200)
                        local acctStroke = acctStatusChip:FindFirstChildOfClass("UIStroke")
                        if acctStroke then acctStroke.Color = PRESENCE_GLOW[parsed_pType] or Color3.fromRGB(140,140,140) end
                    end
                end)
            end
        end, true)
        AvatarProfileQueue.Enqueue(function()
            local body = SafeHttpGet("https://avatar.roblox.com/v2/avatar/users/" .. tostring(userId) .. "/avatar")
            local text_type, text_scales, text_colors = nil, nil, nil
            if body then
                local okD, data = pcall(function() return HttpService:JSONDecode(body) end)
                if okD and type(data) == "table" then
                    if type(data.playerAvatarType) == "string" then
                        text_type = data.playerAvatarType
                    end
                    if type(data.scales) == "table" then
                        local s = data.scales
                        local parts = {}
                        if s.height     then table.insert(parts, "Height: "     .. string.format("%.2f", tonumber(s.height)     or 0)) end
                        if s.width      then table.insert(parts, "Width: "      .. string.format("%.2f", tonumber(s.width)      or 0)) end
                        if s.head       then table.insert(parts, "Head: "       .. string.format("%.2f", tonumber(s.head)       or 0)) end
                        if s.depth      then table.insert(parts, "Depth: "      .. string.format("%.2f", tonumber(s.depth)      or 0)) end
                        if s.proportion then table.insert(parts, "Proportion: " .. string.format("%.2f", tonumber(s.proportion) or 0)) end
                        if s.bodyType   then table.insert(parts, "BodyType: "   .. string.format("%.2f", tonumber(s.bodyType)   or 0)) end
                        text_scales = (#parts > 0) and table.concat(parts, " | ") or "Default"
                    end
                    if type(data.bodyColors) == "table" then
                        local c = data.bodyColors
                        local function hexOf(v)
                            local n = tonumber(v)
                            return n and string.format("#%06X", n) or "?"
                        end
                        text_colors = table.concat({
                            "Head: "    .. hexOf(c.headColorId),
                            "Torso: "   .. hexOf(c.torsoColorId),
                            "L.Arm: "   .. hexOf(c.leftArmColorId),
                            "R.Arm: "   .. hexOf(c.rightArmColorId),
                            "L.Leg: "   .. hexOf(c.leftLegColorId),
                            "R.Leg: "   .. hexOf(c.rightLegColorId),
                        }, " | ")
                    end
                end
            end
            if myGen == profileGen then
                if Stats.statAvatarType       then Stats.statAvatarType.Text       = text_type   or "Unknown" end
                if Stats.statAvatarScales     then Stats.statAvatarScales.Text     = text_scales or "Unknown" end
                if Stats.statAvatarBodyColors then Stats.statAvatarBodyColors.Text = text_colors or "Unknown" end
                if PersistExtendedField then
                    PersistExtendedField(userId, "deepAvatarType",   text_type   or "-")
                    PersistExtendedField(userId, "deepAvatarScales", text_scales or "-")
                    PersistExtendedField(userId, "deepAvatarColors", text_colors or "-")
                end
            end
        end, true)
        BadgesAllQueue.Enqueue(function()
            local body = SafeHttpGet(
                "https://badges.roblox.com/v1/users/" .. tostring(userId) .. "/badges?limit=100&sortOrder=Desc"
            )
            local text_count, text_recent, text_list = nil, nil, nil
            if body then
                local okD, data = pcall(function() return HttpService:JSONDecode(body) end)
                if okD and type(data) == "table" and type(data.data) == "table" then
                    local badges = data.data
                    local n = #badges
                    local hasMore = type(data.nextPageCursor) == "string" and data.nextPageCursor ~= ""
                    text_count = tostring(n) .. (hasMore and "+" or "") .. " badge" .. (n ~= 1 and "s" or "") .. " (lintas semua game)"
                    local function parseBadgeDate(s)
                        if type(s) ~= "string" then return "?" end
                        local yr,mo,dy = s:match("(%d+)-(%d+)-(%d+)")
                        return yr and (yr.."/"..mo.."/"..dy) or s
                    end
                    if n > 0 then
                        local first = badges[1]
                        if type(first) == "table" then
                            local bName  = tostring(first.name or "?")
                            local bGame  = (type(first.awardingUniverse) == "table" and first.awardingUniverse.name) or "?"
                            local bDate  = parseBadgeDate(first.awardedDate)
                            text_recent = bName .. " — " .. bGame .. " (" .. bDate .. ")"
                        end
                        local parts = {}
                        for _, b in ipairs(badges) do
                            if type(b) == "table" then
                                local bGame2 = (type(b.awardingUniverse) == "table" and b.awardingUniverse.name) or "?"
                                table.insert(parts, (b.name or "?") .. " [" .. bGame2 .. ", " .. parseBadgeDate(b.awardedDate) .. "]")
                            end
                        end
                        text_list = (#parts > 0) and table.concat(parts, " • ") or "-"
                    else
                        text_recent = "Belum pernah mendapat badge"
                        text_list   = "No badges"
                    end
                end
            end
            if myGen == profileGen then
                if Stats.statAllBadgesCount then Stats.statAllBadgesCount.Text = text_count  or "Gagal memuat" end
                if Stats.statRecentBadge    then Stats.statRecentBadge.Text    = text_recent or "Gagal memuat" end
                if Stats.statAllBadgesList  then Stats.statAllBadgesList.Text  = text_list   or "Gagal memuat" end
                if PersistExtendedField then
                    PersistExtendedField(userId, "deepBadgesCount",  text_count  or "-")
                    PersistExtendedField(userId, "deepBadgesRecent", text_recent or "-")
                    PersistExtendedField(userId, "deepBadgesList",   text_list   or "-")
                end
            end
        end, true)
        InventoryQueue.Enqueue(function()
            local body = SafeHttpGet(
                "https://inventory.roblox.com/v2/users/" .. tostring(userId)
                .. "/inventory?assetTypes=8,41,42,43,44,45,46,47&limit=50&sortOrder=Desc"
            )
            local text = nil
            if body then
                local okD, data = pcall(function() return HttpService:JSONDecode(body) end)
                if okD and type(data) == "table" and type(data.data) == "table" then
                    local items = data.data
                    if #items == 0 then
                        text = "Inventory disembunyikan atau kosong (tidak ada aksesori/hat yang terlihat)"
                    else
                        local hasMore = type(data.nextPageCursor) == "string" and data.nextPageCursor ~= ""
                        local names = {}
                        for _, item in ipairs(items) do
                            if type(item) == "table" then
                                table.insert(names, tostring(item.name or item.assetName or "?"))
                            end
                        end
                        text = ("(%d%s) "):format(#names, hasMore and "+" or "") .. table.concat(names, ", ")
                    end
                end
            end
            text = text or "Inventory private atau tidak dapat diakses"
            if myGen == profileGen then
                if Stats.statInventoryLimited then Stats.statInventoryLimited.Text = text end
                if PersistExtendedField then PersistExtendedField(userId, "deepInventory", text) end
            end
        end, true)
        GenericQueue.Enqueue(function()
            local body = SafeHttpGet("https://locale.roblox.com/v1/users/" .. tostring(userId) .. "/locale")
            local text = nil
            if body then
                local okD, data = pcall(function() return HttpService:JSONDecode(body) end)
                if okD and type(data) == "table" then
                    local parts = {}
                    local sl = data.supportedLocale
                    if type(sl) == "table" then
                        if type(sl.nativeName) == "string" and sl.nativeName ~= "" then
                            table.insert(parts, sl.nativeName)
                        end
                        if type(sl.locale) == "table" and type(sl.locale.nativeName) == "string" and sl.locale.nativeName ~= "" then
                            if sl.locale.nativeName ~= parts[1] then table.insert(parts, sl.locale.nativeName) end
                        end
                    end
                    local ul = data.userLocale
                    if type(ul) == "table" and type(ul.locale) == "table" then
                        local uln = ul.locale.nativeName
                        if type(uln) == "string" and uln ~= "" and uln ~= parts[1] then
                            table.insert(parts, uln)
                        end
                    end
                    if #parts == 0 then
                        if type(data.locale) == "string" and data.locale ~= "" then
                            table.insert(parts, data.locale)
                        end
                    end
                    text = (#parts > 0) and table.concat(parts, " / ") or "Unknown"
                end
            end
            if myGen == profileGen then
            end
        end, true)
        currentDisplayedUserId = userId
        Stats.statFriendsInServer.Text = friendsInServerText[userId] or "No friends currently in this server"
        Stats.statFriendsLeft.Text = friendsLeftText[userId] or "No friends have left the server while monitored"
        end)
    end
    function H.FetchAvatarStats(userId)
        local myGen = profileGen
        Stats.statEquippedEmotes.Text = "Loading..."
        Stats.statBodyParts.Text = "Loading..."
        do
            local histEntry = PlayerHistory and PlayerHistory[tostring(userId)]
            local ext = histEntry and histEntry.extended
            if ext then
                if ext.bodyParts ~= nil then Stats.statBodyParts.Text = tostring(ext.bodyParts) end
                if ext.equippedEmotes ~= nil then Stats.statEquippedEmotes.Text = tostring(ext.equippedEmotes) end
            end
        end
        task.spawn(function()
            local okDesc, desc = pcall(function()
                return Players:GetHumanoidDescriptionFromUserId(userId)
            end)
            if myGen ~= profileGen then return end
            if okDesc and desc then
                local okParts, partsText = pcall(function()
                    local PART_ORDER = {
                        { key = "Head", label = "Head" },
                        { key = "Torso", label = "Torso" },
                        { key = "LeftArm", label = "Left Arm" },
                        { key = "RightArm", label = "Right Arm" },
                        { key = "LeftLeg", label = "Left Leg" },
                        { key = "RightLeg", label = "Right Leg" },
                    }
                    local lines = {}
                    for _, part in ipairs(PART_ORDER) do
                        local assetId = desc[part.key]
                        if type(assetId) == "number" and assetId > 0 then
                            local name = H.GetAssetName(assetId)
                            table.insert(lines, string.format(
                                "%s: %s (ID: %d)", part.label, name or "Unknown Asset", assetId
                            ))
                        else
                            table.insert(lines, string.format("%s: Default (Roblox)", part.label))
                        end
                    end
                    return table.concat(lines, "\n")
                end)
                if myGen == profileGen then
                    local finalParts = (okParts and partsText) or "-"
                    Stats.statBodyParts.Text = finalParts
                    if PersistExtendedField and okParts then PersistExtendedField(userId, "bodyParts", finalParts) end
                end
                local okEmote, emoteText = pcall(function()
                    local raw = desc.EmotesData
                    if not raw or raw == "" then return "No emote equipped" end
                    local okJson, parsed = pcall(function() return HttpService:JSONDecode(raw) end)
                    if not okJson or type(parsed) ~= "table" then return "No emote equipped" end
                    local names = {}
                    for _, entry in pairs(parsed) do
                        if type(entry) == "table" and entry.Name then
                            table.insert(names, entry.Name)
                        end
                    end
                    if #names == 0 then return "No emote equipped" end
                    return table.concat(names, ", ")
                end)
                local finalEmote = (okEmote and emoteText) or "-"
                Stats.statEquippedEmotes.Text = finalEmote
                if PersistExtendedField and okEmote then PersistExtendedField(userId, "equippedEmotes", finalEmote) end
            else
                Stats.statEquippedEmotes.Text = "-"
                Stats.statBodyParts.Text = "-"
            end
        end)
    end
    function H.FormatChatLogText(cache, shownCount)
        local log = (cache and cache.chatLog) or {}
        if #log == 0 then
            return "No messages monitored yet", false, 0
        end
        local shown = math.min(shownCount, #log)
        local parts = {}
        for i = 1, shown do
            local rec = log[i]
            table.insert(parts, os.date("%H:%M:%S", rec.at) .. "  " .. rec.text)
        end
        local text = ("(%d total, showing %d, newest first)\n"):format(#log, shown) .. table.concat(parts, "\n")
        return text, shown < #log, shown
    end
    function H.FormatAnimLogText(cache, shownCount)
        local log = (cache and cache.animLog) or {}
        if #log == 0 then
            return "No animation/emote detected yet", false, 0
        end
        local shown = math.min(shownCount, #log)
        local parts = {}
        for i = 1, shown do
            local rec = log[i]
            local status = rec.original and "Original" or "SCRIPT/INJECTED"
            table.insert(parts, string.format(
                "%s  [%s] %s -- ID: %d (%s)",
                os.date("%H:%M:%S", rec.at), rec.trackName, status, rec.id, rec.name
            ))
        end
        local text = ("(%d total, showing %d, newest first)\n"):format(#log, shown) .. table.concat(parts, "\n")
        return text, shown < #log, shown
    end
    function H.StartLiveStats(target)
        liveStatGen = liveStatGen + 1
        local myGen = liveStatGen
        local liveUserId = target and target.UserId
        local chatLogShown = 20
        local function RenderChatLogPage()
            local cache = H.EnsureCache(liveUserId)
            local text, hasMore = H.FormatChatLogText(cache, chatLogShown)
            statChatLog.Text = text
            statChatLogLoadMoreBtn.Visible = hasMore
        end
        RenderMoreChatLog = function()
            chatLogShown = chatLogShown + 20
            RenderChatLogPage()
        end
        local animLogShown = 20
        local function RenderAnimLogPage()
            local cache = H.EnsureCache(liveUserId)
            local text, hasMore = H.FormatAnimLogText(cache, animLogShown)
            statAnimLog.Text = text
            statAnimLogLoadMoreBtn.Visible = hasMore
        end
        RenderMoreAnimLog = function()
            animLogShown = animLogShown + 20
            RenderAnimLogPage()
        end
        task.spawn(function()
            while myGen == liveStatGen do
                local okLoop = pcall(function()
                    if not (target and target.Parent) then return end
                    if Window and Window.Minimized then return end
                    local mainTabVisible = false
                    pcall(function()
                        local r = Window and Window.Root
                        mainTabVisible = r and r.Parent and r.Visible and (Window.CurrentTab == mainTab)
                    end)
                    if not mainTabVisible then return end
                    local hum = target.Character and target.Character:FindFirstChildOfClass("Humanoid")
                    pcall(function()
                        local animator = hum and hum:FindFirstChildOfClass("Animator")
                        if not animator then
                            Stats.statAnimNow.Text = "No character/Animator"
                            return
                        end
                        local okTracks, tracks = pcall(function() return animator:GetPlayingAnimationTracks() end)
                        if not okTracks or not tracks or #tracks == 0 then
                            Stats.statAnimNow.Text = "No animation playing right now"
                            return
                        end
                        local cacheForOfficial = H.EnsureCache(liveUserId)
                        local lines = {}
                        for _, track in ipairs(tracks) do
                            local id = track.Animation and H.ExtractAnimId(track.Animation.AnimationId)
                            if id then
                                local name = H.GetAssetName(id) or "Unknown Asset"
                                local isOriginal = cacheForOfficial.officialAnimIds and cacheForOfficial.officialAnimIds[id] == true
                                local status = isOriginal and "Original" or "SCRIPT/INJECTED"
                                table.insert(lines, string.format(
                                    "[%s] %s -- ID: %d (%s)",
                                    (track.Name ~= "" and track.Name) or "Animation", status, id, name
                                ))
                            end
                        end
                        Stats.statAnimNow.Text = (#lines > 0) and table.concat(lines, "\n") or "No animation playing right now"
                    end)
                    pcall(RenderAnimLogPage)
                    local okSess, sessText = pcall(function()
                        local cache = H.EnsureCache(liveUserId)
                        local elapsed = math.floor(tick() - (cache.firstSeenTick or tick()))
                        local h = math.floor(elapsed / 3600)
                        local m = math.floor((elapsed % 3600) / 60)
                        local s = elapsed % 60
                        if h > 0 then
                            return string.format("%d:%02d:%02d", h, m, s)
                        end
                        return string.format("%02d:%02d", m, s)
                    end)
                    Stats.statSessionTime.Text = (okSess and sessText) or "-"
                    pcall(function()
                        local chatCache = H.EnsureCache(liveUserId)
                        Stats.statLastChat.Text = chatCache.lastChatMsg or "No messages monitored yet"
                        Stats.statChatCount.Text = tostring(chatCache.chatCount or 0)
                        Stats.statRespawnCount.Text = tostring(chatCache.respawnCount or 0)
                    end)
                    pcall(RenderChatLogPage)
                    local okLeader, leaderText = pcall(function()
                        local ls = target:FindFirstChild("leaderstats")
                        if not ls then return nil end
                        local parts = {}
                        for _, stat in ipairs(ls:GetChildren()) do
                            if stat:IsA("ValueBase") then
                                table.insert(parts, stat.Name .. ": " .. tostring(stat.Value))
                            end
                        end
                        return (#parts > 0) and table.concat(parts, "  " .. _CHR.MIDDOT .. "  ") or nil
                    end)
                    Stats.statLeaderstats.Text = (okLeader and leaderText) or "This game has no leaderstats"
                    if hum then
                        local hp, maxHp = hum.Health, hum.MaxHealth
                        if maxHp and maxHp > 0 then
                            local pct = math.clamp(hp / maxHp, 0, 1)
                            hpValueLbl.Text = string.format("%d / %d", math.floor(hp + 0.5), math.floor(maxHp))
                            local barColor = pct > 0.6 and Color3.fromRGB(142, 142, 142)
                                or (pct > 0.3 and Color3.fromRGB(170, 170, 170) or Color3.fromRGB(65, 65, 65))
                            local cHp = H.EnsureCache(liveUserId)
                            if cHp.lastHpPct ~= pct then
                                Tween(hpFill, 0.25, nil, nil, { Size = UDim2.new(pct, 0, 1, 0) })
                                cHp.lastHpPct = pct
                            end
                            if cHp.lastHpColor ~= barColor then
                                Tween(hpFill, 0.25, nil, nil, { BackgroundColor3 = barColor })
                                cHp.lastHpColor = barColor
                            end
                        end
                        Stats.statWalkSpeed.Text = tostring(math.floor(hum.WalkSpeed))
                        local jp = hum.UseJumpPower and hum.JumpPower or hum.JumpHeight
                        Stats.statJumpPower.Text = tostring(math.floor(jp * 10) / 10)
                        local isUsingLaserNow = (H.EnsureCache(liveUserId).isUsingLaser == true)
                        laserChip.Visible = isUsingLaserNow
                        local tool = target.Character:FindFirstChildOfClass("Tool")
                        Stats.statTool.Text = tool and tool.Name or "None"
                        local invList = ""
                        if target:FindFirstChild("Backpack") then
                            local tools = target.Backpack:GetChildren()
                            local toolNames = {}
                            for _, t in ipairs(tools) do table.insert(toolNames, t.Name) end
                            invList = table.concat(toolNames, ", ")
                        end
                        local invText = (invList == "") and "Kosong" or invList
                        Stats.statInventory.Text = invText
                        if PersistExtendedField then PersistExtendedField(liveUserId, "inventory", invText) end
                        local targetRoot = target.Character:FindFirstChild("HumanoidRootPart")
                        local okDist, distText = pcall(function()
                            local myRoot = LocalPlayer and LocalPlayer.Character
                                and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                            if myRoot and targetRoot then
                                local d = (myRoot.Position - targetRoot.Position).Magnitude
                                return string.format("%d studs", math.floor(d))
                            end
                            return nil
                        end)
                        Stats.statDistance.Text = (okDist and distText) or "-"
                        local okPos, posText = pcall(function()
                            if targetRoot then
                                local p = targetRoot.Position
                                return string.format("%d, %d, %d", math.floor(p.X), math.floor(p.Y), math.floor(p.Z))
                            end
                            return nil
                        end)
                        Stats.statPosition.Text = (okPos and posText) or "-"
                        local okAfk, afkText = pcall(function()
                            local cache = H.EnsureCache(liveUserId)
                            local now = tick()
                            if targetRoot then
                                local p = targetRoot.Position
                                if cache.lastPos and (p - cache.lastPos).Magnitude > 2 then
                                    cache.lastMoveTick = now
                                end
                                cache.lastPos = p
                            end
                            local idleFor = math.floor(now - (cache.lastMoveTick or now))
                            if idleFor <= 8 then return "Active" end
                            local durText
                            if idleFor >= 60 then
                                durText = string.format("%dm %ds", math.floor(idleFor / 60), idleFor % 60)
                            else
                                durText = idleFor .. "s"
                            end
                            return "Likely AFK (idle for " .. durText .. ")"
                        end)
                        Stats.statAfk.Text = (okAfk and afkText) or "-"
                    else
                        hpValueLbl.Text = "- / -"
                        Tween(hpFill, 0.25, nil, nil, { Size = UDim2.new(0, 0, 1, 0) })
                        Stats.statWalkSpeed.Text = "-"
                        Stats.statJumpPower.Text = "-"
                        laserChip.Visible = (H.EnsureCache(liveUserId).isUsingLaser == true)
                        Stats.statTool.Text = "-"
                        Stats.statInventory.Text = "-"
                        Stats.statDistance.Text = "-"
                        Stats.statPosition.Text = "-"
                        Stats.statAfk.Text = "-"
                    end
                    if liveUserId then
                        local c = H.EnsureCache(liveUserId)
                        c.statsText.hp = hpValueLbl.Text
                        c.statsText.hpFillSize = hpFill.Size
                        c.statsText.hpFillColor = hpFill.BackgroundColor3
                        c.statsText.walkSpeed = Stats.statWalkSpeed.Text
                        c.statsText.jumpPower = Stats.statJumpPower.Text
                        c.statsText.tool = Stats.statTool.Text
                        c.statsText.distance = Stats.statDistance.Text
                        c.statsText.position = Stats.statPosition.Text
                        c.statsText.inventory = Stats.statInventory.Text
                        c.statsText.leaderstats = Stats.statLeaderstats.Text
                        c.statsText.afk = Stats.statAfk.Text
                        c.statsText.respawnCount = Stats.statRespawnCount.Text
                        local now = tick()
                        local shouldReclone = (not c.lastCloneAt) or (now - c.lastCloneAt >= 12)
                        if shouldReclone and target.Character then
                            local okCount, descCount = pcall(function() return #target.Character:GetDescendants() end)
                            if okCount and c.lastCloneDescCount == descCount and c.clonedChar then
                                shouldReclone = false
                                c.lastCloneAt = now
                            end
                        end
                        if shouldReclone and target.Character then
                            local wasArchivable = target.Character.Archivable
                            local okClone, freshClone = pcall(function()
                                target.Character.Archivable = true
                                return target.Character:Clone()
                            end)
                            pcall(function() target.Character.Archivable = wasArchivable end)
                            if okClone and freshClone then
                                if c.clonedChar then pcall(function() c.clonedChar:Destroy() end) end
                                SanitizeClonedCharacter(freshClone)
                                c.clonedChar = freshClone
                                c.lastCloneAt = now
                                local okCount2, descCount2 = pcall(function() return #target.Character:GetDescendants() end)
                                c.lastCloneDescCount = okCount2 and descCount2 or nil
                            end
                        end
                    end
                end)
                if not okLoop then
                    warn("[JEYHUB] Live stats tick failed (skipped, loop continues).")
                end
                task.wait((Window and Window.Minimized) and 10 or 5.0)
            end
        end)
    end
    function H.SetInfoCardEmpty(isEmpty)
        emptyStateLbl.Visible = isEmpty
        for _, f in ipairs(statToggleFrames) do
            pcall(function() f.Visible = not isEmpty end)
        end
        if isEmpty then H.StopLiveStats() end
        task.defer(function()
            pcall(function() infoCard.CanvasPosition = Vector2.new(0, 0) end)
            H.SyncInfoCardCanvas()
        end)
    end
    function H.ApplyCachedStatsToUI(cache)
        cache = cache or {}
        local statsText = cache.statsText or H.DefaultStatsText()
        hpValueLbl.Text = statsText.hp
        hpFill.Size = statsText.hpFillSize or UDim2.new(0, 0, 1, 0)
        if statsText.hpFillColor then hpFill.BackgroundColor3 = statsText.hpFillColor end
        Stats.statWalkSpeed.Text = statsText.walkSpeed
        Stats.statJumpPower.Text = statsText.jumpPower
        Stats.statTool.Text = statsText.tool
        Stats.statDistance.Text = "- (offline)"
        Stats.statPosition.Text = statsText.position
        Stats.statInventory.Text = statsText.inventory
        Stats.statLeaderstats.Text = statsText.leaderstats
        Stats.statAfk.Text = statsText.afk or "-"
        Stats.statSessionTime.Text = "- (offline)"
        laserChip.Visible = (cache.isUsingLaser == true)
        Stats.statRespawnCount.Text = tostring(cache.respawnCount or 0)
        Stats.statLastChat.Text = cache.lastChatMsg or "No messages monitored yet"
        Stats.statChatCount.Text = tostring(cache.chatCount or 0)
        local ghostChatShown = 20
        local function RenderGhostChatLog()
            local text, hasMore = H.FormatChatLogText(cache, ghostChatShown)
            statChatLog.Text = text
            statChatLogLoadMoreBtn.Visible = hasMore
        end
        RenderGhostChatLog()
        RenderMoreChatLog = function()
            ghostChatShown = ghostChatShown + 20
            RenderGhostChatLog()
        end
        Stats.statAnimNow.Text = "- (offline, showing last detected log below)"
        local ghostAnimShown = 20
        local function RenderGhostAnimLog()
            local text, hasMore = H.FormatAnimLogText(cache, ghostAnimShown)
            statAnimLog.Text = text
            statAnimLogLoadMoreBtn.Visible = hasMore
        end
        RenderGhostAnimLog()
        RenderMoreAnimLog = function()
            ghostAnimShown = ghostAnimShown + 20
            RenderGhostAnimLog()
        end
    end
    function H.RefreshGameRow(userId)
        local c = PlayerCache and PlayerCache[userId]
        local notInMap = not (c and c.online)
        local isIngame  = c and (c.presenceType == 2)
        if Stats.statCurrentGameRow then
            Stats.statCurrentGameRow.Visible = notInMap and isIngame
        end
        if Stats.statCurrentGame then
            Stats.statCurrentGame.Text = (c and c.presenceGameName) or "Unknown Game"
        end
        if Stats.statJoinBtn then
            Stats.statJoinBtn.Visible = notInMap and isIngame and (c and c.presenceJoinable == true)
        end
    end
    function H.UpdateTargetUI()
        if #TargetPlayers == 0 then
            searchBox.Text = ""
            searchBox.PlaceholderText = "No other players"
            profileGen = profileGen + 1
            H.SetInfoCardEmpty(true)
            if clonedTargetChar then
                pcall(function() clonedTargetChar:Destroy() end)
                clonedTargetChar = nil
            end
            return
        end
        local userId = TargetPlayers[CurrentTargetIndex]
        if not userId then return end
        local cache = H.EnsureCache(userId)
        local snap = cache.snapshot or { userId = userId, name = "Unknown", displayName = "Unknown" }
        local livePlayer = cache.online and Players:GetPlayerByUserId(userId) or nil
        if cache.online and not livePlayer then cache.online = false end
        H.SetInfoCardEmpty(false)
        local isViewingSelf = LocalPlayer and (userId == LocalPlayer.UserId)
        leaderboardHeading.Visible = isViewingSelf
        leaderboardRowFrame.Visible = isViewingSelf
        searchBox.Text = snap.displayName or snap.name
        pcall(function()
            headshot.Image = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(userId) .. "&w=150&h=150"
        end)
        displayNameLbl.Text = snap.displayName or snap.name or "Unknown"
        usernameLbl.Text = "@" .. tostring(snap.name or "?")
        onlineChip.Visible = true
        local onlineStroke = onlineChip:FindFirstChildOfClass("UIStroke")
        if cache.online then
            onlineChipLabel.Text        = _CHR.BULLET .. " IN MAP"
            onlineChip.BackgroundColor3 = Color3.fromRGB(22, 163, 74)
            onlineChipLabel.TextColor3  = Color3.fromRGB(187, 247, 208)
            if onlineStroke then onlineStroke.Color = Color3.fromRGB(74, 222, 128) end
            acctStatusChip.Visible = false
        else
            onlineChipLabel.Text        = _CHR.BULLET .. " NOT IN MAP"
            onlineChip.BackgroundColor3 = Color3.fromRGB(80, 80, 100)
            onlineChipLabel.TextColor3  = Color3.fromRGB(200, 200, 220)
            if onlineStroke then onlineStroke.Color = Color3.fromRGB(140, 140, 160) end
            local PRESENCE_LABELS = {
                [0] = "OFFLINE",
                [1] = "ON WEB",
                [2] = "IN-GAME",
                [3] = "IN STUDIO",
                [4] = "INVISIBLE",
            }
            local PRESENCE_BG = {
                [0] = Color3.fromRGB(185, 28, 28),
                [1] = Color3.fromRGB(37, 99, 235),
                [2] = Color3.fromRGB(22, 163, 74),
                [3] = Color3.fromRGB(109, 40, 217),
                [4] = Color3.fromRGB(64, 64, 64),
            }
            local PRESENCE_TEXT = {
                [0] = Color3.fromRGB(254, 202, 202),
                [1] = Color3.fromRGB(147, 197, 253),
                [2] = Color3.fromRGB(187, 247, 208),
                [3] = Color3.fromRGB(196, 181, 253),
                [4] = Color3.fromRGB(180, 180, 180),
            }
            local PRESENCE_GLOW = {
                [0] = Color3.fromRGB(248, 113, 113),
                [1] = Color3.fromRGB(96, 165, 250),
                [2] = Color3.fromRGB(74, 222, 128),
                [3] = Color3.fromRGB(167, 139, 250),
                [4] = Color3.fromRGB(120, 120, 120),
            }
            local pType = cache.presenceType
            if pType ~= nil then
                acctStatusChip.Visible = true
                acctStatusChipLabel.Text = _CHR.BULLET .. " " .. (PRESENCE_LABELS[pType] or "UNKNOWN")
                acctStatusChip.BackgroundColor3 = PRESENCE_BG[pType]   or Color3.fromRGB(60, 60, 60)
                acctStatusChipLabel.TextColor3  = PRESENCE_TEXT[pType] or Color3.fromRGB(200, 200, 200)
                local acctStroke = acctStatusChip:FindFirstChildOfClass("UIStroke")
                if acctStroke then acctStroke.Color = PRESENCE_GLOW[pType] or Color3.fromRGB(140, 140, 140) end
            else
                acctStatusChip.Visible = false
            end
        end
        H._joinTargetUserId = userId
        if JH_Favorites[userId] then
            starBtn.Text      = CHR_STAR_FILLED .. " Difavoritkan"
            starBtn.TextColor3 = Color3.fromRGB(250, 204, 21)
        else
            starBtn.Text      = CHR_STAR_EMPTY .. " Favorit"
            starBtn.TextColor3 = Palette.SubText
        end
        H.RefreshGameRow(userId)
        premiumChip.Visible = snap.isPremium == true
        verifiedChip.Visible = snap.hasVerifiedBadge == true
        cheaterChip.Visible = false
        laserChip.Visible = (cache.isUsingLaser == true)
        if cache.online then
            Stats.statLastSeen.Text = "Sedang ada di map ini (in map)"
        elseif cache.lastSeenAt then
            local okDate, dateText = pcall(function()
                return os.date("%d %b %Y, %H:%M", cache.lastSeenAt)
            end)
            local agoSeconds = math.max(0, os.time() - cache.lastSeenAt)
            local agoText
            if agoSeconds < 60 then
                agoText = "just now"
            elseif agoSeconds < 3600 then
                agoText = math.floor(agoSeconds / 60) .. " minutes ago"
            elseif agoSeconds < 86400 then
                agoText = math.floor(agoSeconds / 3600) .. " hours ago"
            else
                agoText = math.floor(agoSeconds / 86400) .. " days ago"
            end
            Stats.statLastSeen.Text = (okDate and dateText or "-") .. " (" .. agoText .. ")"
        else
            Stats.statLastSeen.Text = "-"
        end
        statUserId.Text = tostring(userId)
        Stats.statAccAge.Text = tostring(snap.accountAge or "-") .. " Hari"
        local okCreated, createdText = pcall(function()
            return os.date("%d %b %Y", os.time() - ((snap.accountAge or 0) * 86400))
        end)
        Stats.statAccCreated.Text = (snap.accountAge and okCreated) and createdText or "-"
        Stats.statVerifiedBadge.Text = snap.hasVerifiedBadge and "Ya " .. _CHR.CHECK or "No"
        Stats.statVerifiedBadge.TextColor3 = snap.hasVerifiedBadge and Color3.fromRGB(100, 180, 255) or Color3.fromRGB(130, 130, 130)
        Stats.statMembership.Text = (snap.membershipName and snap.membershipName ~= "None") and snap.membershipName or "Reguler"
        Stats.statFriend.Text = snap.isFriend and "Berteman" or "Not Friends Yet"
        do
            local info = H.GetEncounterInfo(userId)
            local n = info.count
            if userId == (LocalPlayer and LocalPlayer.UserId) then
                Stats.statEncounterCount.Text = "This is you"
                Stats.statFirstMet.Text = "-"
                Stats.statLastMet.Text = "-"
                Stats.statEncounterHistory.Text = "-"
                Stats.statEncounterHistoryLoadMoreBtn.Visible = false
                RenderMoreEncounterHistory = nil
            elseif n <= 0 then
                Stats.statEncounterCount.Text = "First time"
                Stats.statFirstMet.Text = "Baru sekarang"
                Stats.statLastMet.Text = "Baru sekarang"
                Stats.statEncounterHistory.Text = "Belum ada riwayat (baru pertama kali ketemu)"
                Stats.statEncounterHistoryLoadMoreBtn.Visible = false
                RenderMoreEncounterHistory = nil
            else
                Stats.statEncounterCount.Text = (n == 1) and "1 kali" or (tostring(n) .. " times")
                local function fmtDateTime(ts)
                    local okFmt, text = pcall(function() return os.date("%d %b %Y, %H:%M", ts) end)
                    return okFmt and text or "-"
                end
                Stats.statFirstMet.Text = info.firstSeen and fmtDateTime(info.firstSeen) or "-"
                Stats.statLastMet.Text = info.lastSeen and fmtDateTime(info.lastSeen) or "-"
                local history = info.history or {}
                if #history == 0 then
                    Stats.statEncounterHistory.Text = "Riwayat detail belum tersedia (tercatat sebelum fitur ini ada)"
                    Stats.statEncounterHistoryLoadMoreBtn.Visible = false
                    RenderMoreEncounterHistory = nil
                else
                    local HISTORY_PAGE_SIZE = 8
                    local shown = 0
                    local function RenderHistoryPage()
                        shown = math.min(shown + HISTORY_PAGE_SIZE, #history)
                        local lines = {}
                        for i = 1, shown do
                            table.insert(lines, (i .. ". " .. fmtDateTime(history[i])))
                        end
                        local suffix = (#history < n) and (" " .. _CHR.EM_DASH .. " riwayat lama sebelum " .. #history .. " terakhir tidak tersimpan") or ""
                        Stats.statEncounterHistory.Text = ("(%d tercatat, menampilkan %d)%s\n"):format(#history, shown, suffix)
                            .. table.concat(lines, "\n")
                        Stats.statEncounterHistoryLoadMoreBtn.Visible = shown < #history
                    end
                    RenderHistoryPage()
                    RenderMoreEncounterHistory = RenderHistoryPage
                end
            end
        end
        if Stats.statNoteBox then
            local isFocused = false
            pcall(function() isFocused = (UserInputService:GetFocusedTextBox() == Stats.statNoteBox) end)
            if not isFocused then
                local noteText, updatedAt = H.GetPlayerNote(userId)
                Stats.statNoteBox.Text = noteText
                if updatedAt then
                    local okFmt, text = pcall(function() return os.date("%d %b %Y, %H:%M", updatedAt) end)
                    Stats.statNoteSavedAt.Text = "Terakhir diedit: " .. (okFmt and text or "-")
                else
                    Stats.statNoteSavedAt.Text = "Belum ada catatan"
                end
            end
        end
        H.FetchSocialStats(userId)
        H.FetchAvatarStats(userId)
        avatarRenderGen = avatarRenderGen + 1
        local myAvatarGen = avatarRenderGen
        if clonedTargetChar then
            pcall(function() clonedTargetChar:Destroy() end)
            clonedTargetChar = nil
        end
        if targetRotationConnection then
            pcall(function() targetRotationConnection:Disconnect() end)
            targetRotationConnection = nil
        end
        targetWorldModel:ClearAllChildren()
        task.spawn(function()
            local localClonedChar = nil
            if cache.online and livePlayer then
                H.StartLiveStats(livePlayer)
                local char = livePlayer.Character
                if char then
                    local wasArchivable = char.Archivable
                    char.Archivable = true
                    local ok, clone = pcall(function() return char:Clone() end)
                    char.Archivable = wasArchivable
                    if ok and clone then
                        localClonedChar = clone
                        SanitizeClonedCharacter(localClonedChar)
                    end
                end
            else
                H.StopLiveStats()
                H.ApplyCachedStatsToUI(cache)
                if cache.clonedChar then
                    local okGhost, ghostClone = pcall(function() return cache.clonedChar:Clone() end)
                    if okGhost and ghostClone then
                        localClonedChar = ghostClone
                    end
                else
                    local okModel, model = pcall(function()
                        return Players:CreateHumanoidModelFromUserId(userId)
                    end)
                    if okModel and model then
                        SanitizeClonedCharacter(model)
                        localClonedChar = model
                        local okCacheClone, cacheClone = pcall(function() return model:Clone() end)
                        if okCacheClone then cache.clonedChar = cacheClone end
                    end
                end
            end
            if myAvatarGen ~= avatarRenderGen then
                if localClonedChar then pcall(function() localClonedChar:Destroy() end) end
                return
            end
            if localClonedChar then
                clonedTargetChar = localClonedChar
                clonedTargetChar.Parent = targetWorldModel
            end
            if clonedTargetChar and targetCamera then
                if cache.online then
                    local camDistance = CAM_DISTANCE
                    local okSize0, _, size0 = pcall(function() return clonedTargetChar:GetBoundingBox() end)
                    if okSize0 and size0 and size0.Y > 0 then
                        camDistance = math.clamp(size0.Y * 1.35, 3.2, CAM_DISTANCE)
                    end
                    ComputeAvatarCameraCFrame(clonedTargetChar, targetCamera, { Distance = camDistance, VerticalBias = 0.55, TiltUp = 0.12 })
                    local RunSvc = RunService
                    if RunSvc then
                        local okCFrame, cframe, size = pcall(function() return clonedTargetChar:GetBoundingBox() end)
                        if okCFrame and size.Y > 0 then
                            local center = cframe.Position
                            local lookAt = center + Vector3.new(0, size.Y * (0.55 - 0.5), 0)
                            local angle = 0
                            targetRotationConnection = DirectConnect(GetSignal(RunSvc, "RenderStepped"), function(dt)
                                if not autoRotate then return end
                                if Window and Window.Minimized then return end
                                angle = angle + (dt * rotateSpeed)
                                local camPos = lookAt + Vector3.new(math.sin(angle) * camDistance, size.Y * 0.12, math.cos(angle) * camDistance)
                                pcall(function() targetCamera.CFrame = CFrame.lookAt(camPos, lookAt) end)
                            end)
                        end
                    end
                else
                    targetRotationConnection = SetupFixedAvatarDisplay(clonedTargetChar, targetCamera, {
                        CamOffset = Vector3.new(0, 0.95, -CAM_DISTANCE),
                        LookOffset = Vector3.new(0, 0.3, 0),
                        ShouldSpin = function()
                            if not autoRotate then return false end
                            local r = Window and Window.Root
                            if not r or not r.Parent or not r.Visible or Window.Minimized then return false end
                            return Window.CurrentTab == mainTab
                        end,
                        SpinPerSec = rotateSpeed,
                    })
                end
            end
        end)
    end
    if statMutualLoadMoreBtn then
        SafeConnect(GetSignal(statMutualLoadMoreBtn, "MouseButton1Click"), function()
            PlayUISound("Click")
            CreateRipple(statMutualLoadMoreBtn)
            if RenderMoreMutualFriends then RenderMoreMutualFriends() end
        end)
    end
    if statChatLogLoadMoreBtn then
        SafeConnect(GetSignal(statChatLogLoadMoreBtn, "MouseButton1Click"), function()
            PlayUISound("Click")
            CreateRipple(statChatLogLoadMoreBtn)
            if RenderMoreChatLog then RenderMoreChatLog() end
        end)
    end
    if statAnimLogLoadMoreBtn then
        SafeConnect(GetSignal(statAnimLogLoadMoreBtn, "MouseButton1Click"), function()
            PlayUISound("Click")
            CreateRipple(statAnimLogLoadMoreBtn)
            if RenderMoreAnimLog then RenderMoreAnimLog() end
        end)
    end
    if Stats.statEncounterHistoryLoadMoreBtn then
        SafeConnect(GetSignal(Stats.statEncounterHistoryLoadMoreBtn, "MouseButton1Click"), function()
            PlayUISound("Click")
            CreateRipple(Stats.statEncounterHistoryLoadMoreBtn)
            if RenderMoreEncounterHistory then RenderMoreEncounterHistory() end
        end)
    end
    if Stats.statLeaderboardLoadMoreBtn then
        SafeConnect(GetSignal(Stats.statLeaderboardLoadMoreBtn, "MouseButton1Click"), function()
            PlayUISound("Click")
            CreateRipple(Stats.statLeaderboardLoadMoreBtn)
            if RenderMoreLeaderboard then RenderMoreLeaderboard() end
        end)
    end
    if Stats.statNoteSaveBtn then
        SafeConnect(GetSignal(Stats.statNoteSaveBtn, "MouseButton1Click"), function()
            PlayUISound("Click")
            CreateRipple(Stats.statNoteSaveBtn)
            local activeUserId = TargetPlayers[CurrentTargetIndex]
            if not activeUserId then return end
            local activePlr = Players:GetPlayerByUserId(activeUserId)
            H.SetPlayerNote(activeUserId, Stats.statNoteBox.Text, activePlr)
            local _, updatedAt = H.GetPlayerNote(activeUserId)
            if updatedAt then
                local okFmt, text = pcall(function() return os.date("%d %b %Y, %H:%M", updatedAt) end)
                Stats.statNoteSavedAt.Text = "Tersimpan: " .. (okFmt and text or "-")
            else
                Stats.statNoteSavedAt.Text = "Catatan dihapus"
            end
            local original = Stats.statNoteSaveBtn.Text
            Stats.statNoteSaveBtn.Text = "Tersimpan!"
            task.delay(1, function()
                pcall(function() Stats.statNoteSaveBtn.Text = original end)
            end)
        end)
    end
    local _navCooldown = false
    SafeConnect(GetSignal(leftBtn, "MouseButton1Click"), function()
        if _navCooldown then return end
        _navCooldown = true
        if #TargetPlayers > 0 then
            CurrentTargetIndex = CurrentTargetIndex - 1
            if CurrentTargetIndex < 1 then CurrentTargetIndex = #TargetPlayers end
            H.UpdateTargetUI()
            task.defer(function() if ApplySpectateCamera then ApplySpectateCamera() end end)
        end
        task.delay(0.2, function() _navCooldown = false end)
    end)
    SafeConnect(GetSignal(rightBtn, "MouseButton1Click"), function()
        if _navCooldown then return end
        _navCooldown = true
        if #TargetPlayers > 0 then
            CurrentTargetIndex = CurrentTargetIndex + 1
            if CurrentTargetIndex > #TargetPlayers then CurrentTargetIndex = 1 end
            H.UpdateTargetUI()
            task.defer(function() if ApplySpectateCamera then ApplySpectateCamera() end end)
        end
        task.delay(0.2, function() _navCooldown = false end)
    end)
    if LocalPlayer then
        task.spawn(function()
            H.GetOrFetchFriends(LocalPlayer.UserId, nil, true)
        end)
    end
    task.spawn(function()
        task.wait(1)
        H.RefreshPlayerList()
        if #TargetPlayers > 0 then CurrentTargetIndex = 1 end
        H.UpdateTargetUI()
        H.PrefetchAllTargetAvatars()
    end)
    task.spawn(function()
        task.wait(2)
        H.BackgroundScanAllPlayers()
    end)
    SafeConnect(GetSignal(Players, "PlayerAdded"), function(plr)
        if PlayerCache[plr.UserId] then
            PlayerCache[plr.UserId] = nil
            for i = #OfflineOrder, 1, -1 do
                if OfflineOrder[i] == plr.UserId then table.remove(OfflineOrder, i) end
            end
        end
        H.RefreshPlayerList()
        H.RecordEncounter(plr)
        task.wait(2)
        H.BackgroundPrefetchPlayer(plr)
    end)
    SafeConnect(GetSignal(Players, "PlayerRemoving"), function(leavingPlr)
        local c = PlayerCache[leavingPlr.UserId]
        if c then
            c.online = false
            c.lastSeenAt = os.time()
            if not c.snapshot then
                pcall(function() c.snapshot = H.SnapshotPlayer(leavingPlr) end)
            end
            if not H.seenInOfflineOrder(leavingPlr.UserId) then
                table.insert(OfflineOrder, leavingPlr.UserId)
            end
            if PersistLastSeen then PersistLastSeen(leavingPlr.UserId, c.lastSeenAt) end
            if PersistPlayerSnapshot and c.snapshot then PersistPlayerSnapshot(leavingPlr.UserId, c.snapshot) end
        end
        task.defer(H.RefreshPlayerList)
        task.defer(H.PrefetchAllTargetAvatars)
        if TargetPlayers[CurrentTargetIndex] == leavingPlr.UserId then
            task.defer(H.UpdateTargetUI)
        end
    end)
    task.spawn(function()
        while true do
            task.wait(600)
            if not IsCurrentRun() then break end
            if not (Window and Window.Minimized) then
            H.BackgroundScanAllPlayers()
            H.PrefetchAllTargetAvatars()
                end
        end
    end)
    task.spawn(function()
        while true do
            task.wait(10)
            if not IsCurrentRun() then break end
            if Window and Window.Minimized then continue end
            local uid = TargetPlayers[CurrentTargetIndex]
            if not uid then continue end
            local c = PlayerCache and PlayerCache[uid]
            if not c or c.online then continue end
            local pollUid = uid
            PresenceQueue.Enqueue(function()
                if TargetPlayers[CurrentTargetIndex] ~= pollUid then return end
                local ok, resp = pcall(DoHttpRequestGlobal, {
                    Url     = "https://presence.roblox.com/v1/presence/users",
                    Method  = "POST",
                    Headers = { ["Content-Type"] = "application/json" },
                    Body    = '{"userIds":[' .. tostring(pollUid) .. ']}',
                })
                local pType, gameName, placeId, gameId, universeId
                local joinable = false
                if ok and type(resp) == "table" then
                    local body = resp.Body or resp.body or ""
                    if type(body) == "string" and body ~= "" then
                        local okD, data = pcall(function() return HttpService:JSONDecode(body) end)
                        if okD and type(data) == "table"
                        and type(data.userPresences) == "table"
                        and #data.userPresences > 0 then
                            local p = data.userPresences[1]
                            pType = tonumber(p.userPresenceType)
                            if type(p.lastLocation) == "string" and p.lastLocation ~= "" then
                                gameName = p.lastLocation
                            end
                            if type(p.placeId) == "number" and p.placeId ~= 0 then
                                placeId = p.placeId
                            end
                            if type(p.gameId) == "string" and p.gameId ~= "" and p.gameId ~= "0" then
                                gameId = p.gameId
                            end
                            if type(p.universeId) == "number" and p.universeId ~= 0 then
                                universeId = p.universeId
                            end
                            joinable = (pType == 2 and placeId ~= nil and gameId ~= nil)
                        end
                    end
                end
                local cc = PlayerCache and PlayerCache[pollUid]
                if cc and not cc.online then
                    cc.presenceType      = pType
                    cc.presenceGameName  = gameName
                    cc.presencePlaceId   = placeId
                    cc.presenceGameId    = gameId
                    cc.presenceUniverseId = universeId
                    cc.presenceJoinable  = joinable
                end
                pcall(function()
                    if TargetPlayers[CurrentTargetIndex] ~= pollUid then return end
                    local cc2 = PlayerCache and PlayerCache[pollUid]
                    if not cc2 or cc2.online then return end
                    H.RefreshGameRow(pollUid)
                    if Stats.statPresenceLastGame and pType ~= nil then
                        local locParts = {}
                        if gameName   then table.insert(locParts, gameName) end
                        if placeId    then table.insert(locParts, "PlaceId: " .. tostring(placeId)) end
                        if gameId     then table.insert(locParts, "Server: " .. gameId) end
                        if universeId then table.insert(locParts, "UniverseId: " .. tostring(universeId)) end
                        Stats.statPresenceLastGame.Text = (#locParts > 0)
                            and table.concat(locParts, " | ")
                            or  "None / Private"
                    end
                    if acctStatusChip and pType ~= nil then
                        local LABELS = { [0]="OFFLINE", [1]="ON WEB", [2]="IN-GAME", [3]="IN STUDIO", [4]="INVISIBLE" }
                        local BG     = { [0]=Color3.fromRGB(185,28,28),  [1]=Color3.fromRGB(37,99,235),
                                         [2]=Color3.fromRGB(22,163,74),   [3]=Color3.fromRGB(109,40,217),
                                         [4]=Color3.fromRGB(64,64,64) }
                        local TEXT   = { [0]=Color3.fromRGB(254,202,202), [1]=Color3.fromRGB(147,197,253),
                                         [2]=Color3.fromRGB(187,247,208), [3]=Color3.fromRGB(196,181,253),
                                         [4]=Color3.fromRGB(180,180,180) }
                        local GLOW   = { [0]=Color3.fromRGB(248,113,113), [1]=Color3.fromRGB(96,165,250),
                                         [2]=Color3.fromRGB(74,222,128),  [3]=Color3.fromRGB(167,139,250),
                                         [4]=Color3.fromRGB(120,120,120) }
                        acctStatusChip.Visible = true
                        acctStatusChipLabel.Text           = _CHR.BULLET .. " " .. (LABELS[pType] or "UNKNOWN")
                        acctStatusChip.BackgroundColor3    = BG[pType]   or Color3.fromRGB(60,60,60)
                        acctStatusChipLabel.TextColor3     = TEXT[pType] or Color3.fromRGB(200,200,200)
                        local stroke = acctStatusChip:FindFirstChildOfClass("UIStroke")
                        if stroke then stroke.Color = GLOW[pType] or Color3.fromRGB(140,140,140) end
                    end
                end)
            end, true)
        end
    end)
    SafeConnect(GetSignal(searchBox, "FocusLost"), function(enterPressed)
        if not enterPressed then return end
        local query = string.lower(searchBox.Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if query == "" then
            H.UpdateTargetUI()
            return
        end
        local foundIndex = nil
        local onlineExact   = nil
        local onlinePartial = nil
        for i, uid in ipairs(TargetPlayers) do
            local c  = PlayerCache[uid]
            local dn = c and c.snapshot and c.snapshot.displayName
            local un = c and c.snapshot and c.snapshot.name
            local isOnline = c and c.online
            if isOnline then
                local dnLow = dn and string.lower(dn) or nil
                local unLow = un and string.lower(un) or nil
                if (dnLow == query) or (unLow == query) then
                    onlineExact = i
                    break
                elseif not onlinePartial then
                    if (dnLow and string.find(dnLow, query, 1, true))
                        or (unLow and string.find(unLow, query, 1, true)) then
                        onlinePartial = i
                    end
                end
            end
        end
        local offlineIndex = nil
        if not onlineExact and not onlinePartial then
            for i, uid in ipairs(TargetPlayers) do
                local c  = PlayerCache[uid]
                local dn = c and c.snapshot and c.snapshot.displayName
                local un = c and c.snapshot and c.snapshot.name
                local isOnline = c and c.online
                if not isOnline then
                    local dnLow = dn and string.lower(dn) or nil
                    local unLow = un and string.lower(un) or nil
                    if (dnLow and string.find(dnLow, query, 1, true))
                        or (unLow and string.find(unLow, query, 1, true)) then
                        offlineIndex = i
                        break
                    end
                end
            end
        end
        foundIndex = onlineExact or onlinePartial or offlineIndex
        if foundIndex then
            CurrentTargetIndex = foundIndex
            H.UpdateTargetUI()
            task.defer(function() if ApplySpectateCamera then ApplySpectateCamera() end end)
        else
            searchBox.Text = ""
            searchBox.PlaceholderText = "Not found: \"" .. query .. "\""
            task.delay(1.4, function()
                pcall(function()
                    searchBox.PlaceholderText = "Search Player..."
                    H.UpdateTargetUI()
                end)
            end)
        end
    end)
