    local function GetCurrentTargetPlayer()
        if #TargetPlayers == 0 then return nil end
        local uid = TargetPlayers[CurrentTargetIndex]
        return uid and Players:GetPlayerByUserId(uid)
    end
    local function ApplySpectateCamera()
        if spectateConn then spectateConn:Disconnect() spectateConn = nil end
        if not isSpectating then return end
        local cam = workspace and workspace.CurrentCamera
        if not cam then return end
        pcall(function() cam.CameraType = Enum.CameraType.Follow end)
        if spectateConn then pcall(function() spectateConn:Disconnect() end) end
        spectateConn = TrackConnection(RunSvcCheat.RenderStepped:Connect(function()
            if not isSpectating then return end
            local camNow = workspace and workspace.CurrentCamera
            if not camNow then return end
            local t = GetCurrentTargetPlayer()
            if t and t.Character and t.Character:FindFirstChild("Humanoid") then
                local targetHum = t.Character.Humanoid
                if camNow.CameraSubject ~= targetHum then
                    pcall(function()
                        camNow.CameraType   = Enum.CameraType.Follow
                        camNow.CameraSubject = targetHum
                    end)
                end
                if cheatStatus and cheatStatus.Parent then
                    pcall(function()
                        cheatStatus.Text = "Spectating: " .. (t.DisplayName or t.Name)
                    end)
                end
            else
                if cheatStatus and cheatStatus.Parent then
                    pcall(function()
                        cheatStatus.Text = "Spectate: target has no character"
                    end)
                end
            end
        end))
    end
    local ugOffsetVal        = 25
    local isUnderground      = false
    local isNoisyUnderground = false
    local isInvisible        = false
    local undergroundOriginalCFrame = nil
    local undergroundConn           = nil
    local invisibleParts            = {}
    local invisibleConn             = nil
    local safeFollowConn            = nil
    local function CheatTeleport(targetCFrame)
        local char = LocalPlayer and LocalPlayer.Character
        if not char or not char.PrimaryPart then return end
        local root = char.PrimaryPart
        local hum  = char:FindFirstChildOfClass("Humanoid")
        for _ = 1, 2 do
            root.AssemblyLinearVelocity  = Vector3.new(0,0,0)
            root.AssemblyAngularVelocity = Vector3.new(0,0,0)
        end
        if hum then hum:ChangeState(Enum.HumanoidStateType.Physics) end
        char:PivotTo(targetCFrame)
        if RunSvcCheat then RunSvcCheat.Heartbeat:Wait() end
        for _ = 1, 2 do
            root.AssemblyLinearVelocity  = Vector3.new(0,0,0)
            root.AssemblyAngularVelocity = Vector3.new(0,0,0)
        end
        if hum then hum:ChangeState(Enum.HumanoidStateType.GettingUp) end
    end
