    H.CreateMainButton({
        Title = "Teleport",
        Subtitle = "Instant TP behind the selected target",
        Callback = function()
            local t = GetCurrentTargetPlayer()
            local myChar = LocalPlayer and LocalPlayer.Character
            if not t or not t.Character or not myChar or not myChar.PrimaryPart then
                cheatStatus.Text = "Teleport FAILED " .. _CHR.EM_DASH .. " no valid target"
                return
            end
            local tr = t.Character.PrimaryPart
            if not tr then return end
            local lookVec = tr.CFrame.LookVector
            local offset  = math.random(0, 1) == 0 and 2 or -2
            local dest    = Vector3.new(
                tr.Position.X + lookVec.X * offset,
                tr.Position.Y + 1.5,
                tr.Position.Z + lookVec.Z * offset
            )
            CheatTeleport(CFrame.new(dest, tr.Position))
            cheatStatus.Text = "Teleported to: " .. (t.DisplayName or t.Name)
        end,
    })
    H.CreateMainToggle({
        Title = "Safe Follow",
        Subtitle = "Walk toward target, stop at ~8 studs",
        Default = false,
        Callback = function(s)
            safeFollowActive = s
            if safeFollowConn then safeFollowConn:Disconnect() safeFollowConn = nil end
            if s then
                safeFollowConn = RunSvcCheat.Heartbeat:Connect(function()
                    if not safeFollowActive then return end
                    local t = GetCurrentTargetPlayer()
                    if t and t.Character and t.Character.PrimaryPart then
                        local char = LocalPlayer.Character
                        local hum  = char and char:FindFirstChildOfClass("Humanoid")
                        local root = char and char:FindFirstChild("HumanoidRootPart")
                        if hum and root then
                            local dist = (root.Position - t.Character.PrimaryPart.Position).Magnitude
                            if dist > 8 then hum:MoveTo(t.Character.PrimaryPart.Position)
                            else hum:MoveTo(root.Position) end
                        end
                    end
                end)
                cheatStatus.Text = "Safe Follow ON"
            else
                local char = LocalPlayer and LocalPlayer.Character
                local hum  = char and char:FindFirstChildOfClass("Humanoid")
                local root = char and char:FindFirstChild("HumanoidRootPart")
                if hum and root then hum:MoveTo(root.Position) end
                cheatStatus.Text = "Safe Follow OFF"
            end
        end,
    })
