    H.CreateMainToggle({
        Title = "Underground",
        Subtitle = "Phase below the map under the target",
        Default = false,
        Callback = function(s)
            isUnderground = s
            local char = LocalPlayer and LocalPlayer.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if isUnderground then
                if root and hum then
                    undergroundOriginalCFrame = root.CFrame
                    root.Anchored = false
                    for _, track in pairs(hum:GetPlayingAnimationTracks()) do track:AdjustSpeed(0) end
                    local t = GetCurrentTargetPlayer()
                    if t and t.Character and t.Character:FindFirstChild("HumanoidRootPart") then
                        local tr = t.Character.HumanoidRootPart
                        local underY = math.max(tr.Position.Y - ugOffsetVal, (workspace and workspace.FallenPartsDestroyHeight or -500) + 25)
                        local tp = Vector3.new(tr.Position.X, underY, tr.Position.Z)
                        local fcf = CFrame.new(tp) * cheatBaseRot
                        local ugLastKnownPos = tp
                        task.spawn(function()
                            CheatTeleport(fcf)
                            if _ugCollisionGroupReady then
                                _AssignCollisionGroup(LocalPlayer.Character, _UG_COLLISION_GROUP)
                                pcall(function()
                                    local _ugDescConn = LocalPlayer.Character.DescendantAdded:Connect(function(d)
                                        if not isUnderground then return end
                                        if d:IsA("BasePart") then
                                            pcall(function() d.CollisionGroup = _UG_COLLISION_GROUP end)
                                        end
                                    end)
                                    table.insert(activeConns or {}, _ugDescConn)
                                end)
                            else
                                for _, v in pairs(LocalPlayer.Character:GetDescendants()) do
                                    if v:IsA("BasePart") and v.CanCollide then v.CanCollide = false end
                                end
                            end
                            undergroundConn = TrackConnection(RunSvcCheat.Heartbeat:Connect(function()
                                pcall(function()
                                    local myC = LocalPlayer.Character
                                    local myR = myC and myC:FindFirstChild("HumanoidRootPart")
                                    local myH = myC and myC:FindFirstChildOfClass("Humanoid")
                                    if not myR then return end
                                    local t2 = GetCurrentTargetPlayer()
                                    local targetRoot = t2 and t2.Character and t2.Character:FindFirstChild("HumanoidRootPart")
                                    if targetRoot then
                                        local tr2 = targetRoot
                                        if myR and tr2.Position.Y <= myR.Position.Y then
                                            if ugLastKnownPos then
                                                myR.CFrame = CFrame.new(ugLastKnownPos) * cheatBaseRot
                                            end
                                            myR.AssemblyLinearVelocity  = Vector3.new(0, 0, 0)
                                            myR.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                                            if myH then myH:ChangeState(Enum.HumanoidStateType.Freefall) end
                                            if not _ugCollisionGroupReady then
                                                for _, v in pairs(myC:GetDescendants()) do
                                                    if v:IsA("BasePart") and v.CanCollide then v.CanCollide = false end
                                                end
                                            end
                                            return
                                        end
                                        local uy2 = math.max(tr2.Position.Y - ugOffsetVal, (workspace and workspace.FallenPartsDestroyHeight or -500) + 25)
                                        local up = Vector3.new(tr2.Position.X, uy2, tr2.Position.Z)
                                        ugLastKnownPos = up
                                        if myR then
                                            myR.CFrame = CFrame.new(up) * cheatBaseRot
                                            if isNoisyUnderground then
                                                local stateChoice = math.random(1, 2)
                                                if stateChoice == 1 then
                                                    if myH then myH:ChangeState(Enum.HumanoidStateType.Swimming) end
                                                else
                                                    if myH then myH:ChangeState(Enum.HumanoidStateType.Freefall) end
                                                end
                                                if math.random() < 0.05 then
                                                    myR.AssemblyLinearVelocity = Vector3.new(
                                                        math.random(-10000, 10000),
                                                        math.random(-1000,  1000),
                                                        math.random(-10000, 10000)
                                                    )
                                                end
                                                for _, snd in pairs(myC:GetDescendants()) do
                                                    if snd:IsA("Sound") then
                                                        local n = snd.Name
                                                        if n == "Splash" or n == "Swimming" or n == "Wading"
                                                        or n == "Running" or n == "Climbing" or n == "FreeFalling"
                                                        or n == "GettingUp" or n == "Jumping" or n == "Landing"
                                                        or n == "Died" then
                                                            pcall(function() snd.Volume = 0 end)
                                                            if snd.IsPlaying then pcall(function() snd:Stop() end) end
                                                        end
                                                    end
                                                end
                                            else
                                                myR.AssemblyLinearVelocity  = Vector3.new(0, 0, 0)
                                                myR.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                                                if myH then myH:ChangeState(Enum.HumanoidStateType.Freefall) end
                                            end
                                            if not _ugCollisionGroupReady then
                                                for _, v in pairs(myC:GetDescendants()) do
                                                    if v:IsA("BasePart") and v.CanCollide then v.CanCollide = false end
                                                end
                                            end
                                        end
                                    else
                                        if ugLastKnownPos then
                                            myR.CFrame = CFrame.new(ugLastKnownPos) * cheatBaseRot
                                        end
                                        myR.AssemblyLinearVelocity  = Vector3.new(0, 0, 0)
                                        myR.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                                        if myH then myH:ChangeState(Enum.HumanoidStateType.Freefall) end
                                        if not _ugCollisionGroupReady then
                                            for _, v in pairs(myC:GetDescendants()) do
                                                if v:IsA("BasePart") and v.CanCollide then v.CanCollide = false end
                                            end
                                        end
                                    end
                                end)
                            end))
                        end)
                    end
                end
                cheatStatus.Text = "Underground ON"
            else
                if undergroundConn then undergroundConn:Disconnect() undergroundConn = nil end
                if root and undergroundOriginalCFrame then
                    root.Anchored = false
                    task.spawn(function() CheatTeleport(undergroundOriginalCFrame) end)
                    if hum then
                        hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                        for _, track in pairs(hum:GetPlayingAnimationTracks()) do track:AdjustSpeed(1) end
                    end
                end
                if _ugCollisionGroupReady and char then
                    _AssignCollisionGroup(char, "Default")
                end
                cheatStatus.Text = "Underground OFF"
            end
        end,
    })
