    local isVoidDrop          = false
    local voidDropConn        = nil
    local voidDropOriginalCF  = nil
    local VOID_XZ_BASE = 2^25 * 30000000
    local VOID_Y       = 2^25 * 30000000
    local function DestroyNetworkPause()
        pcall(function()
            local cg = game:GetService("CoreGui")
            local rg = cg:FindFirstChild("RobloxGui")
            if rg then
                local np = rg:FindFirstChild("CoreScripts/NetworkPause")
                if np then np:Destroy() end
            end
        end)
    end
    H.CreateMainToggle({
        Title = "Void Drop",
        Subtitle = "Overflow coords TP — toggle off to return",
        Default = false,
        Callback = function(s)
            isVoidDrop = s
            local char = LocalPlayer and LocalPlayer.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if voidDropConn then voidDropConn:Disconnect() voidDropConn = nil end
            if isVoidDrop then
                if root then
                    voidDropOriginalCF = root.CFrame
                    DestroyNetworkPause()
                    if hum then
                        hum.PlatformStand = true
                        hum.Sit = true
                        for _, tr in pairs(hum:GetPlayingAnimationTracks()) do
                            tr:Stop()
                        end
                    end
                    if char then
                        for _, p in pairs(char:GetDescendants()) do
                            if p:IsA("BasePart") then
                                p.CanCollide = false
                                p.CustomPhysicalProperties = PhysicalProperties.new(0.01, 0, 0, 0, 0)
                            end
                        end
                    end
                    task.spawn(function()
                        CheatTeleport(CFrame.new(VOID_XZ_BASE, VOID_Y, VOID_XZ_BASE))
                        RunSvcCheat.Heartbeat:Wait()
                        local myC = LocalPlayer.Character
                        local myR = myC and myC:FindFirstChild("HumanoidRootPart")
                        local myH = myC and myC:FindFirstChildOfClass("Humanoid")
                        if myR then
                            local mass = myR.AssemblyMass or 1
                            local BRUTAL = 50000000
                            myR:ApplyImpulse(Vector3.new(
                                math.random(BRUTAL, BRUTAL * 2),
                                math.random(BRUTAL, BRUTAL * 2),
                                math.random(BRUTAL, BRUTAL * 2)
                            ) * mass)
                            myR.AssemblyLinearVelocity = Vector3.new(
                                math.random(10000000, 50000000),
                                math.random(10000000, 50000000),
                                math.random(10000000, 50000000)
                            )
                            myR.AssemblyAngularVelocity = Vector3.new(
                                math.random(-50000000, 50000000),
                                math.random(-50000000, 50000000),
                                math.random(-50000000, 50000000)
                            )
                            local bv = Instance.new("BodyVelocity")
                            bv.Name = "JEYHUB_VoidBV"
                            bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                            bv.Velocity = Vector3.new(
                                math.random(20000000, 40000000),
                                math.random(20000000, 40000000),
                                math.random(20000000, 40000000)
                            )
                            bv.Parent = myR
                            local ba = Instance.new("BodyAngularVelocity")
                            ba.Name = "JEYHUB_VoidBA"
                            ba.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
                            ba.AngularVelocity = Vector3.new(
                                math.random(-30000000, 30000000),
                                math.random(-30000000, 30000000),
                                math.random(-30000000, 30000000)
                            )
                            ba.Parent = myR
                        end
                        local ticker = 0
                        voidDropConn = TrackConnection(RunSvcCheat.Heartbeat:Connect(function(dt)
                            pcall(function()
                                local myC = LocalPlayer.Character
                                local myR = myC and myC:FindFirstChild("HumanoidRootPart")
                                local myH = myC and myC:FindFirstChildOfClass("Humanoid")
                                if myR then
                                    local jitter = 100000000
                                    local fx = VOID_XZ_BASE + math.random(-jitter, jitter)
                                    local fz = VOID_XZ_BASE + math.random(-jitter, jitter)
                                    local fy = VOID_Y + math.random(-jitter, jitter)
                                    myR.AssemblyLinearVelocity = Vector3.new(
                                        math.random(20000000, 80000000),
                                        math.random(20000000, 80000000),
                                        math.random(20000000, 80000000)
                                    )
                                    myR.AssemblyAngularVelocity = Vector3.new(
                                        math.random(-80000000, 80000000),
                                        math.random(-80000000, 80000000),
                                        math.random(-80000000, 80000000)
                                    )
                                    myR.CFrame = CFrame.new(fx, fy, fz) * CFrame.Angles(
                                        math.rad(math.random(-180, 180)),
                                        math.rad(math.random(-180, 180)),
                                        math.rad(math.random(-180, 180))
                                    )
                                    if myH then
                                        myH:ChangeState(Enum.HumanoidStateType.Physics)
                                        myH.PlatformStand = true
                                    end
                                    for _, p in pairs(myC:GetDescendants()) do
                                        if p:IsA("BasePart") and p.CanCollide then
                                            p.CanCollide = false
                                        end
                                    end
                                end
                                ticker = ticker + dt
                                if ticker >= 5 then
                                    ticker = 0
                                    DestroyNetworkPause()
                                end
                            end)
                        end))
                    end)
                end
                cheatStatus.Text = string.format("Void Drop ON " .. _CHR.EM_DASH .. " koordinat %.2e studs", VOID_XZ_BASE)
            else
                if voidDropConn then voidDropConn:Disconnect() voidDropConn = nil end
                if char then
                    for _, p in pairs(char:GetDescendants()) do
                        if p:IsA("BodyVelocity") and p.Name == "JEYHUB_VoidBV" then
                            p:Destroy()
                        end
                        if p:IsA("BodyAngularVelocity") and p.Name == "JEYHUB_VoidBA" then
                            p:Destroy()
                        end
                        if p:IsA("BasePart") then
                            p.CustomPhysicalProperties = nil
                        end
                    end
                end
                if root and voidDropOriginalCF then
                    root.Anchored = false
                    task.spawn(function() CheatTeleport(voidDropOriginalCF) end)
                    if hum then
                        hum.PlatformStand = false
                        hum.Sit = false
                        hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                        for _, tr in pairs(hum:GetPlayingAnimationTracks()) do
                            tr:AdjustSpeed(1)
                        end
                    end
                    if char then
                        for _, p in pairs(char:GetDescendants()) do
                            if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" then
                                p.CanCollide = true
                            end
                        end
                    end
                end
                cheatStatus.Text = "Void Drop OFF " .. _CHR.EM_DASH .. " kembali ke posisi semula"
            end
        end,
    })H.CreateMainToggle({
        Title = "Invisible (FE)",
        Subtitle = "Hide yourself from other players",
        Default = false,
        Callback = function(s)
            isInvisible = s
            local char = LocalPlayer and LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            local root = char and char:FindFirstChild("HumanoidRootPart")
            invisibleParts = {}
            if char then
                for _, v in pairs(char:GetDescendants()) do
                    if v:IsA("BasePart") and v.Name ~= "HumanoidRootPart" and v.Transparency < 1 then
                        table.insert(invisibleParts, v)
                    end
                end
            end
            if invisibleConn then invisibleConn:Disconnect() invisibleConn = nil end
            if isInvisible then
                for _, v in pairs(invisibleParts) do v.Transparency = 0.5 end
                invisibleConn = RunSvcCheat.Heartbeat:Connect(function()
                    if isInvisible and char and root and hum then
                        local ocf = root.CFrame
                        local oof = hum.CameraOffset
                        local hideCF = ocf * CFrame.new(0, -25, 0)
                        root.CFrame = hideCF
                        hum.CameraOffset = hideCF:ToObjectSpace(CFrame.new(ocf.Position)).Position
                        RunSvcCheat.RenderStepped:Wait()
                        root.CFrame = ocf
                        hum.CameraOffset = oof
                    end
                end)
                cheatStatus.Text = "Invisible ON"
            else
                for _, v in pairs(invisibleParts) do v.Transparency = 0 end
                if hum then hum.CameraOffset = Vector3.new(0,0,0) end
                cheatStatus.Text = "Invisible OFF"
            end
        end,
    })
    H.RefreshPlayerList()
    if #TargetPlayers > 0 and CurrentTargetIndex < 1 then CurrentTargetIndex = 1 end
    H.UpdateTargetUI()
end
_Tabs.AvatarChanger = function()    local tab = CreatedTabs and CreatedTabs["Avatar Changer"]
    if not tab or not tab.CreateSection then return end
    local AvatarEditorService = SafeService("AvatarEditorService")
    local function enumItem(enumType, name)
        local ok, value = pcall(function() return enumType[name] end)
        if ok then return value end
        return nil
    end
    local function formatItemPrice(item)
        local price = item.Price or item.LowestPrice
        if item.IsForSale == false and not price then
            return "Off-Sale"
        end
        if price == nil then return _CHR.EM_DASH end
        if type(price) ~= "number" then return tostring(price) end
        if price <= 0 then return "Gratis" end
        return "R$ " .. tostring(price)
    end
    local SUB_TABS = {
        { key = "hats", label = "Hats", placeholder = "Search hat",
          assetTypes = { enumItem(Enum.AvatarAssetType, "Hat") }, mode = "accessory" },
        { key = "hair", label = "Hair", placeholder = "Search hair",
