        if locked then
            if pillLoadingSpin then pcall(function() pillLoadingSpin:Cancel() end) end
            pillLoadingIcon.Rotation = 0
            local function spinOnce()
                local tw = Tween(pillLoadingIcon, 0.5, Enum.EasingStyle.Linear, Enum.EasingDirection.Out, { Rotation = 360 })
                pillLoadingSpin = tw
                if tw then
                    tw.Completed:Connect(function()
                        if pillsLocked then
                            pillLoadingIcon.Rotation = 0
                            spinOnce()
                        end
                    end)
                end
            end
            spinOnce()
        end
        for _, entry in pairs(pillButtons) do
            pcall(function() entry.Frame.Active = not locked end)
        end
    end
