    local function switchETab(target)
        local isR6 = (target == "R6")
        ePanelR6.Visible  = isR6
        ePanelR15.Visible = not isR6
        Tween(eTabR6, 0.12, nil, nil, {
            BackgroundColor3       = isR6 and accent or Palette.Element,
            BackgroundTransparency = isR6 and 0 or 0.1,
            TextColor3             = isR6 and Palette.Background or Palette.SubText,
        })
        Tween(eTabR15, 0.12, nil, nil, {
            BackgroundColor3       = (not isR6) and accent or Palette.Element,
            BackgroundTransparency = (not isR6) and 0 or 0.1,
            TextColor3             = (not isR6) and Palette.Background or Palette.SubText,
        })
    end
