    local CROUCH_ANIM_SPEED   = 0.8
    local CROUCH_IDLE_ANIMID  = "rbxassetid://107078800928182"
    local CROUCH_WALK_ANIMID  = "rbxassetid://137525751454426"
    local CROUCH_BTN_IMG      = "rbxassetid://109660173469064"
