    local _noclipCache, _noclipCacheChar = {}, nil
    local function _rebuildNoclipCache(char)
        _noclipCache = {}
        _noclipCacheChar = char
        for _, v in ipairs(char:GetDescendants()) do
            if v:IsA("BasePart") and _noclipNames[v.Name] then
                _noclipCache[#_noclipCache + 1] = v
            end
        end
    end
    protSec:CreateToggle({
