    local walkOnWaterActive = false
    local waterPad, waterConn = nil, nil
    protSec:CreateToggle({
        Title = "Walk On Water",
        Subtitle = "Walk on water",
        Default = false,
        Callback = function(state)
            walkOnWaterActive = state
            if state then
                if not waterPad then
                    waterPad = Instance.new("Part")
                    waterPad.Size = Vector3.new(6, 0.5, 6)
                    waterPad.Transparency = 1
                    waterPad.Anchored = true
                    waterPad.CanCollide = true
                    waterPad.Massless = true
                    waterPad.CastShadow = false
                    waterPad.Name = "TerrainWaterSurface"
                    waterPad.Parent = workspace
                end
                if not waterConn then
                    local waterParams = RaycastParams.new()
                    local char = getChar()
                    waterParams.FilterDescendantsInstances = { char, waterPad }
                    waterParams.FilterType = Enum.RaycastFilterType.Exclude
                    waterParams.IgnoreWater = false
                    local _waterDown = Vector3.new(0, -10, 0)
                    waterConn = DirectConnect(GetSignal(RunService, "Heartbeat"), function()
                        if not walkOnWaterActive then return end
                        local root = getRoot()
                        if not root then return end
                        local ray = workspace:Raycast(root.Position, _waterDown, waterParams)
                        if ray and ray.Material == Enum.Material.Water then
                            waterPad.CFrame = CFrame.new(root.Position.X, ray.Position.Y - 0.2, root.Position.Z)
                            waterPad.CanCollide = true
                        else
                            waterPad.CFrame = CFrame.new(0, -9999, 0)
                            waterPad.CanCollide = false
                        end
                    end)
                end
            else
                if waterConn then pcall(function() waterConn:Disconnect() end) waterConn = nil end
                if waterPad  then pcall(function() waterPad:Destroy() end)   waterPad  = nil end
            end
