    local antiKickEnabled = false
    local antiKickHooked  = false
    protSec:CreateToggle({
        Title = "Anti-Kick",
        Subtitle = "Block kick, auto rejoin",
        Default = false,
        Callback = function(state)
            antiKickEnabled = state
            if state and not antiKickHooked and LocalPlayer then
                antiKickHooked = true
                pcall(function()
                    local oldKick = LocalPlayer.Kick
                    LocalPlayer.Kick = function(self, msg)
                        if antiKickEnabled then
                            warn("[JEYHUB] Kick prevented! Message: " .. tostring(msg))
                            return
                        end
                        return oldKick(self, msg)
                    end
                end)
                SafeConnect(GetSignal(LocalPlayer, "AncestryChanged"), function()
                    if antiKickEnabled and not LocalPlayer.Parent and TeleportSvc then
                        warn("[JEYHUB] Detected kick, attempting rejoin...")
                        task.wait(0.5)
                        pcall(function() TeleportSvc:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer) end)
                    end
                end)
            end
        end,
    })
    DirectConnect(GetSignal(RunService, "Heartbeat"), function()
        local anyActive = godModeEnabled or antiVoidEnabled or noFallEnabled
            or _linkedAntiSitActive or _usefullAntiFlingActive or _usefullAntiRagdollActive
        if not anyActive then return end
        local hum  = getHum()
        local root = getRoot()
        if godModeEnabled and hum then
            pcall(function()
                hum.Health = hum.MaxHealth
                hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
            end)
        end
        if antiVoidEnabled and root then
            local _voidThreshold = (workspace.FallenPartsDestroyHeight or -500) + 50
            if root.Position.Y < _voidThreshold then
                root.CFrame = root.CFrame + Vector3.new(0, 250, 0)
                root.AssemblyLinearVelocity = Vector3.new()
            end
        end
        if noFallEnabled and hum then
            pcall(function()
                hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
            end)
        end
        if _linkedAntiSitActive and hum then
            pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Seated, false) end)
            if hum.Sit then hum.Sit = false end
        end
        if _usefullAntiRagdollActive and hum then
            pcall(function()
                hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
                hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
                hum:SetStateEnabled(Enum.HumanoidStateType.Physics, false)
                hum.PlatformStand = false
                local st = hum:GetState()
                if st == Enum.HumanoidStateType.Ragdoll
                    or st == Enum.HumanoidStateType.FallingDown
                    or st == Enum.HumanoidStateType.Physics then
                    hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                end
            end)
        end
        if _usefullAntiFlingActive and root then
            local linMag = root.AssemblyLinearVelocity.Magnitude
            local angMag = root.AssemblyAngularVelocity.Magnitude
            if linMag > 250 or angMag > 250 then
                local safeY = math.clamp(root.AssemblyLinearVelocity.Y, -80, 80)
                root.AssemblyLinearVelocity  = Vector3.new(0, safeY, 0)
                root.AssemblyAngularVelocity = Vector3.zero
            end
        end
    end)
    protSec:CreateToggle({
