    local MktSvc = SafeService("MarketplaceService")
    local _cachedGameName = nil
    task.spawn(function()
        if MktSvc then
            local ok, info = pcall(function()
                return MktSvc:GetProductInfo(game.PlaceId, Enum.InfoType.Asset)
            end)
            if ok and info and type(info.Name) == "string" and #info.Name > 0 then
                _cachedGameName = info.Name
            end
        end
    end)
    local _MONTHS = {
        "January","February","March","April","May","June",
        "July","August","September","October","November","December"
    }
    local function getGameName()
        if _cachedGameName then return _cachedGameName end
        local n = game.Name
        if type(n) == "string" and #n > 0 and n ~= "UGC" and n ~= "Untitled Game" then return n end
        return "PlaceId " .. tostring(game.PlaceId)
    end
    local function humanDate()
        local d = os.date("*t")
        local h = d.hour % 12
        if h == 0 then h = 12 end
        local ampm = d.hour >= 12 and "PM" or "AM"
        return _MONTHS[d.month] .. " " .. d.day .. ", " .. d.year
            .. " at " .. h .. ":" .. string.format("%02d", d.min) .. " " .. ampm
    end
    local function buildText(plr, cat)
        local pool   = cat.reasons
        local reason = pool[math.random(1, #pool)]
        local text = "Player: " .. plr.DisplayName .. " (@" .. plr.Name .. ")\n"
            .. "Game: "              .. getGameName()  .. "\n"
            .. "Date reported: "     .. humanDate()    .. "\n"
            .. "Reason for report: " .. cat.label      .. "\n\n"
            .. reason
        if #text > 999 then text = text:sub(1, 996) .. "..." end
        return text
    end
