    local _ESP = {
        Enabled    = false,
        Box        = { Enabled = false, Fill = false },
        Name       = { Enabled = false, Distance = false, Tool = false },
        HealthBar  = { Enabled = false, Side = "Left" },
        Tracer     = { Enabled = false, Origin = "Bottom" },
        HeadDot    = { Enabled = false },
        Skeleton   = { Enabled = false },
        Highlight  = { Enabled = false, HealthColor = false },
        TeamCheck  = false,
        AliveCheck = true,
        Rainbow    = false,
        Color      = Color3.fromRGB(255, 255, 255),
    }
    local _rainbowHue = 0
    local _espObjects = {}
    local function _getESPColor()
        if _ESP.Rainbow then return Color3.fromHSV(_rainbowHue, 1, 1) end
        return _ESP.Color
    end
    local function _hpColor(hp, maxHp)
        local r = math.clamp(hp / math.max(maxHp, 1), 0, 1)
        return Color3.fromRGB(math.floor(255*(1-r)), math.floor(255*r), 0)
    end
    local R6_BONES = {
        {"Head","Torso"},{"Torso","Left Arm"},{"Torso","Right Arm"},
        {"Torso","Left Leg"},{"Torso","Right Leg"},
    }
    local R15_BONES = {
        {"Head","UpperTorso"},{"UpperTorso","LowerTorso"},
        {"UpperTorso","LeftUpperArm"},{"LeftUpperArm","LeftLowerArm"},{"LeftLowerArm","LeftHand"},
        {"UpperTorso","RightUpperArm"},{"RightUpperArm","RightLowerArm"},{"RightLowerArm","RightHand"},
        {"LowerTorso","LeftUpperLeg"},{"LeftUpperLeg","LeftLowerLeg"},{"LeftLowerLeg","LeftFoot"},
        {"LowerTorso","RightUpperLeg"},{"RightUpperLeg","RightLowerLeg"},{"RightLowerLeg","RightFoot"},
    }
    local MAX_BONES = #R15_BONES
    local function _nd(class, props)
        local d = Drawing.new(class)
        for k,v in pairs(props) do d[k]=v end
        return d
    end
    local _FONT = (Drawing.Fonts and Drawing.Fonts.UI) or 0
    local _HITBOX_EDGES = {
        {1,2},{1,5},{2,6},{5,6},
        {3,4},{3,7},{4,8},{7,8},
        {1,3},{2,4},{5,7},{6,8},
    }
    local function _makeESPObj()
        local obj = {
            hitboxEdges = {},
            nameTxt  = _nd("Text",{Visible=false,Size=13,Center=true,Outline=true,Font=_FONT}),
            distTxt  = _nd("Text",{Visible=false,Size=11,Center=true,Outline=true,Font=_FONT}),
            toolTxt  = _nd("Text",{Visible=false,Size=11,Center=true,Outline=true,Font=_FONT}),
            hpBg     = _nd("Square",{Visible=false,Thickness=1,Filled=true,Color=Color3.new(0,0,0),Transparency=0.55}),
            hpBar    = _nd("Square",{Visible=false,Thickness=0,Filled=true}),
            tracer   = _nd("Line",{Visible=false,Thickness=1}),
            headDot  = _nd("Circle",{Visible=false,Filled=true,Thickness=0,Radius=4}),
            bones    = {},
            highlight= nil,
        }
        for i=1,12 do obj.hitboxEdges[i]=_nd("Line",{Visible=false,Thickness=1}) end
        for i=1,MAX_BONES do obj.bones[i]=_nd("Line",{Visible=false,Thickness=1}) end
        pcall(function()
            local h=Instance.new("Highlight")
            h.FillTransparency=0.5 h.OutlineTransparency=0
            h.Enabled=false h.Parent=workspace
            obj.highlight=h
        end)
        return obj
    end
    local function _destroyESPObj(obj)
        if not obj then return end
        for _,l in ipairs(obj.hitboxEdges) do pcall(function() l:Remove() end) end
        pcall(function() obj.nameTxt:Remove() end)
        pcall(function() obj.distTxt:Remove() end)
        pcall(function() obj.toolTxt:Remove() end)
        pcall(function() obj.hpBg:Remove()    end)
        pcall(function() obj.hpBar:Remove()   end)
        pcall(function() obj.tracer:Remove()  end)
        pcall(function() obj.headDot:Remove() end)
        for _,l in ipairs(obj.bones) do pcall(function() l:Remove() end) end
        if obj.highlight then pcall(function() obj.highlight:Destroy() end) end
    end
    local function _hideESP(obj)
        for _,l in ipairs(obj.hitboxEdges) do l.Visible=false end
        obj.nameTxt.Visible=false obj.distTxt.Visible=false obj.toolTxt.Visible=false
        obj.hpBg.Visible=false obj.hpBar.Visible=false
        obj.tracer.Visible=false obj.headDot.Visible=false
        for _,l in ipairs(obj.bones) do l.Visible=false end
        if obj.highlight then pcall(function() obj.highlight.Enabled=false end) end
    end
    local function _w2s(pos, cam)
        local p,vis=cam:WorldToViewportPoint(pos)
        return p.X,p.Y,p.Z,vis
    end
    local function _bbox(char, cam)
        local mn,mx=Vector2.new(math.huge,math.huge),Vector2.new(-math.huge,-math.huge)
        local found=false
        local function chk(p3)
            local sx,sy,sz,_=_w2s(p3,cam)
            if sz>0 then
                mn=Vector2.new(math.min(mn.X,sx),math.min(mn.Y,sy))
                mx=Vector2.new(math.max(mx.X,sx),math.max(mx.Y,sy))
                found=true
            end
        end
        local root=char:FindFirstChild("HumanoidRootPart")
        local head=char:FindFirstChild("Head")
        if root then
            local p=root.Position
            chk(p+Vector3.new( 1.5,0, 1.5)) chk(p+Vector3.new(-1.5,0, 1.5))
            chk(p+Vector3.new( 1.5,0,-1.5)) chk(p+Vector3.new(-1.5,0,-1.5))
            chk(p+Vector3.new(0,-3,0))
        end
        if head then chk(head.Position+Vector3.new(0,1.5,0)) end
        if not found then return nil end
        return mn.X,mn.Y,mx.X,mx.Y
    end
    local function _get3DBBox(char)
        local mnX,mnY,mnZ = math.huge,math.huge,math.huge
        local mxX,mxY,mxZ = -math.huge,-math.huge,-math.huge
        local found = false
        for _,part in ipairs(char:GetChildren()) do
            if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                local p = part.Position
                local s = part.Size * 0.5
                if p.X-s.X < mnX then mnX=p.X-s.X end
                if p.Y-s.Y < mnY then mnY=p.Y-s.Y end
                if p.Z-s.Z < mnZ then mnZ=p.Z-s.Z end
                if p.X+s.X > mxX then mxX=p.X+s.X end
                if p.Y+s.Y > mxY then mxY=p.Y+s.Y end
                if p.Z+s.Z > mxZ then mxZ=p.Z+s.Z end
                found = true
            end
        end
        if not found then return nil end
        return {
            Vector3.new(mnX,mnY,mnZ), Vector3.new(mxX,mnY,mnZ),
            Vector3.new(mnX,mxY,mnZ), Vector3.new(mxX,mxY,mnZ),
            Vector3.new(mnX,mnY,mxZ), Vector3.new(mxX,mnY,mxZ),
            Vector3.new(mnX,mxY,mxZ), Vector3.new(mxX,mxY,mxZ),
        }
    end
    local function _draw3DHitbox(obj, corners3D, cam, col)
        local screen = {}
        for i,v in ipairs(corners3D) do
            local sx,sy,sz,sv = _w2s(v,cam)
            if sz <= 0 then
                for _,l in ipairs(obj.hitboxEdges) do l.Visible=false end
                return
            end
            screen[i] = {x=sx, y=sy, v=sv}
        end
        for i,edge in ipairs(_HITBOX_EDGES) do
            local a,b = screen[edge[1]], screen[edge[2]]
            local ln = obj.hitboxEdges[i]
            if a and b and a.v and b.v then
                ln.From=Vector2.new(a.x,a.y)
                ln.To=Vector2.new(b.x,b.y)
                ln.Color=col ln.Thickness=1 ln.Visible=true
            else ln.Visible=false end
        end
    end
    local function _updateESP(player, obj, cam, lp)
        local char=player.Character
        if not char then _hideESP(obj) return end
        local hum=char:FindFirstChildOfClass("Humanoid")
        if not hum then _hideESP(obj) return end
        if _ESP.AliveCheck and hum.Health<=0 then _hideESP(obj) return end
        if _ESP.TeamCheck and player.Team~=nil and player.Team==lp.Team then _hideESP(obj) return end
        local root=char:FindFirstChild("HumanoidRootPart")
        if not root then _hideESP(obj) return end
        local _,_,depth,onScr=_w2s(root.Position,cam)
        if not onScr or depth<=0 then _hideESP(obj) return end
        local col=_getESPColor()
        local hpR=math.clamp(hum.Health/math.max(hum.MaxHealth,1),0,1)
        local hpC=_hpColor(hum.Health,hum.MaxHealth)
        local dist=math.floor((root.Position-cam.CFrame.Position).Magnitude)
        local x1,y1,x2,y2=_bbox(char,cam)
        if not x1 then _hideESP(obj) return end
        local bw,bh=x2-x1,y2-y1
        local cx=(x1+x2)*0.5
        if _ESP.Box.Enabled then
            local corners3D = _get3DBBox(char)
            if corners3D then
                _draw3DHitbox(obj, corners3D, cam, col)
            else
                for _,l in ipairs(obj.hitboxEdges) do l.Visible=false end
            end
        else
            for _,l in ipairs(obj.hitboxEdges) do l.Visible=false end
        end
        if _ESP.Name.Enabled then
            local label=player.DisplayName~=player.Name
                and (player.DisplayName.." (@"..player.Name..")")
                or player.Name
            obj.nameTxt.Text=label
            obj.nameTxt.Position=Vector2.new(cx,y1-15)
            obj.nameTxt.Color=col obj.nameTxt.Visible=true
        else obj.nameTxt.Visible=false end
        if _ESP.Name.Distance then
            obj.distTxt.Text=tostring(dist).." studs"
            obj.distTxt.Position=Vector2.new(cx,y2+3)
            obj.distTxt.Color=col obj.distTxt.Visible=true
        else obj.distTxt.Visible=false end
        if _ESP.Name.Tool then
            local tool=char:FindFirstChildOfClass("Tool")
            if tool then
                obj.toolTxt.Text="["..tool.Name.."]"
                obj.toolTxt.Position=Vector2.new(cx,y2+15)
                obj.toolTxt.Color=col obj.toolTxt.Visible=true
            else obj.toolTxt.Visible=false end
        else obj.toolTxt.Visible=false end
        if _ESP.HealthBar.Enabled then
            local side=_ESP.HealthBar.Side
            local bx,by,sw,sh
            if side=="Left" then
                sw,sh,bx,by=4,bh,x1-7,y1
            elseif side=="Right" then
                sw,sh,bx,by=4,bh,x2+3,y1
            elseif side=="Top" then
                sw,sh,bx,by=bw,4,x1,y1-7
            else
                sw,sh,bx,by=bw,4,x1,y2+3
            end
            obj.hpBg.Position=Vector2.new(bx,by)
            obj.hpBg.Size=Vector2.new(sw,sh)
            obj.hpBg.Visible=true
            local fw=(side=="Left" or side=="Right") and sw or sw*hpR
            local fh=(side=="Left" or side=="Right") and sh*hpR or sh
            local fy=(side=="Left" or side=="Right") and (by+sh-fh) or by
            obj.hpBar.Position=Vector2.new(bx,fy)
            obj.hpBar.Size=Vector2.new(fw,fh)
            obj.hpBar.Color=hpC obj.hpBar.Visible=true
        else
            obj.hpBg.Visible=false obj.hpBar.Visible=false
        end
        if _ESP.Tracer.Enabled then
            local vp=cam.ViewportSize
            local orig
            if _ESP.Tracer.Origin=="Center" then
                orig=Vector2.new(vp.X*0.5,vp.Y*0.5)
            elseif _ESP.Tracer.Origin=="Top" then
                orig=Vector2.new(vp.X*0.5,0)
            elseif _ESP.Tracer.Origin=="Screen Left" then
                local sx2,sy2=_w2s(root.Position,cam)
                orig=Vector2.new(0,sy2)
            elseif _ESP.Tracer.Origin=="Screen Right" then
                local sx2,sy2=_w2s(root.Position,cam)
                orig=Vector2.new(vp.X,sy2)
            elseif _ESP.Tracer.Origin=="Mouse" then
                local mp=game:GetService("UserInputService"):GetMouseLocation()
                orig=Vector2.new(mp.X,mp.Y)
            else
                orig=Vector2.new(vp.X*0.5,vp.Y)
            end
            local sx,sy=_w2s(root.Position,cam)
            obj.tracer.From=orig obj.tracer.To=Vector2.new(sx,sy)
            obj.tracer.Color=col obj.tracer.Visible=true
        else obj.tracer.Visible=false end
        if _ESP.HeadDot.Enabled then
            local head=char:FindFirstChild("Head")
            if head then
                local hx,hy,_,hv=_w2s(head.Position,cam)
                if hv then
                    obj.headDot.Position=Vector2.new(hx,hy)
                    obj.headDot.Radius=math.clamp(350/depth,2,9)
                    obj.headDot.Color=col obj.headDot.Visible=true
                else obj.headDot.Visible=false end
            else obj.headDot.Visible=false end
        else obj.headDot.Visible=false end
        if _ESP.Skeleton.Enabled then
            local isR15=char:FindFirstChild("UpperTorso")~=nil
            local bones=isR15 and R15_BONES or R6_BONES
            for i,line in ipairs(obj.bones) do
                local b=bones[i]
                if b then
                    local pA=char:FindFirstChild(b[1])
                    local pB=char:FindFirstChild(b[2])
                    if pA and pB then
                        local ax,ay,_,av=_w2s(pA.Position,cam)
                        local bx,by,_,bv=_w2s(pB.Position,cam)
                        if av and bv then
                            line.From=Vector2.new(ax,ay) line.To=Vector2.new(bx,by)
                            line.Color=col line.Visible=true
                        else line.Visible=false end
                    else line.Visible=false end
                else line.Visible=false end
            end
        else for _,l in ipairs(obj.bones) do l.Visible=false end end
        if obj.highlight then
            local boxFillActive = _ESP.Box.Enabled and _ESP.Box.Fill
            local hlActive = _ESP.Highlight.Enabled
            if boxFillActive or hlActive then
                obj.highlight.Adornee=char
                if hlActive then
                    local fc=_ESP.Highlight.HealthColor and hpC or col
                    obj.highlight.FillColor=fc
                    obj.highlight.OutlineColor=col
                    obj.highlight.OutlineTransparency=0
                    obj.highlight.FillTransparency=0.5
                else
                    obj.highlight.FillColor=col
                    obj.highlight.OutlineTransparency=1
                    obj.highlight.FillTransparency=0.88
                end
                obj.highlight.Enabled=true
            else obj.highlight.Enabled=false end
        end
    end
    for _,p in ipairs(Players:GetPlayers()) do
        if p~=LocalPlayer then _espObjects[p]=_makeESPObj() end
    end
    SafeConnect(GetSignal(Players,"PlayerAdded"), function(p)
        if p~=LocalPlayer then _espObjects[p]=_makeESPObj() end
    end)
    SafeConnect(GetSignal(Players,"PlayerRemoving"), function(p)
        if _espObjects[p] then _destroyESPObj(_espObjects[p]) _espObjects[p]=nil end
    end)
    DirectConnect(GetSignal(RunService,"RenderStepped"), function(dt)
        if _ESP.Rainbow then _rainbowHue=(_rainbowHue+dt*0.4)%1 end
        if not _ESP.Enabled then
            for _,obj in pairs(_espObjects) do _hideESP(obj) end
            return
        end
        local cam=workspace.CurrentCamera
        if not cam then return end
        local lp=LocalPlayer
        for _,p in ipairs(Players:GetPlayers()) do
            if p~=LocalPlayer and not _espObjects[p] then
                _espObjects[p]=_makeESPObj()
            end
        end
        for p,obj in pairs(_espObjects) do
            if not p.Parent then
                _destroyESPObj(obj) _espObjects[p]=nil
            else
                pcall(_updateESP,p,obj,cam,lp)
            end
        end
    end)
