            drw.Box.Filled = false
            drw.BoxOutline.Thickness  = 1.5
            drw.BoxOutline.Filled = false
            drw.BoxOutline.Color      = Color3.new(0, 0, 0)
            drw.Name.Size             = 11
            drw.Name.Center = true
            drw.Name.Outline = true
            drw.Name.Font = 2
            drw.Distance.Size         = 10
            drw.Distance.Center = true
            drw.Distance.Outline = true
            drw.Distance.Font = 2
            drw.Distance.Color        = Color3.fromRGB(166, 166, 166)
            drw.HealthOutline.Filled  = true
            drw.HealthOutline.Color = Color3.fromRGB(4, 4, 4)
            drw.HealthOutline.Transparency = 0.2
            drw.HealthBar.Filled      = true
            drw.HealthText.Size       = 9
            drw.HealthText.Center = false
            drw.HealthText.Outline = true
            drw.HealthText.Color      = Color3.fromRGB(254, 254, 254)
            drw.HealthText.Font = 2
            drw.Tracer.Thickness      = 1
            drw.Tracer.Transparency = 0.65
            local charmOk, singleCharm = pcall(function()
                local h = Instance.new("Highlight")
