                drw.Distance.Visible = false
                drw.HealthBar.Visible  = false
                drw.HealthOutline.Visible = false
                drw.HealthText.Visible = false
                drw.Tracer.Visible     = false
                for _, ln in ipairs(drw.SkeletonList) do ln.Visible = false end
                if drw.Charm       then drw.Charm.Enabled = false
                drw.Charm.Parent = game:GetService("CoreGui") end
                if drw.WeaponCharm then drw.WeaponCharm.Enabled = false end
            end
            SafeConnect(GetSignal(RunService, "RenderStepped"), function()
                if not _phys.ESPEnabled then _hideAllDrawings()
                return end
                local tp = _phys.targetPlayer
                if not tp or not tp.Character then _hideAllDrawings()
                return end
                local char = tp.Character
                local hrp  = char:FindFirstChild("HumanoidRootPart")
                local hum  = char:FindFirstChildOfClass("Humanoid")
                local head = char:FindFirstChild("Head") or hrp
                if not hrp or not hum or hum.Health <= 0 then _hideAllDrawings()
                return end
                local cam = workspace.CurrentCamera
                local pos, onScreen = cam:WorldToViewportPoint(hrp.Position)
                if not onScreen then _hideAllDrawings()
                return end
                local gc = SE.ESPColor
                local headPos = cam:WorldToViewportPoint(head.Position + Vector3.new(0, 0.6, 0))
                local footOffset = (hum.HipHeight or 2.0) + 1.35
                local legPos  = cam:WorldToViewportPoint(hrp.Position - Vector3.new(0, footOffset, 0))
                local height  = math.abs(headPos.Y - legPos.Y)
                local rightW  = hrp.CFrame * Vector3.new(0.6, 0, 0)
                local rightS  = cam:WorldToViewportPoint(rightW)
                local width   = math.max(math.abs(rightS.X - pos.X) * 2, height * 0.4)
                if SE.Box then
                    local fillSz = Vector2.new(width, height)
                    local fillPs = Vector2.new(pos.X - width/2, headPos.Y)
                    drw.BoxFill.Size     = fillSz
                    drw.BoxFill.Position = fillPs
                    drw.BoxFill.Color    = gc
                    drw.BoxFill.Transparency = 0.88
                    drw.BoxFill.Visible  = true
                    drw.Box.Size         = fillSz
                    drw.Box.Position = fillPs
                    drw.Box.Color        = gc
                    drw.Box.Visible = true
                    drw.BoxOutline.Size     = drw.Box.Size
                    drw.BoxOutline.Position = drw.Box.Position
                    drw.BoxOutline.Visible  = true
                else
                    drw.BoxFill.Visible = false
                    drw.Box.Visible = false
                    drw.BoxOutline.Visible = false
                end
                if SE.Name then
                    if tp ~= _phys.lastEspTarget then
                        _phys.lastEspTarget  = tp
                        _phys.cachedEspName  = (tp.DisplayName ~= tp.Name)
                            and (tp.DisplayName .. "  @" .. tp.Name) or tp.DisplayName
                    end
                    drw.Name.Text     = _phys.cachedEspName
                    drw.Name.Position = Vector2.new(pos.X, headPos.Y - 14)
                    drw.Name.Color    = gc
                    drw.Name.Visible = true
                else
                    drw.Name.Visible = false
                end
                if SE.Distance then
                    local dist = (cam.CFrame.Position - hrp.Position).Magnitude
                    drw.Distance.Text     = math.floor(dist) .. "m"
                    drw.Distance.Position = Vector2.new(pos.X, headPos.Y + height + 2)
                    drw.Distance.Visible  = true
                else
                    drw.Distance.Visible = false
                end
                if SE.Health then
                    local tH  = hum.Health
                    local mH = hum.MaxHealth
                    _phys.CurrentHealth = _phys.CurrentHealth + (tH - _phys.CurrentHealth) * 0.12
                    local ratio = math.clamp(_phys.CurrentHealth / mH, 0, 1)
                    local r  = math.clamp(2 - ratio * 2, 0, 1)
                    local g  = math.clamp(ratio * 2, 0, 1)
                    local hc = Color3.new(r, g, 0)
                    local bw = 4
                    local ot = 1
                    local bx = pos.X - width/2 - bw - 4 - ot
                    drw.HealthOutline.Size     = Vector2.new(bw + ot*2, height + ot*2)
                    drw.HealthOutline.Position = Vector2.new(bx - ot, headPos.Y - ot)
                    drw.HealthOutline.Visible  = true
                    local bh = math.max(height * ratio, 1)
                    drw.HealthBar.Size     = Vector2.new(bw, bh)
                    drw.HealthBar.Position = Vector2.new(bx, headPos.Y + height - bh)
                    drw.HealthBar.Color    = hc
                    drw.HealthBar.Visible = true
                    drw.HealthText.Text        = tostring(math.floor(_phys.CurrentHealth))
                    drw.HealthText.Position    = Vector2.new(bx - 1, drw.HealthBar.Position.Y - 10)
                    drw.HealthText.Transparency = ratio > 0.98 and 0.6 or 0
                    drw.HealthText.Visible     = true
                else
                    drw.HealthBar.Visible = false
                    drw.HealthOutline.Visible = false
                    drw.HealthText.Visible = false
                end
