                        local p1 = char:FindFirstChild(joint[1])
                        local p2 = char:FindFirstChild(joint[2])
                        if p1 and p2 then
                            local s1, v1 = cam:WorldToViewportPoint(p1.Position)
                            local s2, v2 = cam:WorldToViewportPoint(p2.Position)
                            if v1 or v2 then
                                drw.SkeletonList[i].From    = Vector2.new(s1.X, s1.Y)
                                drw.SkeletonList[i].To      = Vector2.new(s2.X, s2.Y)
                                drw.SkeletonList[i].Color   = gc
                                drw.SkeletonList[i].Visible = true
