                        drw.WeaponCharm.FillColor    = gc
                        drw.WeaponCharm.OutlineColor = gc
                        drw.WeaponCharm.Enabled      = true
                    else
                        if drw.WeaponCharm then drw.WeaponCharm.Enabled = false end
                    end
                else
                    if drw.WeaponCharm then drw.WeaponCharm.Enabled = false end
                end
            end)
        end
        local function _onToolEquipped(child)
            if _phys.ghostThrow and child:IsA("Tool") then
                task.defer(function()
                    if child.Parent==LocalPlayer.Character then
                        child:Activate()
                        local h2=LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                        if h2 then h2:UnequipTools() end
                    end
                end)
            end
        end
