    local function physRefreshPlayers()
        for _, c in ipairs(physPlrScroll:GetChildren()) do
            if c:IsA("Frame") then c:Destroy() end
        end
        physPlrBtns  = {}
        physPlrOrder = 0
        local count  = 0
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer then
                buildPhysPlayerRow(plr)
                count = count + 1
            end
        end
        physPlrScroll.CanvasSize = UDim2.new(0, 0, 0, count * 30)
        if _phys.targetPlayer and not _phys.targetPlayer.Parent then
            physSetTarget(nil)
        end
    end
