    end)
    local function doManualSearch()
        local kw = manualBox.Text
        if kw == "" then return end
        local found = findPlayer(kw)
        if found then
            for _, fn in pairs(physPlrBtns) do fn(false) end
            if physPlrBtns[found] then physPlrBtns[found](true) end
            physSetTarget(found)
            manualBox.Text = ""
        else
            local prev       = physSelLabel.Text
            local prevColor  = physSelLabel.TextColor3
            physSelLabel.Text       = "Tidak ditemukan: \"" .. kw .. "\""
            physSelLabel.TextColor3 = Color3.fromRGB(196, 130, 30)
            task.delay(1.5, function()
                physSelLabel.Text       = _phys.targetPlayer
                    and (_phys.targetPlayer.DisplayName .. "  @" .. _phys.targetPlayer.Name)
                    or  "Belum ada target dipilih"
                physSelLabel.TextColor3 = _phys.targetPlayer and Palette.Text or Palette.SubText
            end)
        end
    end
