    })
    utilSec:CreateToggle({
        Title    = "Invisible",
        Subtitle = "Hide character",
        Default  = false,
        Callback = function(s)
            _phys.isInvisible = s
            local c=LocalPlayer.Character
            local h=c and c:FindFirstChildOfClass("Humanoid")
            local r=c and c:FindFirstChild("HumanoidRootPart")
            if c then
                if s then
                    _phys.invisibleParts={}
                    for _,v in pairs(c:GetDescendants()) do
                        if v:IsA("BasePart") and v.Name~="HumanoidRootPart" and v.Transparency<1 then
                            table.insert(_phys.invisibleParts,v)
                            v.Transparency=0.5
                        end
                    end
                    if not _phys.invisConn then
                        local _savedCF,_savedOff
                        local _ih=SafeConnect(GetSignal(RunService,"Heartbeat"),function()
                            if not _phys.isInvisible or not c or not r or not h then return end
                            _savedCF=r.CFrame
                            _savedOff=h.CameraOffset
                            r.CFrame=_savedCF*CFrame.new(0,-200,0)
                        end)
                        local _ir=SafeConnect(GetSignal(RunService,"RenderStepped"),function()
                            if not _phys.isInvisible or not r or not h then return end
                            if _savedCF then r.CFrame=_savedCF end
                            h.CameraOffset=_savedOff or Vector3.zero
                        end)
                        _phys.invisConn={Disconnect=function() _ih:Disconnect()
                        _ir:Disconnect() end}
                    end
                else
                    for _,v in pairs(_phys.invisibleParts) do v.Transparency=0 end
                    _phys.invisibleParts={}
                    if _phys.invisConn then _phys.invisConn:Disconnect()
                    _phys.invisConn=nil end
                    if h then h.CameraOffset=Vector3.zero end
                end
            end
        end,
    })
    SafeConnect(GetSignal(RunService, "Heartbeat"), function(dt)
        if not _phys.telekinesisActive then return end
        local v3     = Vector3.new
        local cf     = CFrame.new
        local mclamp = math.clamp
        local mmax   = math.max
        local mmin   = math.min
        local mabs   = math.abs
        local msin   = math.sin
        local mcos   = math.cos
        local mrand  = math.random
        local mexp   = math.exp
        local dtC    = mclamp(dt or 0.016, 0.008, 0.083)
        local lchar  = LocalPlayer.Character
        local myHrp  = lchar and lchar:FindFirstChild("HumanoidRootPart")
        if not myHrp then return end
        if sethiddenproperty then
            pcall(function() sethiddenproperty(LocalPlayer, "SimulationRadius", 9e9) end)
        end
        _phys.telek_frame = _phys.telek_frame + 1
        local fr      = _phys.telek_frame
        local doOwn   = (fr % 15 == 0)
        local doApply = (fr % 6  == 0)
        local doGrav  = _phys.telekinesisGravComp and (fr % 2 == 0)
        if not doOwn and not doApply and not doGrav then return end
        local radius      = _phys.telekinesisRadius
        local force       = _phys.telekinesisForce
        local chaosForce  = _phys.telekinisChaosForce
        local spinRate    = _phys.telekinesisSpinRate
        local chaosRate   = _phys.telekinisChaosRate
        local orbitRadius = _phys.telekinesisOrbitRadius
        local orbitHeight = _phys.telekinesisOrbitHeight
        local liftBias    = _phys.telekinesisLiftBias
        local mode        = _phys.telekinesisMode
        local hrpPos      = myHrp.Position
        local now         = tick()
        do
            local vel = myHrp.AssemblyLinearVelocity
            local a   = 1 - mexp(-25 * dtC)
            _phys.telek_sVel = _phys.telek_sVel:Lerp(vel, a)
        end
        local hrpVelPred = hrpPos + _phys.telek_sVel * dtC * 1.8
        local doWave = false
        if _phys.telek_wavePulse and doApply then
            if (now - _phys.telek_lastWave) >= _phys.telek_waveInterval then
                _phys.telek_lastWave = now
                doWave = true
            end
        end
        local op = OverlapParams.new()
        op.FilterDescendantsInstances = {lchar}
        op.FilterType = Enum.RaycastFilterType.Exclude
        local parts = workspace:GetPartBoundsInRadius(hrpPos, radius, op)
        local gravDelta = v3(0, workspace.Gravity * 2 * dtC, 0)
        local GOLDEN = 2.399
        local idx = 0
        for _, obj in ipairs(parts) do
            repeat
            if not obj or not obj.Parent then break end
            if obj.Anchored then break end
            if _phys.telek_filterSize then
                local sz = obj.Size
                local longest = mmax(sz.X, sz.Y, sz.Z)
                if longest < _phys.telek_minSize or longest > _phys.telek_maxSize then break end
            end
            local skip = false
            local p = obj.Parent
            while p do
                if p:IsA("Model") and p:FindFirstChildOfClass("Humanoid") then skip = true
                break end
                if p:IsA("Backpack") or p:IsA("Accessory") then skip = true
                break end
                p = p.Parent
            end
            if skip then break end
            idx = idx + 1
            pcall(function()
                if not _phys.telek_ownedSet[obj] then
                    if _phys.telekAutoRestore and not _phys.telek_savedState[obj] then
                        _phys.telek_savedState[obj] = {
                            cframe     = obj.CFrame,
                            anchored   = obj.Anchored,
                            canCollide = obj.CanCollide,
                        }
                    end
                    if sethiddenproperty then
                        sethiddenproperty(obj, "NetworkOwnership", LocalPlayer)
                        sethiddenproperty(obj, "NetworkIsSleeping", false)
                    end
                    pcall(function() obj:SetNetworkOwner(LocalPlayer) end)
                    obj.Anchored   = false
                    obj.CanCollide = false
                    pcall(function()
                        obj.Massless = true
                        obj.CustomPhysicalProperties = PhysicalProperties.new(0.01, 0, 0, 0, 0)
                    end)
                    _phys.telek_ownedSet[obj] = true
                    pcall(function()
                        local function _telek_breakWeakWelds(part)
                            for _, w in ipairs(part:GetChildren()) do
                                if w:IsA("WeldConstraint") or w:IsA("Weld") then
                                    pcall(function() w:Destroy() end)
                                end
                            end
                            local _wpar = part.Parent
                            if _wpar then
                                for _, w in ipairs(_wpar:GetChildren()) do
                                    if (w:IsA("WeldConstraint") or w:IsA("Weld"))
                                       and (w.Part0 == part or w.Part1 == part) then
                                        pcall(function() w:Destroy() end)
                                    end
                                end
                            end
                        end
                        _telek_breakWeakWelds(obj)
                        for _, c in ipairs(obj:GetChildren()) do
                            if (c:IsA("HingeConstraint") or c:IsA("BallSocketConstraint")
                                or c:IsA("CylindricalConstraint")) and c.Enabled then
                                c.Enabled = false
                                _phys.telek_disabledConstraints[c] = true
                            end
                        end
                        local _par = obj.Parent
                        if _par then
                            for _, c in ipairs(_par:GetChildren()) do
                                if (c:IsA("HingeConstraint") or c:IsA("BallSocketConstraint")
                                    or c:IsA("CylindricalConstraint")) and c.Enabled
                                   and c.Attachment0 and c.Attachment1
                                   and (c.Attachment0:IsDescendantOf(obj)
                                        or c.Attachment1:IsDescendantOf(obj)) then
                                    c.Enabled = false
                                    _phys.telek_disabledConstraints[c] = true
                                end
                            end
                        end
                        local aRoot = obj.AssemblyRootPart
                        if aRoot and aRoot ~= obj then
                            _telek_breakWeakWelds(aRoot)
                            if sethiddenproperty then
                                sethiddenproperty(aRoot, "NetworkOwnership", LocalPlayer)
                                sethiddenproperty(aRoot, "NetworkIsSleeping", false)
                            end
                            pcall(function() aRoot:SetNetworkOwner(LocalPlayer) end)
                            aRoot.Anchored   = false
                            aRoot.CanCollide = false
                            pcall(function()
                                aRoot.Massless = true
                                aRoot.CustomPhysicalProperties = PhysicalProperties.new(0.01, 0, 0, 0, 0)
                            end)
                        end
                    end)
                elseif doOwn then
                    pcall(function() obj:SetNetworkOwner(LocalPlayer) end)
                    obj.Anchored   = false
                    obj.CanCollide = false
                end
                if doGrav then
                    obj.AssemblyLinearVelocity = obj.AssemblyLinearVelocity + gravDelta
                end
                if doWave then
                    local diff = obj.Position - hrpPos
                    local dmag = diff.Magnitude
                    local dir  = dmag > 0.1 and (diff / dmag)
                                 or v3(mrand()-0.5, mrand()*0.5+0.3, mrand()-0.5).Unit
                    local wf = _phys.telek_waveForce
                    obj.AssemblyLinearVelocity  = dir * wf
                    obj.AssemblyAngularVelocity = v3(
                        (mrand()*2-1) * wf * 0.3,
                        (mrand()*2-1) * wf * 0.3,
                        (mrand()*2-1) * wf * 0.3
                    )
                    return
                end
                if not doApply then return end
                local lastHit = _phys.telek_claimed[obj] or 0
                if (now - lastHit) < chaosRate then return end
                _phys.telek_claimed[obj] = now
                local diff = obj.Position - hrpPos
                local dist = diff.Magnitude
                local dirOut = dist > 0.1 and (diff / dist) or v3(0, 1, 0)
                if mode == "freeze" then
                    obj.AssemblyLinearVelocity  = Vector3.zero
                    obj.AssemblyAngularVelocity = Vector3.zero
                elseif mode == "pull" then
                    local toTarget = -diff
                    local mathVel  = toTarget / dtC
                    local pullVel  = toTarget.Unit * (force * (1 + dist / mmax(radius, 1)))
                    if dist < 18 then
                        obj.AssemblyLinearVelocity = toTarget.Unit * (force * 3.5)
                    else
                        obj.AssemblyLinearVelocity = mathVel:Lerp(pullVel, 0.35)
                    end
                    obj.AssemblyAngularVelocity = v3(
                        (mrand()*2-1) * force * spinRate * 0.3,
                        (mrand()*2-1) * force * spinRate * 0.3,
                        (mrand()*2-1) * force * spinRate * 0.3
                    )
                elseif mode == "repel" then
                    local repelForce = force * (1 + (radius - dist) / mmax(radius, 1))
                    obj.AssemblyLinearVelocity  = dirOut * repelForce
                                                  + v3(0, force * liftBias * 0.4, 0)
                    obj.AssemblyAngularVelocity = v3(
                        (mrand()*2-1) * force * spinRate * 0.5,
                        (mrand()*2-1) * force * spinRate * 0.5,
                        (mrand()*2-1) * force * spinRate * 0.5
                    )
                elseif mode == "vortex" then
                    local angle = (idx * GOLDEN) + now * 0.35
                    _phys.telek_vortexAngle = angle
                    if dist < orbitRadius * 0.4 and dist > 0.5 then
                        if dist < 4 then
                            local snapTarget = hrpVelPred + v3(mcos(angle)*1.2, 0, msin(angle)*1.2)
                            local toSnap = snapTarget - obj.Position
                            obj.AssemblyLinearVelocity  = toSnap / mmax(dtC, 0.016)
                            obj.AssemblyAngularVelocity = Vector3.zero
                        else
                            obj.AssemblyLinearVelocity  = dirOut * (force + chaosForce)
                            obj.AssemblyAngularVelocity = v3(
                                (mrand()*2-1) * force * spinRate,
                                (mrand()*2-1) * force * spinRate,
                                (mrand()*2-1) * force * spinRate
                            )
                        end
                    else
                        local inward  = -dirOut * force * 0.6
                        local tangent = v3(mcos(angle), 0, msin(angle))
                        local lift    = v3(0, force * liftBias * 0.25, 0)
                        obj.AssemblyLinearVelocity  = inward + tangent * force * 0.4 + lift
                        obj.AssemblyAngularVelocity = v3(
                            (mrand()*2-1) * force * spinRate * 0.4,
                            force * spinRate * 0.6,
                            (mrand()*2-1) * force * spinRate * 0.4
                        )
                    end
                else
                    local orbitPivot = hrpVelPred + v3(0, orbitHeight, 0)
                    local goldenAngle = (idx * GOLDEN) + now * 0.35
                    local orbitTarget = orbitPivot + v3(
                        mcos(goldenAngle) * orbitRadius,
                        msin(now * 1.7 + idx * 0.55) * 0.3,
                        msin(goldenAngle) * orbitRadius
                    )
                    if dist <= orbitRadius and dist > 0.5 then
                        local toOrbit = orbitTarget - obj.Position
                        local toMag   = toOrbit.Magnitude
                        if toMag < 4 then
                            obj.AssemblyLinearVelocity  = toOrbit / mmax(dtC, 0.016)
                            obj.AssemblyAngularVelocity = Vector3.zero
                        else
                            local radial  = (obj.Position - orbitPivot).Unit
                            local tangent = v3(0, 1, 0):Cross(radial)
                            if tangent.Magnitude < 0.05 then
                                tangent = v3(1, 0, 0):Cross(radial)
                            end
                            tangent = tangent.Unit
                            local orbitSpeed = force * 0.65
                            local inward     = -radial * (force * 0.15)
                            local mathVel    = toOrbit / dtC
                            obj.AssemblyLinearVelocity = mathVel:Lerp(
                                tangent * orbitSpeed + inward + v3(0, force * 0.08, 0), 0.4
                            )
                            obj.AssemblyAngularVelocity = v3(
                                (mrand()*2-1) * force * spinRate * 0.4,
                                force * spinRate * 0.5,
                                (mrand()*2-1) * force * spinRate * 0.4
                            )
                        end
                    else
                        if dist > orbitRadius * 2 then
                            local _teleTarget = orbitPivot + v3(
                                mcos(idx * 1.618) * (orbitRadius * 0.8 + mrand()),
                                mrand() * 1.5,
                                msin(idx * 1.618) * (orbitRadius * 0.8 + mrand())
                            )
                            local _toTele = _teleTarget - obj.Position
                            obj.AssemblyLinearVelocity  = _toTele / mmax(dtC, 0.016)
                            obj.AssemblyAngularVelocity = Vector3.zero
                        else
                            local _inDir  = (hrpVelPred - obj.Position)
                            local _inMag  = _inDir.Magnitude
                            local _inUnit = _inMag > 0.1 and (_inDir / _inMag) or v3(0,1,0)
                            local _jx = (mrand()*2-1) * 0.35
                            local _jy = mrand() * liftBias * 0.45
                            local _jz = (mrand()*2-1) * 0.35
                            local _pullDir  = (_inUnit + v3(_jx, _jy, _jz)).Unit
                            local _distFrac = mmin(dist / mmax(radius, 1), 1)
                            local _scale    = mmin(force * (0.55 + _distFrac * 0.55), force * 1.15)
                            local mathVel  = (orbitTarget - obj.Position) / dtC
                            local constVel = _pullDir * _scale
                            obj.AssemblyLinearVelocity  = mathVel:Lerp(constVel, 0.35)
                            obj.AssemblyAngularVelocity = v3(
                                (mrand()*2-1) * force * spinRate * 0.45,
                                (mrand()*2-1) * force * spinRate * 0.45,
                                (mrand()*2-1) * force * spinRate * 0.45
                            )
                        end
                    end
                end
            end)
            until true
        end
        if fr % 60 == 0 then
            for obj, _ in pairs(_phys.telek_claimed) do
                if not obj or not obj.Parent then
                    _phys.telek_claimed[obj]  = nil
                    _phys.telek_ownedSet[obj] = nil
                end
            end
        end
    end)
    local telekSec = tab:CreateSection("Telekinesis", "5 mode chaos physics \226\128\148 FE synced, wave pulse, gravity comp, size filter")
