            _phys.telekinesisActive = s
            if not s then
                _phys.telek_claimed = {}
                for c, _ in pairs(_phys.telek_disabledConstraints) do
                    pcall(function()
                        if c and c.Parent then c.Enabled = true end
                    end)
                end
                _phys.telek_disabledConstraints = {}
                _phys.telek_ownedSet = {}
                if _phys.telekAutoRestore then
                    for obj, st in pairs(_phys.telek_savedState) do
                        pcall(function()
                            if obj and obj.Parent then
                                obj.AssemblyLinearVelocity  = Vector3.zero
                                obj.AssemblyAngularVelocity = Vector3.zero
                                obj.CFrame     = st.cframe
                                obj.Anchored   = st.anchored
                                obj.CanCollide = st.canCollide
                            end
                        end)
                    end
                    _phys.telek_savedState = {}
                end
            end
            ShowNotification("Telekinesis", s and "Telekinesis aktif" or "Telekinesis nonaktif", 2)
        end,
