    local function _BH_SpawnVisual(pos)
        if _phys.blackhole_visual and _phys.blackhole_visual.Parent then
            pcall(function() _phys.blackhole_visual.Position = pos end)
            return
        end
        local v = Instance.new("Part")
        v.Name             = "_JeyBH_Visual"
        v.Shape            = Enum.PartType.Ball
        v.Size             = Vector3.new(4, 4, 4)
        v.Anchored         = true
        v.CanCollide       = false
        v.CanTouch         = false
        v.CastShadow       = false
        v.Color            = Color3.fromRGB(0, 0, 0)
        v.Transparency     = 0.15
        v.Material         = Enum.Material.Neon
        v.Position         = pos
        local sg = Instance.new("SelectionSphere")
        sg.SurfaceTransparency = 0.7
        sg.SurfaceColor3       = Color3.fromRGB(80, 0, 180)
        sg.Adornee             = v
        sg.Parent              = v
        v.Parent               = workspace
        _phys.blackhole_visual = v
    end
    local function _BH_RemoveVisual()
        if _phys.blackhole_visual then
            pcall(function() _phys.blackhole_visual:Destroy() end)
            _phys.blackhole_visual = nil
        end
    end
    local function _BH_SetPosition(pos)
        _phys.blackholePosition = pos
        if _phys.blackholeActive then
            _BH_SpawnVisual(pos)
        end
    end
    SafeConnect(GetSignal(RunService, "Heartbeat"), function(dt)
        if not _phys.blackholeActive then return end
        local v3     = Vector3.new
        local cf     = CFrame.new
        local mclamp = math.clamp
        local mmax   = math.max
        local mmin   = math.min
        local mrand  = math.random
        local dtC    = mclamp(dt or 0.016, 0.008, 0.083)
        local lchar  = LocalPlayer.Character
        local myHrp  = lchar and lchar:FindFirstChild("HumanoidRootPart")
        if not myHrp then return end
        if sethiddenproperty then
            pcall(function() sethiddenproperty(LocalPlayer, "SimulationRadius", 9e9) end)
        end
        _phys.blackhole_frame = _phys.blackhole_frame + 1
        local fr = _phys.blackhole_frame
        if _phys.blackholeFollowMode == "player" then
            _phys.blackholePosition = myHrp.Position
        elseif _phys.blackholeFollowMode == "look" and fr % 10 == 0 then
            local cam = workspace.CurrentCamera
            if cam then
                local origin = cam.CFrame.Position
                local direction = cam.CFrame.LookVector * (_phys.blackholeRadius * 1.5)
                local rp = RaycastParams.new()
                rp.FilterDescendantsInstances = {lchar}
                rp.FilterType = Enum.RaycastFilterType.Exclude
                local hit = workspace:Raycast(origin, direction, rp)
                if hit then
                    _phys.blackholePosition = hit.Position
                end
            end
        end
        local bhPos  = _phys.blackholePosition
        local radius = _phys.blackholeRadius
        local force  = _phys.blackholePullForce
        local dDist  = _phys.blackholeDestroyDist
        local doOwn  = (fr % 12 == 0)
        local doApply = (fr % 3  == 0)
        if _phys.blackhole_visual and _phys.blackhole_visual.Parent then
            pcall(function() _phys.blackhole_visual.Position = bhPos end)
        end
        local op = OverlapParams.new()
        op.FilterDescendantsInstances = {lchar}
        op.FilterType = Enum.RaycastFilterType.Exclude
        local parts = workspace:GetPartBoundsInRadius(bhPos, radius, op)
        for _, obj in ipairs(parts) do
            repeat
            if not obj or not obj.Parent then break end
            if obj.Anchored then break end
            if obj == _phys.blackhole_visual then break end
            local skipObj = false
            local pp = obj.Parent
            while pp do
                if pp:IsA("Backpack") or pp:IsA("Accessory") then skipObj = true
                break end
                if not _phys.blackholeAffectPlayers
                   and pp:IsA("Model") and pp:FindFirstChildOfClass("Humanoid") then
                    skipObj = true
                    break
                end
                pp = pp.Parent
            end
            if skipObj then break end
            pcall(function()
                if not _phys.bh_ownedSet[obj] then
                    if _phys.blackholeAutoRestore and not _phys.bh_savedState[obj] then
                        _phys.bh_savedState[obj] = {
                            cframe     = obj.CFrame,
                            anchored   = obj.Anchored,
                            canCollide = obj.CanCollide,
                        }
                    end
                    if sethiddenproperty then
                        sethiddenproperty(obj, "NetworkOwnership", LocalPlayer)
                        sethiddenproperty(obj, "NetworkIsSleeping", false)
                    end
                    pcall(function() obj:SetNetworkOwner(LocalPlayer) end)
                    obj.Anchored   = false
                    obj.CanCollide = false
                    pcall(function()
                        obj.Massless = true
                        obj.CustomPhysicalProperties = PhysicalProperties.new(0.01, 0, 0, 0, 0)
                    end)
                    _phys.bh_ownedSet[obj] = true
                    pcall(function()
                        local function _bh_breakWeakWelds(part)
                            for _, w in ipairs(part:GetChildren()) do
                                if w:IsA("WeldConstraint") or w:IsA("Weld") then
                                    pcall(function() w:Destroy() end)
                                end
                            end
                            local _wpar = part.Parent
                            if _wpar then
                                for _, w in ipairs(_wpar:GetChildren()) do
                                    if (w:IsA("WeldConstraint") or w:IsA("Weld"))
                                       and (w.Part0 == part or w.Part1 == part) then
                                        pcall(function() w:Destroy() end)
                                    end
                                end
                            end
                        end
                        _bh_breakWeakWelds(obj)
                        for _, c in ipairs(obj:GetChildren()) do
                            if (c:IsA("HingeConstraint") or c:IsA("BallSocketConstraint")
                                or c:IsA("CylindricalConstraint")) and c.Enabled then
                                c.Enabled = false
                                _phys.bh_disabledConstraints[c] = true
                            end
                        end
                        local _par = obj.Parent
                        if _par then
                            for _, c in ipairs(_par:GetChildren()) do
                                if (c:IsA("HingeConstraint") or c:IsA("BallSocketConstraint")
                                    or c:IsA("CylindricalConstraint")) and c.Enabled
                                   and c.Attachment0 and c.Attachment1
                                   and (c.Attachment0:IsDescendantOf(obj)
                                        or c.Attachment1:IsDescendantOf(obj)) then
                                    c.Enabled = false
                                    _phys.bh_disabledConstraints[c] = true
                                end
                            end
                        end
                        local aRoot = obj.AssemblyRootPart
                        if aRoot and aRoot ~= obj then
                            _bh_breakWeakWelds(aRoot)
                            if sethiddenproperty then
                                sethiddenproperty(aRoot, "NetworkOwnership", LocalPlayer)
                                sethiddenproperty(aRoot, "NetworkIsSleeping", false)
                            end
                            pcall(function() aRoot:SetNetworkOwner(LocalPlayer) end)
                            aRoot.Anchored   = false
                            aRoot.CanCollide = false
                            pcall(function()
                                aRoot.Massless = true
                                aRoot.CustomPhysicalProperties = PhysicalProperties.new(0.01, 0, 0, 0, 0)
                            end)
                        end
                    end)
                elseif doOwn then
                    pcall(function() obj:SetNetworkOwner(LocalPlayer) end)
                    obj.Anchored   = false
                    obj.CanCollide = false
                end
                local diff = bhPos - obj.Position
                local dist = diff.Magnitude
                if dist < 0.1 then return end
                if dist < dDist then
                    if _phys.blackholeBreakWelds then
                        pcall(function()
                            local par = obj.Parent
                            if par then
                                for _, w in ipairs(par:GetChildren()) do
                                    if (w:IsA("WeldConstraint") or w:IsA("Weld") or w:IsA("Motor6D"))
                                       and (w.Part0 == obj or w.Part1 == obj) then
                                        w:Destroy()
                                    end
                                end
                            end
                            for _, w in ipairs(obj:GetChildren()) do
                                if w:IsA("WeldConstraint") or w:IsA("Weld") or w:IsA("Motor6D") then
                                    w:Destroy()
                                end
                            end
                        end)
                    end
                    if _phys.blackholeDestroyParts then
                        pcall(function() obj:Destroy() end)
                        _phys.blackhole_claimed[obj] = nil
                        _phys.blackhole_frozen[obj]  = nil
                        _phys.bh_ownedSet[obj]       = nil
                        return
                    end
                    if _phys.blackholeFreezeAtCore then
                        _phys.blackhole_frozen[obj] = true
                        obj.AssemblyLinearVelocity  = Vector3.zero
                        obj.AssemblyAngularVelocity = Vector3.zero
                        obj.Anchored   = true
                        obj.CanCollide = false
                        return
                    end
                    return
                end
                if not doApply then return end
                local dirIn   = diff.Unit
                local angMult = _phys.blackholeSpinParts and 1 or 0
                local innerZone = dDist * 4.5
                if dist < innerZone then
                    local toCore = bhPos - obj.Position
                    obj.AssemblyLinearVelocity  = toCore / mmax(dtC * 1.2, 0.016)
                    obj.AssemblyAngularVelocity = Vector3.zero
                else
                    local _t = mmax(0, (dist - innerZone) / mmax(radius - innerZone, 1))
                    local _gravity = mmin(force * (0.38 + _t * 0.82), force * 1.6)
                    local mathVel  = diff / dtC
                    local pullVel  = dirIn * _gravity
                    local _up      = v3(0, 1, 0)
                    local _tang    = _up:Cross(dirIn)
                    if _tang.Magnitude > 0.05 then _tang = _tang.Unit else _tang = Vector3.zero end
                    local blended  = mathVel:Lerp(pullVel, 0.35)
                    obj.AssemblyLinearVelocity  = blended + _tang * (_gravity * 0.18 * angMult)
                    obj.AssemblyAngularVelocity = v3(
                        (mrand()*2-1) * _gravity * angMult * 0.3,
                        _gravity * angMult * 0.42,
                        (mrand()*2-1) * _gravity * angMult * 0.3
                    )
                end
                _phys.blackhole_claimed[obj] = true
            end)
            until true
        end
        if _phys.blackholeAffectPlayers and doApply then
            for _, plr in ipairs(Players:GetPlayers()) do
                repeat
                if plr == LocalPlayer then break end
                local pchar = plr.Character
                local phrp  = pchar and pchar:FindFirstChild("HumanoidRootPart")
                if not phrp then break end
                local diff = bhPos - phrp.Position
                local dist = diff.Magnitude
                if dist > radius or dist < 0.1 then break end
                pcall(function()
                    if sethiddenproperty then
                        sethiddenproperty(phrp, "NetworkOwnership", LocalPlayer)
                    end
                    pcall(function() phrp:SetNetworkOwner(LocalPlayer) end)
                    local _t    = mmax(0, (dist - 1) / mmax(radius - 1, 1))
                    local gravity = mmin(force * (0.35 + _t * 0.85), force * 1.5)
                    phrp.AssemblyLinearVelocity = diff.Unit * gravity
                end)
                until true
            end
        end
        if fr % 90 == 0 then
            for obj, _ in pairs(_phys.blackhole_claimed) do
                if not obj or not obj.Parent then
                    _phys.blackhole_claimed[obj] = nil
                    _phys.bh_ownedSet[obj]       = nil
                end
            end
        end
    end)
    local bhSec = tab:CreateSection("Blackhole", "Singularitas gravitasi \226\128\148 tarik semua part & player ke satu titik")
    bhSec:CreateToggle({
        Title    = "Enable Blackhole",
        Subtitle = "Enable singularity at selected position",
        Default  = false,
        Callback = function(s)
            _phys.blackholeActive = s
            if s then
                local lchar = LocalPlayer.Character
                local myHrp = lchar and lchar:FindFirstChild("HumanoidRootPart")
                if myHrp then _phys.blackholePosition = myHrp.Position end
                _BH_SpawnVisual(_phys.blackholePosition)
                ShowNotification("Blackhole", "Singularitas aktif", 2)
            else
                _BH_RemoveVisual()
                for obj, _ in pairs(_phys.blackhole_frozen) do
                    pcall(function()
                        if obj and obj.Parent then
                            obj.Anchored   = false
                            obj.CanCollide = true
                            obj.AssemblyLinearVelocity  = Vector3.zero
                            obj.AssemblyAngularVelocity = Vector3.zero
                        end
                    end)
                end
                _phys.blackhole_frozen = {}
                for c, _ in pairs(_phys.bh_disabledConstraints) do
                    pcall(function()
                        if c and c.Parent then c.Enabled = true end
                    end)
                end
                _phys.bh_disabledConstraints = {}
                _phys.bh_ownedSet = {}
                if _phys.blackholeAutoRestore then
                    for obj, st in pairs(_phys.bh_savedState) do
                        pcall(function()
                            if obj and obj.Parent then
                                obj.AssemblyLinearVelocity  = Vector3.zero
                                obj.AssemblyAngularVelocity = Vector3.zero
                                obj.CFrame     = st.cframe
                                obj.Anchored   = st.anchored
                                obj.CanCollide = st.canCollide
                            end
                        end)
                    end
                    _phys.bh_savedState = {}
                end
                _phys.blackhole_claimed = {}
                ShowNotification("Blackhole", "Singularitas dimatikan" .. (_phys.blackholeAutoRestore and " \226\128\148 part dikembalikan" or ""), 2)
            end
        end,
    })
    bhSec:CreateToggle({
        Title    = "Auto-Restore Parts",
        Subtitle = "Auto-restore parts when blackhole off",
        Default  = false,
        Callback = function(s)
            _phys.blackholeAutoRestore = s
            if not s then _phys.bh_savedState = {} end
            ShowNotification("Blackhole", s and "Auto-Restore ON" or "Auto-Restore OFF", 2)
        end,
    })
    bhSec:CreateToggle({
