_Tabs.Hutan = function()    local tab = CreatedTabs and CreatedTabs["Forest"]
    if not tab or not tab.CreateSection then return end
    local lp = Players and Players.LocalPlayer
    local RS = game:GetService("ReplicatedStorage")
    local function htpNotify(title, msg, dur)
        pcall(function()
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title    = "[Forest] " .. tostring(title),
                Text     = tostring(msg),
                Duration = dur or 3,
            })
        end)
    end
    local function htpTP(cf)
        local char = lp and lp.Character
        if not char then return end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if hrp then hrp.CFrame = cf end
    end
    local function getFishingRod()
        local char = lp and lp.Character
        if char then
            for _, t in ipairs(char:GetChildren()) do
                if t:IsA("Tool") then return t end
            end
        end
        if lp then
            for _, t in ipairs(lp.Backpack:GetChildren()) do
                if t:IsA("Tool") then return t end
            end
        end
        return nil
    end
    local FISH_FALLBACK = {{ Fish_Name = "Salmon", FishImage = "", Sell_Price_KG = 500, Weight = 3 }}
    local function getFishList()
        local ok, result = pcall(function()
            local cfg  = RS.Fishing_System.FishingSystem.Configuration.Fishes
            local list = {}
            for _, folder in ipairs(cfg:GetChildren()) do
                for _, fishObj in ipairs(folder:GetChildren()) do
                    local wAttr = fishObj:GetAttribute("Weight")
                    local wMin  = (wAttr and wAttr.Min) or 1
                    local wMax  = (wAttr and wAttr.Max) or 10
                    list[#list+1] = {
                        Fish_Name     = fishObj.Name,
                        FishImage     = fishObj:GetAttribute("FishImage") or "",
                        Sell_Price_KG = fishObj:GetAttribute("Sell_Price_Per_KG") or 100,
                        Weight        = math.random(wMin, wMax),
                    }
                end
            end
            return list
        end)
        return (ok and result and #result > 0) and result or FISH_FALLBACK
    end
    local function getBackpackFish()
        local list = {}
        if not lp then return list end
        local function scan(container)
            for _, tool in ipairs(container:GetChildren()) do
                if tool:IsA("Tool") and tool:GetAttribute("FishPrice") ~= nil then
                    list[#list+1] = {
                        Fish_Name     = tool.Name,
                        FishImage     = "",
                        Sell_Price_KG = tool:GetAttribute("FishPrice"),
                        Weight        = 1,
                    }
                end
            end
        end
        scan(lp.Backpack)
        if lp.Character then scan(lp.Character) end
        return list
    end
    local function fireFinalTask(fishData, price, weight)
        local rod = getFishingRod()
        if not rod then return false end
        pcall(function()
            local _ftRem = RS.Fishing_System.Remotes.FinalTask
            if _ftRem then _HM_SetFishingRemote(_ftRem) _HM_Install() end
        end)
        local ok = pcall(function()
            RS.Fishing_System.Remotes.FinalTask:FireServer(rod, {
                Fish_Name     = fishData.Fish_Name,
                FishImage     = fishData.FishImage or "",
                Sell_Price_KG = price or fishData.Sell_Price_KG,
                Weight        = weight or fishData.Weight,
            })
        end)
        return ok
    end
    local function getLiveCoins()
        local found = {}
        pcall(function()
            local coinsFolder = workspace:FindFirstChild("Coins")
            if coinsFolder then
                for _, part in ipairs(coinsFolder:GetDescendants()) do
                    if part:IsA("BasePart") and
                       (part.Name == "Coins" or part.Name == "Coins Cave") then
                        found[#found + 1] = part
                    end
                end
            end
            if #found == 0 then
                for _, obj in ipairs(workspace:GetDescendants()) do
                    if obj:IsA("BasePart") and
                       (obj.Name == "Coins" or obj.Name == "Coins Cave") then
                        found[#found + 1] = obj
                    end
                end
            end
        end)
        return found
    end
    local CAVE_COIN_Y    = 19.5
    local TREETOP_COIN_Y = 201.0
    local accentGreen    = Palette.Accent
    local accentDim      = Palette.AccentDark
    local tabBg          = Palette.Background
