    local function MakeQuickRow(parent, layoutOrder, items)
        local row = New("Frame", {
            Size                 = UDim2.new(1, 0, 0, 30),
            BackgroundTransparency = 1,
            LayoutOrder          = layoutOrder,
            Parent               = parent,
        })
        New("UIListLayout", {
            FillDirection     = Enum.FillDirection.Horizontal,
            SortOrder         = Enum.SortOrder.LayoutOrder,
            Padding           = UDim.new(0, 5),
            VerticalAlignment = Enum.VerticalAlignment.Center,
            Parent            = row,
        })
        for idx, item in ipairs(items) do
            local btn = New("TextButton", {
                Size                 = UDim2.new(1 / #items, -(5 * (#items - 1) / #items), 1, 0),
                BackgroundColor3     = pillActiveBg,
                BackgroundTransparency = 0.2,
                AutoButtonColor      = false,
                Text                 = item.label,
                Font                 = Enum.Font.GothamBold,
                TextSize             = 11,
                TextColor3           = accentGreen,
                LayoutOrder          = idx,
                Parent               = row,
            })
            Round(btn, 6)
            Stroke(btn, borderColor, 1, 0)
            SafeConnect(GetSignal(btn, "MouseButton1Click"), function()
                PlayUISound("Click")
                TweenService:Create(btn, TweenInfo.new(0.08), { BackgroundTransparency = 0 }):Play()
                task.delay(0.12, function()
                    TweenService:Create(btn, TweenInfo.new(0.12), { BackgroundTransparency = 0.2 }):Play()
                end)
                item.callback()
            end)
            SafeConnect(GetSignal(btn, "MouseEnter"), function()
                TweenService:Create(btn, TweenInfo.new(0.1), { TextColor3 = textActive }):Play()
            end)
            SafeConnect(GetSignal(btn, "MouseLeave"), function()
                TweenService:Create(btn, TweenInfo.new(0.1), { TextColor3 = accentGreen }):Play()
            end)
        end
        return row
    end
    local mainSec = tab:CreateSection("Forest Explorer", "Coins  •  Fishing  •  Duplicate  •  Price  •  Rating")
