        pages[t.key]       = page
    end
    local function styleSegs()
        for k, entry in pairs(pillButtons) do
            local active = (currentSubTab == k)
            TweenService:Create(entry.Fill,    TweenInfo.new(0.18), { BackgroundTransparency = active and 0.15 or 1 }):Play()
            TweenService:Create(entry.NameLbl, TweenInfo.new(0.18), {
                TextColor3 = active and accentGreen or textInactive,
                TextSize   = active and 9.5         or 9,
            }):Play()
        end
        for k, p in pairs(pages) do p.Visible = (k == currentSubTab) end
    end
    for _, entry in pairs(pillButtons) do
        SafeConnect(GetSignal(entry.Frame, "MouseButton1Click"), function()
            currentSubTab = entry.Def.key
            PlayUISound("Click")
            styleSegs()
        end)
        SafeConnect(GetSignal(entry.Frame, "MouseEnter"), function()
            if currentSubTab ~= entry.Def.key then
                TweenService:Create(entry.NameLbl, TweenInfo.new(0.1), { TextColor3 = Color3.fromRGB(140, 200, 160) }):Play()
            end
        end)
        SafeConnect(GetSignal(entry.Frame, "MouseLeave"), function()
            if currentSubTab ~= entry.Def.key then
                TweenService:Create(entry.NameLbl, TweenInfo.new(0.1), { TextColor3 = textInactive }):Play()
            end
        end)
    end
    local coinPage    = pages["coins"]
    local _coinActive = false
    local _coinStop   = false
    MakeSectionHeader(coinPage, "", "Coin Collector", "Auto-teleport to every coin in the forest map")
    local coinSec = Section.new(coinPage, accentGreen, "Coin Routes", "Detect & collect live coins — skips cooldown slots")
    pcall(function() for _, c in ipairs(coinSec.Frame:GetChildren()) do if c:IsA("UIStroke") then c:Destroy() end end end)
    Stroke(coinSec.Frame, borderColor, 1, 0)
    coinSec:CreateButton({
        Title = "Collect All  (Live Scan)", Subtitle = "Detects real coins in map — skips if on cooldown",
        ButtonText = "▶ Start",
        Callback   = function()
            if _coinActive then return end
            _coinActive, _coinStop = true, false
            task.spawn(function()
                local passCount = 0
                repeat
                    passCount = passCount + 1
                    local liveCoins = getLiveCoins()
                    if #liveCoins == 0 then
                        htpNotify("Coins", "Pass " .. passCount .. " — no coins found, waiting...", 2)
                        task.wait(2)
                    else
                        htpNotify("Coins", "Pass " .. passCount .. " — " .. #liveCoins .. " coins found", 1.5)
                        for i, coinPart in ipairs(liveCoins) do
                            if _coinStop then break end
                            local stillValid = false
                            pcall(function()
                                stillValid = coinPart and
                                            coinPart.Parent ~= nil and
                                            coinPart:IsDescendantOf(workspace)
                            end)
                            if stillValid then
                                local cf = coinPart.CFrame
                                htpNotify("Coins", i .. "/" .. #liveCoins .. " → " .. coinPart.Name, 1)
                                htpTP(cf)
                                task.wait(0.45)
                            end
                        end
                    end
                until _coinStop
                htpNotify("Coins", "Stopped.", 3)
                _coinActive, _coinStop = false, false
            end)
        end,
    })
    coinSec:CreateButton({
        Title = "Stop", Subtitle = "Abort the current run",
        ButtonText = "■ Stop",
        Callback   = function() _coinStop = true end,
    })
    local coinQRow = MakeQuickRow(coinPage, 99, {
        {
            label = "Cave Coin",
            callback = function()
                local coins = getLiveCoins()
                local best, bestDist = nil, math.huge
                for _, part in ipairs(coins) do
                    pcall(function()
                        local dist = math.abs(part.Position.Y - CAVE_COIN_Y)
                        if dist < bestDist then bestDist = dist; best = part end
                    end)
                end
                if best then
                    htpTP(best.CFrame)
                    htpNotify("Coins", "→ Cave Coin (live)", 2)
                else
                    htpNotify("Coins", "Cave Coin not found — may be on cooldown", 2)
                end
            end
        },
        {
            label = "Treetop Coin",
            callback = function()
                local coins = getLiveCoins()
                local best, bestDist = nil, math.huge
                for _, part in ipairs(coins) do
                    pcall(function()
                        local dist = math.abs(part.Position.Y - TREETOP_COIN_Y)
                        if dist < bestDist then bestDist = dist; best = part end
                    end)
                end
                if best then
                    htpTP(best.CFrame)
                    htpNotify("Coins", "→ Treetop Coin (live)", 2)
                else
                    htpNotify("Coins", "Treetop Coin not found — may be on cooldown", 2)
                end
            end
        },
    })
    coinQRow.LayoutOrder = 99
    local forestPage = pages["forest"]
