    })
    MakeQuickRow(forestPage, 11, {
        { label = "SP 3  (3.8, 7.0, -951)",  callback = function() htpTP(CFrame.new(   3.8,  7.0,  -951.0)); htpNotify("Forest", "Secret Place 3", 2) end },
        { label = "SP 4  (-417, 41, -918)",  callback = function() htpTP(CFrame.new(-417.9, 41.1,  -918.7)); htpNotify("Forest", "Secret Place 4", 2) end },
    })
    local mancingPage   = pages["mancing"]
    local _farmActive   = false
    local _farmCount    = 0
    local _farmInterval = 2
    MakeSectionHeader(mancingPage, "", "Auto Fishing", "FireServer FinalTask — bypasses 45 s server delay")
    local mancingSec = Section.new(mancingPage, accentGreen, "Farm Config", "Interval and toggle")
    pcall(function() for _, c in ipairs(mancingSec.Frame:GetChildren()) do if c:IsA("UIStroke") then c:Destroy() end end end)
    Stroke(mancingSec.Frame, borderColor, 1, 0)
    mancingSec:CreateSlider({
        Title = "Farm Interval  (seconds)", Subtitle = "Delay between FinalTask fires",
        Min = 0.5, Max = 30, Step = 0.5, Default = 2,
        Callback = function(v) _farmInterval = v end,
    })
    mancingSec:CreateToggle({
        Title = "Auto Farm Fishing", Subtitle = "Toggle ON to start — OFF to stop and report count",
        Default  = false,
        Callback = function(state)
            _farmActive = state
            if not state then
                htpNotify("Farm", "OFF — total " .. _farmCount .. " fish", 3); return
            end
            _farmCount = 0
            htpNotify("Farm", "Auto Farm ON", 2)
            task.spawn(function()
                local fishList = getFishList()
                while _farmActive do
                    if math.random(1, 10) == 1 then fishList = getFishList() end
                    local pick = fishList[math.random(1, #fishList)]
                    local wLo  = math.max(1, math.floor((pick.Weight or 5) * 0.5))
                    local wHi  = math.max(2, math.ceil( (pick.Weight or 5) * 1.5))
                    local w    = math.random(wLo, wHi)
                    local ok   = fireFinalTask(pick, pick.Sell_Price_KG, w)
                    if ok then _farmCount += 1 end
                    task.wait(_farmInterval)
                end
            end)
        end,
    })
    local dupPage   = pages["duplikat"]
    local _dupCount = 5
    MakeSectionHeader(dupPage, "", "Fish Duplicator", "Clone every fish in backpack × slider count")
    local dupSec = Section.new(dupPage, accentGreen, "Clone Config", "Slider + execute")
    pcall(function() for _, c in ipairs(dupSec.Frame:GetChildren()) do if c:IsA("UIStroke") then c:Destroy() end end end)
    Stroke(dupSec.Frame, borderColor, 1, 0)
    dupSec:CreateSlider({
        Title = "Duplicate Count", Subtitle = "How many times each fish is cloned (1–200)",
        Min = 1, Max = 200, Step = 1, Default = 5,
        Callback = function(v) _dupCount = v end,
    })
    dupSec:CreateButton({
        Title = "Duplicate All Fish", Subtitle = "Clone each fish in backpack × slider value",
        ButtonText = "Dup",
        Callback   = function()
            task.spawn(function()
                local fishList = getBackpackFish()
                if #fishList == 0 then
                    htpNotify("Duplicate", "Backpack empty — go fishing first!", 3); return
                end
                local total = 0
                for _, f in ipairs(fishList) do
                    for _ = 1, _dupCount do
                        fireFinalTask(f, f.Sell_Price_KG, 1)
                        total += 1
                        task.wait(0.05)
                    end
                end
                htpNotify("Duplicate", "+" .. total .. " fish added", 3)
            end)
        end,
    })
    local hargaPage    = pages["harga"]
    local _customPrice = 1000000
    MakeSectionHeader(hargaPage, "", "Custom Fish Price", "Override Sell_Price_KG before FireServer")
    local hargaSec = Section.new(hargaPage, accentGreen, "Price Override", "Slider or quick-select")
    pcall(function() for _, c in ipairs(hargaSec.Frame:GetChildren()) do if c:IsA("UIStroke") then c:Destroy() end end end)
    Stroke(hargaSec.Frame, borderColor, 1, 0)
    hargaSec:CreateSlider({
        Title = "Price  (×1,000 coins)", Subtitle = "Value × 1000 — default 1000 → 1,000,000 coins",
        Min = 1, Max = 999999, Step = 1, Default = 1000,
        Callback = function(v) _customPrice = v * 1000 end,
    })
    local function applyCustomPrice(price)
        task.spawn(function()
            local fishList = getBackpackFish()
            local label    = (price == math.huge) and "∞" or tostring(price)
            if #fishList == 0 then
                local allFish = getFishList()
                fireFinalTask(allFish[math.random(1, #allFish)], price, 1)
                htpNotify("Price", "1 fish — price " .. label, 3); return
            end
            for _, f in ipairs(fishList) do
                fireFinalTask(f, price, 1)
                task.wait(0.05)
            end
            htpNotify("Price", #fishList .. " fish — price " .. label, 3)
        end)
    end
    hargaSec:CreateButton({
        Title = "Apply Slider Price", Subtitle = "Send fish at the value set by slider above",
        ButtonText = "Apply",
        Callback = function() applyCustomPrice(_customPrice) end,
    })
    MakeQuickRow(hargaPage, 50, {
        { label = "1K  (1,000)",        callback = function() applyCustomPrice(1000)       end },
        { label = "1M  (1,000,000)",    callback = function() applyCustomPrice(1000000)    end },
    })
    MakeQuickRow(hargaPage, 51, {
        { label = "1B  (1,000,000,000)", callback = function() applyCustomPrice(1000000000) end },
        { label = "∞   math.huge",       callback = function() applyCustomPrice(math.huge)  end },
    })
    local ratingPage    = pages["rating"]
    local _repRemotes   = RS:FindFirstChild("ReputationRemotes")
    local _submitVote   = _repRemotes and _repRemotes:FindFirstChild("SubmitVote")
    local _reqProfile   = _repRemotes and _repRemotes:FindFirstChild("RequestProfile")
    if typeof(getgenv()._HM_SetSubmitVote) == "function" then
        pcall(getgenv()._HM_SetSubmitVote, _submitVote)
    end
    if typeof(getgenv()._HM_SetReqProfile) == "function" then
        pcall(getgenv()._HM_SetReqProfile, _reqProfile)
    end
    local _ratingActive = false
    local _ratingDelay  = 0.6
    local function checkCanRate(uid)
        if not _reqProfile then return false end
        local ok, profile = pcall(function() return _reqProfile:InvokeServer(uid) end)
        return ok and profile and profile.CanRate == true
    end
    local function fireVote(uid)
        if not _submitVote then return false, "SubmitVote not found" end
        local ok, result = pcall(function() return _submitVote:InvokeServer(uid, "Like") end)
        if not ok then return false, tostring(result) end
        if result and result.ok == false then return false, "server rejected" end
        return true, (result and result.cost) or 250
    end
    MakeSectionHeader(ratingPage, "", "Rating Player", "SubmitVote Like — 250 coins deducted per vote")
    local rateSec = Section.new(ratingPage, accentGreen, "Vote Config", "Delay and loop toggle")
    pcall(function() for _, c in ipairs(rateSec.Frame:GetChildren()) do if c:IsA("UIStroke") then c:Destroy() end end end)
    Stroke(rateSec.Frame, borderColor, 1, 0)
    rateSec:CreateSlider({
        Title = "Delay Per Vote  (seconds)", Subtitle = "Delay between votes — min 0.5 s",
        Min = 0.5, Max = 15, Step = 0.1, Default = 0.6,
        Callback = function(v) _ratingDelay = v end,
    })
    rateSec:CreateToggle({
        Title = "Rate All  (Like)", Subtitle = "Loop SubmitVote Like to every player in server",
        Default  = false,
        Callback = function(state)
            _ratingActive = state
            if not state then htpNotify("Rating", "Rating stopped", 2); return end
            if not _submitVote then htpNotify("Rating", "ReputationRemotes not found!", 3); return end
            task.spawn(function()
                local targets = {}
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= lp then targets[#targets+1] = p end
                end
                if #targets == 0 then
                    htpNotify("Rating", "No other players in server", 2)
                    _ratingActive = false; return
                end
                local okCount, skipCount, coinSpent = 0, 0, 0
                htpNotify("Rating", "Rating " .. #targets .. " players...", 2)
                for _, target in ipairs(targets) do
                    if not _ratingActive then break end
                    if not checkCanRate(target.UserId) then
                        skipCount += 1; task.wait(0.3)
                    else
                        local ok, res = fireVote(target.UserId)
                        if ok then
                            okCount   += 1
                            coinSpent += (type(res) == "number" and res or 250)
                            htpNotify("Rating", "✓ " .. target.Name, 1)
                        end
                        task.wait(_ratingDelay)
                    end
                end
                _ratingActive = false
                htpNotify("Rating", "Done — OK:" .. okCount .. "  Skip:" .. skipCount .. "  -" .. coinSpent .. " coins", 5)
            end)
        end,
    })
    rateSec:CreateButton({
        Title = "Rate Player  (One-shot)", Subtitle = "Single pass — rate all eligible players now",
        ButtonText = "Rate",
        Callback   = function()
            if not _submitVote then htpNotify("Rating", "Remote not found!", 3); return end
            task.spawn(function()
                local rated = 0
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= lp and checkCanRate(p.UserId) then
                        local ok = fireVote(p.UserId)
                        if ok then rated += 1; htpNotify("Rating", "✓ " .. p.Name, 1.5) end
                        task.wait(_ratingDelay)
                    end
                end
                htpNotify("Rating", "Done — " .. rated .. " players rated", 3)
            end)
        end,
    })
    styleSegs()
end
