    local function applyFilters()
        for _, c in ipairs(listScroll:GetChildren()) do
            if c:IsA("Frame") and c ~= loadMoreBtn then
                pcall(function() c:Destroy() end)
            end
        end
        sfServers = {}
        rowN      = 0
        pcall(function() emptyLabel.Parent = listScroll end)
        for _, s in ipairs(sfRawPool) do
            if passFilter(s) then
                table.insert(sfServers, s)
                addServerRow(s, #sfServers)
            end
        end
        local n = #sfServers
        listCountLabel.Text = n .. " SERVER" .. (n == 1 and "" or "S") .. " SHOWN"
        if n == 0 then
            pcall(function() emptyLabel.Text = "No servers match the current filters." end)
        end
        loadMoreBtn.Visible = not sfAllLoaded and #sfRawPool > 0
        updateSummary()
    end
    applyBtn.MouseButton1Click:Connect(function()
        PlayUISound("Click")
        if #sfRawPool == 0 then
            statusLabel.Text       = "  [INFO] No data " .. _CHR.EM_DASH .. " press Scan first."
            statusLabel.TextColor3 = Color3.fromRGB(170, 170, 170)
            return
        end
        applyFilters()
        statusLabel.Text       = "  [FILTER] Applied " .. _CHR.EM_DASH .. " " .. #sfServers .. " match."
        statusLabel.TextColor3 = Color3.fromRGB(210, 210, 210)
    end)
    local function fetchPage(myToken, isLoadMore)
        if sfScanToken ~= myToken then return end
        sfPage = sfPage + 1
        pcall(function()
            statusLabel.Text       = "  [SCAN] Page " .. sfPage .. " " .. _CHR.EM_DASH .. " " .. #sfRawPool .. " fetched so far..."
            statusLabel.TextColor3 = Color3.fromRGB(190, 190, 190)
        end)
        local url = "https://games.roblox.com/v1/games/" .. game.PlaceId
            .. "/servers/Public?sortOrder=" .. sfSort .. "&limit=100"
        if sfCursor then url = url .. "&cursor=" .. sfCursor end
        local body, pingMs = sfFetch(url)
        _ = pingMs
        local function finishScan(errMsg)
            sfScanning = false
            pcall(function()
                scanBtn.Text       = "SCAN SERVERS"
                scanBtn.TextColor3 = Color3.fromRGB(10, 10, 10)
                loadMoreBtn.Text       = "LOAD MORE"
                loadMoreBtn.TextColor3 = accent
            end)
            if errMsg then
                statusLabel.Text       = errMsg
                statusLabel.TextColor3 = Color3.fromRGB(150, 150, 150)
            end
        end
        if not body then finishScan("  [ERR] Fetch failed " .. _CHR.EM_DASH .. " check HTTP permissions.")
        return end
        local ok, decoded = pcall(function() return HttpService:JSONDecode(body) end)
        if not ok or not decoded or not decoded.data then finishScan("  [ERR] Parse error " .. _CHR.EM_DASH .. " no server data.")
        return end
        for _, s in ipairs(decoded.data) do
            table.insert(sfRawPool, s)
            if passFilter(s) then
                table.insert(sfServers, s)
                addServerRow(s, #sfServers)
            end
        end
        sfCursor    = decoded.nextPageCursor
        sfAllLoaded = not sfCursor
        local n = #sfServers
        listCountLabel.Text    = n .. " SERVER" .. (n == 1 and "" or "S") .. " SHOWN"
        statusLabel.Text       = "  [DONE] " .. n .. " match from " .. #sfRawPool .. " fetched."
        statusLabel.TextColor3 = Color3.fromRGB(210, 210, 210)
        if sfAllLoaded then
            statusLabel.Text    = "  [DONE] All pages loaded " .. _CHR.EM_DASH .. " " .. n .. " servers match."
            loadMoreBtn.Visible = false
        else
            loadMoreBtn.Visible = true
        end
        updateSummary()
        finishScan()
    end
    scanBtn.MouseButton1Click:Connect(function()
        PlayUISound("Click")
        if sfScanning then return end
        sfScanning  = true
        sfScanToken = sfScanToken + 1
        local myToken = sfScanToken
        scanBtn.Text       = "SCANNING..."
        scanBtn.TextColor3 = Color3.fromRGB(120, 120, 120)
        clearList()
        task.spawn(function()
            fetchPage(myToken, false)
        end)
    end)
    loadMoreBtn.MouseButton1Click:Connect(function()
        PlayUISound("Click")
        if sfScanning or sfAllLoaded then return end
        sfScanning = true
        loadMoreBtn.Text       = "LOADING..."
        loadMoreBtn.TextColor3 = Color3.fromRGB(100, 100, 100)
        local myToken = sfScanToken
        task.spawn(function()
            fetchPage(myToken, true)
            pcall(function()
                loadMoreBtn.Text       = "LOAD MORE"
                loadMoreBtn.TextColor3 = accent
            end)
        end)
    end)
end
