    end
    FetchScripts = function(reset)
        if sbLoading then return end
        sbLoading = true
        if reset then
            sbPage = 1
            ClearGrid()
            pcall(function() sbLoadMoreBtn.Visible = false end)
        end
        SetStatus("Loading...", Color3.fromRGB(180, 180, 180))
        local q = (sbSearchBox and sbSearchBox.Text:match("^%s*(.-)%s*$")) or ""
        local url
        if sbMode == "search" and q ~= "" then
            local encoded = ""
            pcall(function() encoded = HttpService:UrlEncode(q) end)
            if encoded == "" then
                encoded = q:gsub("[^%w%-_%.~]", function(c)
                    return string.format("%%%02X", string.byte(c))
                end)
            end
            url = "https://scriptblox.com/api/script/search?q=" .. encoded .. "&page=" .. sbPage
        elseif sbMode == "trending" then
            url = "https://scriptblox.com/api/script/trending"
        elseif sbMode == "free" then
            url = "https://scriptblox.com/api/script/fetch?mode=free&page=" .. sbPage
        elseif sbMode == "universal" then
            url = "https://scriptblox.com/api/script/fetch?mode=universal&page=" .. sbPage
        else
            url = "https://scriptblox.com/api/script/fetch?page=" .. sbPage
        end
        task.spawn(function()
            local body, err = SafeHttpGet(url)
            if not body or body == "" then
                SetStatus("Gagal load " .. _CHR.EM_DASH .. " " .. (err or "network error"), Color3.fromRGB(180, 80, 80))
                sbLoading = false
                return
            end
            local ok, data = pcall(function() return HttpService:JSONDecode(body) end)
            if not ok or not data or not data.result then
                SetStatus("Parse error " .. _CHR.EM_DASH .. " response tidak valid", Color3.fromRGB(180, 80, 80))
                sbLoading = false
                return
            end
            local scripts    = data.result.scripts or {}
            local totalPages = data.result.totalPages or 1
            local count      = #scripts
            if count == 0 then
                SetStatus("No results" .. (q ~= "" and (" for: " .. q) or ""), Color3.fromRGB(90, 90, 90))
                sbLoading = false
                pcall(function() sbLoadMoreBtn.Visible = false end)
                return
            end
            local existingCount = 0
            if sbGrid then
                for _, child in ipairs(sbGrid:GetChildren()) do
                    if child:IsA("Frame") then existingCount = existingCount + 1 end
                end
            end
            local rendered = 0
            for i, scriptData in ipairs(scripts) do
                task.wait()
                local card = MakeScriptCard(scriptData, existingCount + i)
                if card then rendered = rendered + 1 end
            end
            local hasMore = (sbPage < totalPages) and (sbMode ~= "trending")
            pcall(function() sbLoadMoreBtn.Visible = hasMore end)
            local total = existingCount + rendered
            SetStatus(
                "Menampilkan " .. total .. " script" .. (hasMore and "  " .. _CHR.EM_DASH .. "  Ada lebih banyak" or ""),
                Color3.fromRGB(85, 85, 85)
            )
            sbLoading = false
        end)
    end
