                pcall(function()
                    local n = totalFires
                    local fmt
                    if     n >= 1000000 then fmt = string.format("%.2fM", n / 1000000)
                    elseif n >= 1000    then fmt = string.format("%.1fK", n / 1000)
                    else                     fmt = tostring(n) end
                    statsFiresLabel.Text = "Total Fires: " .. fmt
                end)
            end
        end)
        SafeConnect(GetSignal(playBtn, "MouseButton1Click"), function()
            PlayUISound("ToggleOn")
            CreateRipple(playBtn)
            task.spawn(function()
                if #discoveredRemotes == 0 then
                    if _scanStatusLabel  then _scanStatusLabel.Text              = "Auto-scanning first" .. _CHR.ELLIPSIS end
                    if _scanStatusDot    then _scanStatusDot.BackgroundColor3    = Color3.fromRGB(172, 172, 172) end
                    local count = scanRemotes()
                    local col   = count > 0 and Color3.fromRGB(152, 152, 152) or Color3.fromRGB(57, 57, 57)
                    if _scanStatusLabel  then _scanStatusLabel.Text              = "Auto-scan: " .. tostring(count) .. " found" end
                    if _scanCountLabel   then _scanCountLabel.Text               = tostring(count) .. " remote" .. (count ~= 1 and "s" or "") end
                    if _scanCountLabel   then _scanCountLabel.TextColor3         = col end
                    if _scanStatusDot    then _scanStatusDot.BackgroundColor3    = col end
                end
                local targets = getTargetRemotes()
                if #targets == 0 then
                    liveStatusLabel.Text       = _CHR.BULLET .. " NO TARGETS"
                    liveStatusLabel.TextColor3 = Color3.fromRGB(143, 143, 143)
                    return
                end
                liveRemotesLabel.Text      = "Targets: " .. tostring(#targets)
                                             .. " " .. _CHR.MULTIPLY .. " " .. tostring(threadCount) .. "T"
                liveStatusLabel.Text       = _CHR.BULLET .. " FIRING"
                liveStatusLabel.TextColor3 = Color3.fromRGB(186, 186, 186)
                Tween(playBtn, 0.12, nil, nil, { BackgroundColor3 = Color3.fromRGB(50, 50, 50) })
                AddGlowPulse(playBtn, Color3.fromRGB(188, 188, 188), 0.2, 0.65, 0.75)
                startSpam(targets)
            end)
        end)
        SafeConnect(GetSignal(stopBtn, "MouseButton1Click"), function()
            PlayUISound("ToggleOff")
            CreateRipple(stopBtn)
            stopSpam()
            liveStatusLabel.Text       = _CHR.BULLET .. " IDLE"
            liveStatusLabel.TextColor3 = Palette.SubText
            liveRemotesLabel.Text      = "Targets: " .. _CHR.EM_DASH
            if statsRateLabel  then statsRateLabel.Text  = "Fires / sec: " .. _CHR.EM_DASH end
            if statsFiresLabel then
                local n = totalFires
                local fmt
                if     n >= 1000000 then fmt = string.format("%.2fM", n / 1000000)
                elseif n >= 1000    then fmt = string.format("%.1fK", n / 1000)
                else                     fmt = tostring(n) end
                statsFiresLabel.Text = "Total Fires: " .. fmt
            end
            Tween(playBtn, 0.18, Enum.EasingStyle.Quad, nil, { BackgroundColor3 = Color3.fromRGB(55, 55, 55) })
        end)
    end
