    local function _buildRemotePrioritizerSection()
        local PRIO_KEYWORDS = {
            { kw = "kill",     score = 100 }, { kw = "damage",   score = 95  },
            { kw = "dead",     score = 90  }, { kw = "admin",    score = 88  },
            { kw = "teleport", score = 85  }, { kw = "kick",     score = 85  },
            { kw = "ban",      score = 85  }, { kw = "give",     score = 80  },
            { kw = "cash",     score = 78  }, { kw = "money",    score = 78  },
            { kw = "coin",     score = 75  }, { kw = "gem",      score = 75  },
            { kw = "item",     score = 70  }, { kw = "weapon",   score = 70  },
            { kw = "data",     score = 65  }, { kw = "save",     score = 60  },
            { kw = "load",     score = 55  }, { kw = "update",   score = 50  },
            { kw = "event",    score = 30  }, { kw = "remote",   score = 20  },
        }
        local prioResults    = {}
        local prioOnlyActive = false
        local prioTopN       = 5
        local function scoreRemote(name)
            local low, best = name:lower(), 0
            for _, entry in ipairs(PRIO_KEYWORDS) do
                if string.find(low, entry.kw, 1, true) and entry.score > best then
                    best = entry.score
                end
            end
            return best
        end
        local prioSec  = _cs("Remote Prioritizer", "Rank & pick remotes by keyword " .. _CHR.EM_DASH .. " fire highest impact")
        local prioBody = prioSec.Body
        local prioCard = New("Frame", {
            Size = UDim2.new(1, 0, 0, 136), BackgroundColor3 = Color3.fromRGB(1, 1, 1),
            BackgroundTransparency = 0.04, ClipsDescendants = true, Parent = prioBody,
        })
        Round(prioCard, 10)
        Stroke(prioCard, fsAccent, 1.2, 0.22)
        local prioTop = New("Frame", { Size = UDim2.new(1, 0, 0, 20), BackgroundColor3 = Color3.fromRGB(5, 5, 5), Parent = prioCard })
        Round(prioTop, 10)
        New("TextLabel", {
            BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, 0), Font = Enum.Font.GothamBold,
            Text = "REMOTE PRIORITY LIST", TextColor3 = fsAccent, TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Center, Parent = prioTop,
        })
        local prioScroll = New("ScrollingFrame", {
            Size = UDim2.new(1, 0, 0, 116), Position = UDim2.new(0, 0, 0, 20),
            BackgroundTransparency = 1, ScrollBarThickness = 3, ScrollBarImageColor3 = fsAccent,
            CanvasSize = UDim2.new(0, 0, 0, 0),
            AutomaticCanvasSize    = _AutomaticSizeY or Enum.AutomaticSize.Y,
            VerticalScrollBarInset = _ScrollBarInsetAlways or Enum.ScrollBarInset.Always,
            ClipsDescendants = true, Parent = prioCard,
        })
        Pad(prioScroll, 8, 8, 4, 4)
        New("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2), Parent = prioScroll })
        local prioLineN = 0
        local function AddPrioLine(text, color, order)
            prioLineN = prioLineN + 1
            local f = New("Frame", {
                Size = UDim2.new(1, 0, 0, 16), BackgroundTransparency = 1,
                LayoutOrder = order or prioLineN, Parent = prioScroll,
            })
            New("TextLabel", {
                Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1,
                Font = Enum.Font.Code, Text = tostring(text),
                TextColor3 = color or Color3.fromRGB(170, 170, 170), TextSize = 10,
                TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left,
                RichText = false, Parent = f,
            })
        end
        AddPrioLine("\226\148\128\226\148\128 Click SCAN & RANK to begin \226\148\128\226\148\128", Color3.fromRGB(130, 130, 130))
        prioSec:CreateSlider({
            Title = "Top-N Target", Subtitle = "Priority remote count",
            Min = 1, Max = 20, Step = 1, Default = 5,
            Callback = function(v) prioTopN = v end,
        })
        prioSec:CreateToggle({
            Title = "Prioritized Only", Subtitle = "Fire priority remotes only",
            Default = false, Callback = function(v) prioOnlyActive = v end,
        })
        local originalGetTargets = getTargetRemotes
        local function patchedGetTargets()
            if prioOnlyActive and #prioResults > 0 then
                local out = {}
                for i = 1, math.min(prioTopN, #prioResults) do
                    table.insert(out, prioResults[i])
                end
                return out
            end
            return originalGetTargets()
        end
        getTargetRemotes = patchedGetTargets
        local scanRankBtn = New("TextButton", {
            Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = Color3.new(1, 1, 1),
            BackgroundTransparency = 0, Font = Enum.Font.GothamBold,
            Text = "SCAN & RANK REMOTES", TextColor3 = Color3.fromRGB(10, 10, 10),
            TextSize = 12, AutoButtonColor = false, RichText = false, Parent = prioBody,
        })
        Round(scanRankBtn, 10)
        local scanRankStroke = Stroke(scanRankBtn, Color3.fromRGB(80, 80, 80), 1.5, 0.3)
        AddButtonHover(scanRankBtn, scanRankStroke, 0.08)
        New("UIGradient", {
            Color = ColorSequence.new(Color3.fromRGB(235, 235, 235), Color3.fromRGB(185, 185, 185)),
            Rotation = 135, Parent = scanRankBtn,
        })
        SafeConnect(GetSignal(scanRankBtn, "MouseButton1Click"), function()
            PlayUISound("Click")
            CreateRipple(scanRankBtn)
            for _, c in ipairs(prioScroll:GetChildren()) do
                if c:IsA("Frame") then pcall(function() c:Destroy() end) end
            end
            prioLineN, prioResults = 0, {}
            task.spawn(function()
                local count = scanRemotes()
                AddPrioLine("\226\148\128\226\148\128 Scanned " .. count .. " remote(s) \226\148\128\226\148\128", Color3.fromRGB(92, 92, 92))
                local scored = {}
                for _, r in ipairs(discoveredRemotes) do
                    table.insert(scored, { r = r, score = scoreRemote(r.name) })
                end
                table.sort(scored, function(a, b) return a.score > b.score end)
                prioResults = {}
                local shown = 0
                for _, entry in ipairs(scored) do
                    if entry.score > 0 then
                        table.insert(prioResults, entry.r)
                        local tag = entry.r.kind == "Function" and "[FN]" or "[EV]"
                        AddPrioLine(
                            string.format("[%3d] %s %s", entry.score, tag, entry.r.name),
                            Color3.fromRGB(173, 173, 173)
                        )
                        shown = shown + 1
                    end
                end
                if shown == 0 then
                    AddPrioLine("No remote found with a known keyword.", Color3.fromRGB(74, 74, 74))
                end
                AddPrioLine("\226\148\128\226\148\128 Top " .. shown .. " remote(s) successfully ranked \226\148\128\226\148\128", Color3.fromRGB(147, 147, 147))
            end)
        end)
    end
    local function _buildMutationEngineSection()
        local mutSec = _cs("Payload Mutation Engine", "Auto-swap payload every N fires " .. _CHR.EM_DASH .. " bypass server rate-limiter")
        mutSec:CreateToggle({
            Title = "Auto Mutation", Subtitle = "Auto-rotate payload",
            Default = false,
            Callback = function(v)
                if v then
                    savedPayloadMode = payloadMode
                else
                    if savedPayloadMode then
                        payloadMode      = savedPayloadMode
                        savedPayloadMode = nil
                    end
                end
                mutationActive = v
            end,
        })
        mutSec:CreateSlider({
            Title = "Mutation Interval", Subtitle = "Interval rotasi (fires)",
            Min = 5, Max = 500, Step = 5, Default = 50,
            Callback = function(v) mutationInterval = v end,
        })
        task.spawn(function()
            while true do
                task.wait(0.1)
                if not IsCurrentRun() then break end
                if mutationActive and spamActive then
                    local snapshot = totalFires
                    if snapshot - mutationCycle >= mutationInterval then
                        mutationCycle = snapshot
                        mutationIdx   = (mutationIdx % #MUTATION_POOL) + 1
                        payloadMode   = MUTATION_POOL[mutationIdx]
                    end
                end
            end
        end)
        local mutStatusLabel = New("TextLabel", {
            Size = UDim2.new(1, 0, 0, 18), BackgroundColor3 = Color3.fromRGB(2, 2, 2),
            BackgroundTransparency = 0.05, Font = Enum.Font.Code,
            Text = "  Mutation: idle", TextColor3 = Color3.fromRGB(121, 121, 121),
            TextSize = 10, TextXAlignment = Enum.TextXAlignment.Left,
            Parent = mutSec.Body,
        })
        Round(mutStatusLabel, 6)
        Stroke(mutStatusLabel, fsAccent, 1, 0.5)
        Pad(mutStatusLabel, 12, 12, 0, 0)
        task.spawn(function()
            while true do
                task.wait(0.25)
                if not IsCurrentRun() then break end
                pcall(function()
                    if mutationActive and spamActive then
                        mutStatusLabel.Text       = "  Mutation: ACTIVE  " .. _CHR.ARROW_RIGHT
                                                    .. "  mode=" .. tostring(payloadMode)
                                                    .. "  cycle=" .. tostring(mutationIdx) .. "/" .. #MUTATION_POOL
                        mutStatusLabel.TextColor3 = Color3.fromRGB(182, 182, 182)
                    else
                        mutStatusLabel.Text       = "  Mutation: idle  (payload=" .. tostring(payloadMode) .. ")"
                        mutStatusLabel.TextColor3 = Color3.fromRGB(130, 130, 130)
                    end
                end)
            end
        end)
    end
    local function _buildSingleTargetFireSection()
        local stfSec  = _cs("Single-Target Fire", "Pick remote from list above " .. _CHR.EM_DASH .. " then START STF")
        local stfBody = stfSec.Body
        local stfHintLabel = New("TextLabel", {
