            TextColor3 = Color3.fromRGB(135, 135, 135), TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Left, Parent = stfBody,
        })
        Round(stfStatusLabel, 6)
        Stroke(stfStatusLabel, fsAccent, 1, 0.5)
        Pad(stfStatusLabel, 12, 12, 0, 0)
        local stfBtnRow = New("Frame", { Size = UDim2.new(1, 0, 0, 32), BackgroundTransparency = 1, Parent = stfBody })
        New("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 8),
            VerticalAlignment = Enum.VerticalAlignment.Center, Parent = stfBtnRow,
        })
        local function MakeStfBtn(label, image, order)
            local b = New("TextButton", {
                Size = UDim2.new(0.5, -4, 0, 32), BackgroundColor3 = Color3.fromRGB(55, 55, 55),
                BackgroundTransparency = 0, Font = Enum.Font.GothamBold,
                Text = label, TextColor3 = Color3.fromRGB(255, 255, 255), TextSize = 11,
                AutoButtonColor = false, RichText = false, LayoutOrder = order, Parent = stfBtnRow,
            })
            Round(b, 10)
            New("UIGradient", {
                Color = ColorSequence.new(Color3.fromRGB(82, 82, 82), Color3.fromRGB(44, 44, 44)),
                Rotation = 135, Parent = b,
            })
            local s = Stroke(b, Color3.fromRGB(80, 80, 80), 1.5, 0.3)
            AddButtonHover(b, s, 0.08)
            New("ImageLabel", {
                Size = UDim2.new(0, 14, 0, 14), Position = UDim2.new(0, 11, 0.5, -7),
                BackgroundTransparency = 1, Image = image,
                ImageColor3 = Color3.fromRGB(255, 255, 255), ZIndex = b.ZIndex + 1, Parent = b,
            })
            Pad(b, 31, 10, 0, 0)
            return b, s
        end
        local stfPlayBtn, _ = MakeStfBtn("START STF", "rbxassetid://7743871480", 1)
        local stfStopBtn, _ = MakeStfBtn("STOP STF",  "rbxassetid://7733655755", 2)
        SafeConnect(GetSignal(stfPlayBtn, "MouseButton1Click"), function()
            PlayUISound("Click")
            if stfActive then return end
            if not stfRemote then
                if stfStatusLabel then
                    stfStatusLabel.Text       = "  [ERR] Select a remote from the scan list first"
                    stfStatusLabel.TextColor3 = Color3.fromRGB(69, 69, 69)
                end
                return
            end
            local remOk = pcall(function() return stfRemote.Name end)
            if not remOk then
                stfRemote = nil
                if stfStatusLabel then
                    stfStatusLabel.Text       = "  [ERR] Remote invalid \226\128\148 scan & re-select"
                    stfStatusLabel.TextColor3 = Color3.fromRGB(69, 69, 69)
                end
                return
            end
            local rem   = stfRemote
            stfActive   = true
            stfToken    = stfToken + 1
            local myTok = stfToken
            stfStatusLabel.Text       = "  [ON]  Firing: " .. rem:GetFullName()
            stfStatusLabel.TextColor3 = Color3.fromRGB(176, 176, 176)
            task.spawn(function()
                pcall(function()
                    if typeof(task.desynchronize) == "function" then task.desynchronize() end
                end)
                while stfActive and stfToken == myTok and IsCurrentRun() do
                    if not rem.Parent then
                        stfActive = false
                        pcall(function()
                            stfStatusLabel.Text       = "  [ERR] Remote destroyed " .. _CHR.EM_DASH .. " stopped."
                            stfStatusLabel.TextColor3 = Color3.fromRGB(130, 130, 130)
                        end)
                        break
                    end
                    local firesPerFrame = math.max(1, math.ceil(stfRate / 60))
                    for _ = 1, firesPerFrame do
                        if not stfActive or stfToken ~= myTok then break end
                        local payload = buildFinalPayload()
                        local ok = pcall(function()
                            if rem:IsA("RemoteFunction") then rem:InvokeServer(payload)
                            else                              rem:FireServer(payload) end
                        end)
                        if ok then
                            totalFires        = totalFires        + 1
                            sharedRateCounter = sharedRateCounter + 1
                        else
                            for _ri = 1, math.max(1, _HM_EX_STF) do
                                pcall(function()
                                    if rem:IsA("RemoteFunction") then rem:InvokeServer(payload)
                                    else                              rem:FireServer(payload) end
                                    totalFires        = totalFires        + 1
                                    sharedRateCounter = sharedRateCounter + 1
                                end)
                            end
                        end
                    end
                    RunService.Heartbeat:Wait()
                end
            end)
        end)
        SafeConnect(GetSignal(stfStopBtn, "MouseButton1Click"), function()
            PlayUISound("Click")
            stfActive                 = false
            stfStatusLabel.Text       = "  [OFF] Stopped."
            stfStatusLabel.TextColor3 = Color3.fromRGB(135, 135, 135)
        end)
    end
    local function _buildLiveFireLogSection()
        local logSec  = _cs("Live Fire Log", "Real-time log of every fired remote " .. _CHR.EM_DASH .. " confirm & debug")
        local logBody = logSec.Body
