        local fireLogLines   = 0
        local fireLogScroll  = nil
        local fireLogMax     = 80
        local fireLogCard = New("Frame", {
            Size = UDim2.new(1, 0, 0, 136), BackgroundColor3 = Color3.fromRGB(1, 1, 1),
            BackgroundTransparency = 0.04, ClipsDescendants = true, Parent = logBody,
        })
        Round(fireLogCard, 10)
        Stroke(fireLogCard, fsAccent, 1.2, 0.2)
        local fireLogTopBar = New("Frame", { Size = UDim2.new(1, 0, 0, 20), BackgroundColor3 = Color3.fromRGB(4, 4, 4), Parent = fireLogCard })
        Round(fireLogTopBar, 10)
        New("TextLabel", {
            BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, 0), Font = Enum.Font.GothamBold,
            Text = "LIVE FIRE LOG", TextColor3 = fsAccent, TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Center, Parent = fireLogTopBar,
        })
        fireLogScroll = New("ScrollingFrame", {
            Size = UDim2.new(1, 0, 0, 116), Position = UDim2.new(0, 0, 0, 20),
            BackgroundTransparency = 1, ScrollBarThickness = 3, ScrollBarImageColor3 = fsAccent,
            CanvasSize = UDim2.new(0, 0, 0, 0),
            AutomaticCanvasSize    = _AutomaticSizeY or Enum.AutomaticSize.Y,
            VerticalScrollBarInset = _ScrollBarInsetAlways or Enum.ScrollBarInset.Always,
            ClipsDescendants = true, Parent = fireLogCard,
        })
        Pad(fireLogScroll, 8, 8, 4, 4)
        New("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 1), Parent = fireLogScroll })
        local function AddFireLogLine(text, color)
            if not fireLogEnabled then return end
            fireLogLines = fireLogLines + 1
            if fireLogLines > fireLogMax then
                for _, c in ipairs(fireLogScroll:GetChildren()) do
                    if c:IsA("Frame") then pcall(function() c:Destroy() end) end
                end
                fireLogLines = 1
            end
            local f = New("Frame", {
                Size = UDim2.new(1, 0, 0, 14), BackgroundTransparency = 1,
                LayoutOrder = fireLogLines, Parent = fireLogScroll,
            })
            New("TextLabel", {
                Size = UDim2.new(1, 0, 1, 0), BackgroundTransparency = 1,
                Font = Enum.Font.Code, Text = tostring(text),
                TextColor3 = color or Color3.fromRGB(170, 170, 170), TextSize = 9,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left, RichText = false, Parent = f,
            })
            task.defer(function()
                pcall(function()
                    fireLogScroll.CanvasPosition = Vector2.new(
                        0, math.max(0, fireLogScroll.AbsoluteCanvasSize.Y - fireLogScroll.AbsoluteSize.Y)
                    )
                end)
            end)
        end
        logSec:CreateToggle({
            Title = "Enable Fire Log", Subtitle = "Log every fire",
            Default = false,
            Callback = function(v)
                fireLogEnabled = v
                if v then AddFireLogLine("\226\148\128\226\148\128 Log active \226\148\128\226\148\128", Color3.fromRGB(119, 119, 119)) end
            end,
        })
        local logClearBtn = New("TextButton", {
            Size = UDim2.new(1, 0, 0, 24), BackgroundColor3 = Color3.new(1, 1, 1),
            BackgroundTransparency = 0, Font = Enum.Font.GothamBold,
            Text = "CLEAR LOG", TextColor3 = Color3.fromRGB(10, 10, 10),
            TextSize = 10, AutoButtonColor = false, Parent = logBody,
        })
        Round(logClearBtn, 8)
        New("UIGradient", {
            Color = ColorSequence.new(Color3.fromRGB(235, 235, 235), Color3.fromRGB(185, 185, 185)),
            Rotation = 135, Parent = logClearBtn,
        })
        local logClearStroke = Stroke(logClearBtn, Color3.fromRGB(80, 80, 80), 1, 0.4)
        AddButtonHover(logClearBtn, logClearStroke, 0.08)
        SafeConnect(GetSignal(logClearBtn, "MouseButton1Click"), function()
            PlayUISound("Click")
            for _, c in ipairs(fireLogScroll:GetChildren()) do
                if c:IsA("Frame") then pcall(function() c:Destroy() end) end
            end
            fireLogLines = 0
        end)
        task.spawn(function()
            while true do
                task.wait((Window and Window.Minimized) and 10 or 5.0)
                if not IsCurrentRun() then break end
                if not (Window and Window.Minimized) then
                if fireLogEnabled then
                    if spamActive then
                        local targets = getTargetRemotes()
                        if #targets > 0 then
                            logSampleCounter = logSampleCounter + 1
                            local r  = targets[((logSampleCounter - 1) % #targets) + 1]
                            local ts = string.format("%05.1f", os.clock() % 100000)
                            AddFireLogLine(
                                "[" .. ts .. "]  " .. r.name .. "  (" .. r.kind .. ")  payload=" .. tostring(payloadMode),
                                Color3.fromRGB(206, 206, 206)
                            )
                        end
                    elseif stfActive and stfRemote then
                        local ts   = string.format("%05.1f", os.clock() % 100000)
                        local kind = stfRemote:IsA("RemoteFunction") and "Function" or "Event"
                        AddFireLogLine(
                            "[" .. ts .. "]  " .. stfRemote.Name .. "  (" .. kind .. ")  [STF]  payload=" .. tostring(payloadMode),
                            Color3.fromRGB(175, 175, 175)
                        )
                    end
                end
                end
            end
        end)
    end
