    local _DAILY_LIMIT_REGULAR = 5
    local _DAILY_LIMIT_PREMIUM = 10
    local _USAGE_FILE    = "jeyhub_spam_usage.json"
    local _usageToday    = 0
    local _usageDateKey  = ""
    local function _TodayKey()
        local t  = os.time()
        local d  = math.floor(t / 86400)
        local y  = 1970 + math.floor(d / 365.25)
        local mo = math.floor((d % 365) / 30.44) + 1
        local dy = math.floor(d % 30.44) + 1
        return string.format("%04d-%02d-%02d", y, mo, dy)
    end
    local function _LoadUsage()
        pcall(function()
            if typeof(readfile) == "function" then
                local raw = readfile(_USAGE_FILE)
                if raw and raw ~= "" then
                    local HS2 = game:GetService("HttpService")
                    local ok, t = pcall(function() return HS2:JSONDecode(raw) end)
                    if ok and t and t.date == _TodayKey() then
                        _usageToday   = tonumber(t.count) or 0
                        _usageDateKey = t.date
                    end
                end
            end
        end)
    end
    local function _SaveUsage()
        pcall(function()
            if typeof(writefile) == "function" then
                local HS2 = game:GetService("HttpService")
                local ok, s = pcall(function()
                    return HS2:JSONEncode({ date = _usageDateKey, count = _usageToday })
                end)
                if ok then writefile(_USAGE_FILE, s) end
            end
        end)
    end
    local function _IncrementUsage()
        local today = _TodayKey()
        if _usageDateKey ~= today then
            _usageDateKey = today
            _usageToday   = 0
        end
        _usageToday = _usageToday + 1
        _SaveUsage()
    end
    local function _CheckDailyLimit(limit)
        limit = limit or _DAILY_LIMIT_REGULAR
        local today = _TodayKey()
        if _usageDateKey ~= today then
            _usageDateKey = today
            _usageToday   = 0
        end
        return _usageToday < limit, limit - _usageToday
    end
    _LoadUsage()
