    local function _HM_SetRW(mt, writable)
        if typeof(setreadonly) == "function" then
            pcall(setreadonly, mt, not writable)
        elseif typeof(make_writeable) == "function" and writable then
            pcall(make_writeable, mt)
        end
    end
    local function _HM_Install()
        if _HM_INSTALLED then return end
        if typeof(hookmetamethod) ~= "function" or typeof(getrawmetatable) ~= "function" then return end
        local mt     = getrawmetatable(game)
        local origNC = mt.__namecall
        _HM_RESTORE_NC = origNC
        _HM_SetRW(mt, true)
        mt.__namecall = newcclosure(function(self, ...)
            local method = tostring(getnamecallmethod and getnamecallmethod() or "")
            local isFS   = method == "FireServer"
            local isIS   = method == "InvokeServer"
            if not isFS and not isIS then
                return origNC(self, ...)
            end
            local args  = { ... }
            local extra = 0
            if _HM_EN_PIANO and _HM_SET_PIANO[self] then
                extra = _HM_EX_PIANO
            elseif _HM_EN_FIRESVR and _HM_SET_FIRESVR[self] then
                extra = _HM_EX_FIRESVR
            elseif _HM_EN_FISHING and _HM_SET_FISHING[self] then
                extra = _HM_EX_FISHING
            elseif _HM_EN_STF and _HM_SET_STF[self] then
                extra = _HM_EX_STF
            elseif _HM_EN_LAGSVR and _HM_SET_LAGSVR[self] then
                extra = _HM_EX_LAGSVR
            elseif _HM_EN_SUBMITVOTE and _HM_SET_SUBMITVOTE[self] then
                extra = _HM_EX_SUBMITVOTE
            elseif _HM_EN_REQPROFILE and _HM_SET_REQPROFILE[self] then
                extra = _HM_EX_REQPROFILE
            end
            if extra > 0 then
                if isIS then
                    for _ = 1, extra do
                        task.spawn(origNC, self, table.unpack(args))
                    end
                else
                    for _ = 1, extra do
                        pcall(origNC, self, table.unpack(args))
                    end
                end
            end
            return origNC(self, ...)
        end)
        _HM_SetRW(mt, false)
        _HM_INSTALLED = true
    end
    local function _HM_Uninstall()
        if not _HM_INSTALLED then return end
        if typeof(getrawmetatable) ~= "function" then return end
        local mt = getrawmetatable(game)
        _HM_SetRW(mt, true)
        if _HM_RESTORE_NC then
            mt.__namecall = _HM_RESTORE_NC
            _HM_RESTORE_NC = nil
        end
        _HM_SetRW(mt, false)
        _HM_SET_PIANO      = {}
        _HM_SET_FIRESVR    = {}
        _HM_SET_FISHING    = {}
        _HM_SET_STF        = {}
        _HM_SET_LAGSVR     = {}
        _HM_SET_SUBMITVOTE = {}
        _HM_SET_REQPROFILE = {}
        _HM_INSTALLED = false
    end
