    local function _scoreRemote(name)
        local n = name:lower()
        local score = 0
        for _, kw in ipairs(REMOTE_KW) do
            if n:find(kw) then score = score + 1 end
        end
        return score
    end
    local function _matchedKW(name)
        local n = name:lower()
        local out = {}
        for _, kw in ipairs(REMOTE_KW) do
            if n:find(kw) then table.insert(out, kw) end
        end
        return table.concat(out, ", ")
    end
    local function ScanPianoRemotes()
        foundRemotes = {}
        local roots = {
            game:GetService("ReplicatedStorage"),
            game:GetService("Workspace"),
        }
        pcall(function()
            table.insert(roots, game:GetService("ReplicatedFirst"))
        end)
        local seen = {}
        for _, root in ipairs(roots) do
            pcall(function()
                for _, obj in ipairs(root:GetDescendants()) do
                    if not seen[obj] then
                        if obj:IsA("RemoteEvent") or obj:IsA("RemoteFunction") then
                            local s = _scoreRemote(obj.Name)
                            if s >= 2 then
                                seen[obj] = true
                                local path = obj.Name
                                local p = obj.Parent
                                local depth = 0
                                while p and p ~= game and depth < 6 do
                                    path = p.Name .. "." .. path
                                    p = p.Parent
                                    depth = depth + 1
                                end
                                table.insert(foundRemotes, {
                                    name    = obj.Name,
                                    remote  = obj,
                                    kind    = obj.ClassName,
                                    path    = path,
                                    score   = s,
                                    matches = _matchedKW(obj.Name),
                                })
                            end
                        end
                    end
                end
            end)
        end
        table.sort(foundRemotes, function(a, b) return a.score > b.score end)
        _HM_RebuildPianoSet()
        return foundRemotes
    end
    local _globalPiano = nil
    local function _getGPC()
        if _globalPiano and _globalPiano.Parent then return _globalPiano end
        local ok, obj = pcall(function()
            return workspace:FindFirstChild("GlobalPianoConnector")
        end)
        _globalPiano = (ok and obj) or nil
        return _globalPiano
    end
    local function FirePianoRemote(noteId)
        local fired = false
        for _, rem in ipairs(pianoRemotes) do
            if rem and rem.Parent then
                pcall(function()
                    if rem:IsA("RemoteEvent") then
                        rem:FireServer("play", noteId)
                    elseif rem:IsA("RemoteFunction") then
                        rem:InvokeServer("play", noteId)
                    end
                end)
                fired = true
            end
        end
        if not fired then
            local gpc = _getGPC()
            if gpc then
                _HM_SET_PIANO[gpc] = true
                pcall(function() gpc:FireServer("play", noteId) end)
            end
        end
    end
    local function GetBurstCount()
        return math.max(1, math.min(100, math.ceil(brutalityLevel / 10)))
    end
    local function GetKeys(count)
        local out = {}
        if spamMode == "all" then
            for i = 1, count do out[i] = PIANO_ALL[((i-1) % _ALL_N) + 1] end
        elseif spamMode == "sequential" then
            for i = 1, count do
                out[i] = PIANO_ALL[((seqIdx + i - 2) % _ALL_N) + 1]
            end
            seqIdx = ((seqIdx + count - 1) % _ALL_N) + 1
        elseif spamMode == "chromatic" then
            for i = 1, count do
                out[i] = PIANO_WHITE[((seqIdx + i - 2) % _WHITE_N) + 1]
            end
            seqIdx = ((seqIdx + count - 1) % _WHITE_N) + 1
        elseif spamMode == "chord" then
            local pool = {}
            for _, k in ipairs(PIANO_ALL) do table.insert(pool, k) end
            local take = math.min(count * 2, #pool)
            for i = 1, take do
                local j = math.random(i, #pool)
                pool[i], pool[j] = pool[j], pool[i]
            end
            for i = 1, take do out[i] = pool[i] end
        elseif spamMode == "nuke" then
            for i = 1, count do
                out[i] = PIANO_ALL[((seqIdx + i - 2) % _ALL_N) + 1]
            end
            seqIdx = ((seqIdx + count - 1) % _ALL_N) + 1
        elseif spamMode == "whiteflood" then
            for i = 1, count do out[i] = PIANO_WHITE[((i-1) % _WHITE_N) + 1] end
        elseif spamMode == "blackflood" then
            for i = 1, count do out[i] = PIANO_BLACK[((i-1) % _BLACK_N) + 1] end
        elseif spamMode == "chaos" then
            local pool = (seqIdx % 2 == 0) and PIANO_WHITE or PIANO_BLACK
            local n    = #pool
            for i = 1, count do out[i] = pool[math.random(1, n)] end
            seqIdx = seqIdx + 1
        elseif spamMode == "thunderclap" then
            local src2 = (seqIdx % 2 == 0) and PIANO_ALL or PIANO_BLACK
            local n2   = #src2
            for i = 1, count do
                out[i] = src2[((seqIdx + i - 2) % n2) + 1]
            end
            seqIdx = ((seqIdx + count - 1) % n2) + 1
        else
            for i = 1, count do out[i] = PIANO_ALL[math.random(1, _ALL_N)] end
        end
        return out
    end
    local function SetStatus(txt, col)
        pcall(function()
            if statusLbl then
                statusLbl.Text       = "  " .. tostring(txt)
                statusLbl.TextColor3 = col or Color3.fromRGB(180,180,180)
