    local _activePianoSeat = nil
    local BENCH_POS        = Vector3.new(0, 0, 0)
    local function DoTPAndSit()
        local ok, err2 = pcall(function()
            local char = LocalPlayer and LocalPlayer.Character
            if not char then error("No character") end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum then error("No HRP/Humanoid") end
            if not (_activePianoSeat and _activePianoSeat.Parent) then
                error("Select a piano from the scan list first")
            end
            local seatPos = _activePianoSeat.Position
            hrp.CFrame = CFrame.new(seatPos + Vector3.new(0, 3, 0))
            local t0 = tick()
            while tick() - t0 < 0.25 do RunService.Heartbeat:Wait() end
            if _activePianoSeat:IsA("Seat") or _activePianoSeat:IsA("VehicleSeat") then
                _activePianoSeat:Sit(hum)
            end
        end)
        if not ok then
            SetStatus("[FAIL] " .. tostring(err2), Color3.fromRGB(130,130,130))
        else
            SetStatus("[OK] Teleported & seated.", Color3.fromRGB(215,215,215))
        end
    end
    local PIANO_KW = {
        "piano","keyboard","key",
    }
    local SEAT_RADIUS = 80
    local foundPianos       = {}
    local pianoListBtns     = {}
    local pianoListFrame    = nil
    local pianoPicStatusLbl = nil
    local selectedPianoLbl  = nil
    local function _hasPianoKW(s)
        local sl = s:lower()
        for _, kw in ipairs(PIANO_KW) do
            if sl:find(kw, 1, true) then return true end
        end
        return false
    end
    local function _ancestorNames(obj, depth)
        local names = {}
        local p = obj.Parent
        for _ = 1, depth do
            if not p or p == game then break end
            names[#names + 1] = p.Name
            p = p.Parent
        end
        return names
    end
    local function _isPianoCandidate(obj)
        if _hasPianoKW(obj.Name) then return true end
        for _, an in ipairs(_ancestorNames(obj, 4)) do
            if _hasPianoKW(an) then return true end
        end
        return false
    end
    local function _modelHasPianoChild(model)
        for _, child in ipairs(model:GetChildren()) do
            if _hasPianoKW(child.Name) then return true end
        end
        return false
    end
    local function _promptIsPiano(pp)
        local at = (pp.ActionText or ""):lower()
        local ot = (pp.ObjectText or ""):lower()
        return _hasPianoKW(at) or _hasPianoKW(ot)
    end
    local function _getRootModel(obj)
        local p = obj
        while p and p.Parent and not p.Parent:IsA("Workspace") and p.Parent ~= game do
            if p.Parent:IsA("Model") and p.Parent.Parent and
               (p.Parent.Parent:IsA("Workspace") or p.Parent.Parent == game) then
                return p.Parent
            end
            p = p.Parent
        end
        return p:IsA("Model") and p or nil
    end
    local function _findNearestSeat(pianoPos, allDesc)
        local SEAT_NAME_KW = { "bench","seat","stool","chair","sofa","throne","pew" }
        local bestPart, bestDist = nil, SEAT_RADIUS
        for _, obj in ipairs(allDesc) do
            local isSeat = obj:IsA("Seat") or obj:IsA("VehicleSeat")
            if not isSeat then
                local nl = obj.Name:lower()
                for _, kw in ipairs(SEAT_NAME_KW) do
                    if nl:find(kw, 1, true) then isSeat = true
                    break end
                end
            end
            if isSeat then
                local bp = obj:IsA("BasePart") and obj
                    or (obj:IsA("Model") and (obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart")))
                if bp then
                    local d = (bp.Position - pianoPos).Magnitude
                    if d < bestDist then bestDist = d
                    bestPart = bp end
                end
            end
        end
        return bestPart, bestDist
    end
    local function ScanPianos()
        foundPianos = {}
        local ws       = game:GetService("Workspace")
        local allDesc  = ws:GetDescendants()
        local seenModel = {}
        local function _addPiano(pos, displayName, sourceTag)
            for _, ex in ipairs(foundPianos) do
                if (ex.pianoPos - pos).Magnitude < 5 then return end
            end
            local seatPart, seatDist = _findNearestSeat(pos, allDesc)
            local lbl = displayName
                .. "  [" .. math.floor(pos.X)
                .. "," .. math.floor(pos.Y)
                .. "," .. math.floor(pos.Z) .. "]"
                .. "  <" .. sourceTag .. ">"
            table.insert(foundPianos, {
                name     = displayName,
                pianoPos = pos,
                seatPart = seatPart,
                seatDist = seatDist,
                label    = lbl,
            })
        end
        local gpc = workspace:FindFirstChild("GlobalPianoConnector")
        if not gpc then
            for _, ch in ipairs(workspace:GetChildren()) do
                if ch.Name:lower():find("piano") and ch:IsA("RemoteEvent") then
                    gpc = ch
                    break
                end
            end
        end
        if gpc and gpc.Parent then
            local pos = nil
            pcall(function()
                local pp = gpc.Parent:IsA("BasePart") and gpc.Parent
                    or (gpc.Parent:IsA("Model") and
                        (gpc.Parent.PrimaryPart or gpc.Parent:FindFirstChildWhichIsA("BasePart")))
                if pp then pos = pp.Position end
            end)
            if pos then _addPiano(pos, "GlobalPianoConnector", "GPC") end
        end
        for _, entry in ipairs(foundRemotes) do
            pcall(function()
                local remote = entry.remote
                if not remote or not remote.Parent then return end
                local p = remote.Parent
                while p and not p:IsA("Workspace") do
                    if p:IsA("Model") then
                        local bp = p.PrimaryPart or p:FindFirstChildWhichIsA("BasePart")
                        if bp then
                            _addPiano(bp.Position, p.Name .. " (via remote)", "REM")
                        end
                        break
                    end
                    if p:IsA("BasePart") then
                        _addPiano(p.Position, p.Name .. " (via remote)", "REM")
                        break
                    end
                    p = p.Parent
                end
            end)
        end
        for _, obj in ipairs(allDesc) do
            if obj:IsA("ProximityPrompt") then
                pcall(function()
                    if _promptIsPiano(obj) then
                        local bp = obj.Parent and obj.Parent:IsA("BasePart") and obj.Parent
                        if bp then
                            _addPiano(bp.Position, obj.Parent.Name .. " (ProxPrompt)", "PP")
                        else
                            local m = obj.Parent and obj.Parent:IsA("Model") and obj.Parent
                            if m then
                                local mbp = m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart")
                                if mbp then
                                    _addPiano(mbp.Position, m.Name .. " (ProxPrompt)", "PP")
                                end
                            end
                        end
                    end
                end)
            end
        end
        for _, obj in ipairs(allDesc) do
            if obj:IsA("Model") and not seenModel[obj] then
                pcall(function()
                    local hit = _hasPianoKW(obj.Name) or _modelHasPianoChild(obj)
                    if hit then
                        seenModel[obj] = true
                        local bp = obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart")
                        if bp then
                            _addPiano(bp.Position, obj.Name, "MDL")
                        end
                    end
                end)
            end
        end
        for _, obj in ipairs(allDesc) do
            if (obj:IsA("BasePart") or obj:IsA("MeshPart") or obj:IsA("SpecialMesh")) then
                pcall(function()
                    if _isPianoCandidate(obj) then
                        local parentModel = obj.Parent and obj.Parent:IsA("Model") and obj.Parent
                        if parentModel and seenModel[parentModel] then return end
                        local pos = obj:IsA("BasePart") and obj.Position
                            or (obj.Parent and obj.Parent:IsA("BasePart") and obj.Parent.Position)
                        if pos then
                            _addPiano(pos, obj.Name, "PART")
                            if parentModel then seenModel[parentModel] = true end
                        end
                    end
                end)
            end
        end
        return foundPianos
    end
    local function RefreshPianoList()
        for _, b in ipairs(pianoListBtns) do
            pcall(function() b:Destroy() end)
        end
        pianoListBtns = {}
        if #foundPianos == 0 then
            if pianoPicStatusLbl then
                pianoPicStatusLbl.Text       = "  No piano found on this map."
                pianoPicStatusLbl.TextColor3 = Color3.fromRGB(130, 130, 130)
            end
            return
        end
        if pianoPicStatusLbl then
            pianoPicStatusLbl.Text       = "  " .. #foundPianos .. " piano(s) found \226\128\148 select one to teleport:"
            pianoPicStatusLbl.TextColor3 = Color3.fromRGB(215, 215, 215)
        end
        for i, entry in ipairs(foundPianos) do
            local hasSeat = entry.seatPart ~= nil
            local seatInfo = hasSeat
                and ("seat ~" .. math.floor(entry.seatDist) .. " studs")
                or  "no seat nearby"
            local btnBg = Color3.fromRGB(18, 18, 18)
            local btn = New("TextButton", {
                Size             = UDim2.new(1, 0, 0, 38),
                BackgroundColor3 = btnBg,
                Font             = Enum.Font.Code,
                Text             = "  [" .. i .. "] " .. entry.label .. "\n        " .. seatInfo,
                TextColor3       = hasSeat and Color3.fromRGB(210, 210, 210)
                                           or  Color3.fromRGB(160, 160, 160),
                TextSize         = 9,
                TextXAlignment   = Enum.TextXAlignment.Left,
                TextWrapped      = true,
                AutoButtonColor  = false,
                LayoutOrder      = i,
                Parent           = pianoListFrame,
            })
            Round(btn, 7)
            Stroke(btn,
                hasSeat and Color3.fromRGB(70, 70, 70) or Color3.fromRGB(70, 70, 70),
                1, 0.45)
            local capEntry = entry
            local capBtn   = btn
            SafeConnect(GetSignal(btn, "MouseButton1Click"), function()
                PlayUISound("Click")
                for _, b in ipairs(pianoListBtns) do
                    pcall(function()
                        b.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
                        b.TextColor3       = Color3.fromRGB(210, 210, 210)
                    end)
                end
                capBtn.BackgroundColor3 = Color3.fromRGB(40, 40, 40)
                capBtn.TextColor3       = Color3.fromRGB(230, 230, 230)
                if capEntry.seatPart and capEntry.seatPart.Parent then
                    _activePianoSeat = capEntry.seatPart
                    BENCH_POS        = capEntry.seatPart.Position
                    if selectedPianoLbl then
                        selectedPianoLbl.Text       = "  Selected: " .. capEntry.name
                            .. "  |  Seat: " .. capEntry.seatPart.Name
                        selectedPianoLbl.TextColor3 = Color3.fromRGB(220, 220, 220)
                    end
                    SetStatus("[PIANO] " .. capEntry.name .. " selected \226\128\148 click TELEPORT & SIT.", Color3.fromRGB(220, 220, 220))
                else
                    _activePianoSeat = nil
                    BENCH_POS        = capEntry.pianoPos + Vector3.new(0, 3, 3)
                    if selectedPianoLbl then
                        selectedPianoLbl.Text       = "  Selected: " .. capEntry.name .. "  |  (no seat \226\128\148 TP in front of piano)"
                        selectedPianoLbl.TextColor3 = Color3.fromRGB(170, 170, 170)
                    end
                    SetStatus("[PIANO] " .. capEntry.name .. " \226\128\148 no seat found. TP in front of piano.", Color3.fromRGB(175, 175, 175))
                end
            end)
            table.insert(pianoListBtns, btn)
        end
    end
