    local function ScanRespawnPoints()
        local results = {}
        local ws      = game:GetService("Workspace")
        local char    = LocalPlayer and LocalPlayer.Character
        local hrp     = char and char:FindFirstChild("HumanoidRootPart")
        local origin  = hrp and hrp.Position or Vector3.new(0, 0, 0)
        for _, obj in ipairs(ws:GetDescendants()) do
            if obj:IsA("SpawnLocation") then
                local d = (obj.Position - origin).Magnitude
                table.insert(results, { part = obj, dist = d,
                    label = obj.Name .. "  [" .. math.floor(obj.Position.X)
                          .. ", " .. math.floor(obj.Position.Y)
                          .. ", " .. math.floor(obj.Position.Z) .. "]" })
            end
        end
        table.sort(results, function(a, b) return a.dist < b.dist end)
        return results
    end
