    local function StopSpam()
        spamGeneration = spamGeneration + 1
        spamActive     = false
        for _, th in ipairs(_activeLayer1Threads) do
            pcall(function()
                if type(th)=="thread" and coroutine.status(th)~="dead" then
                    if coroutine.close then coroutine.close(th) end
                end
            end)
        end
        _activeLayer1Threads = {}
        for _, conn in ipairs(activeConns) do
            pcall(function() conn:Disconnect() end)
        end
        activeConns  = {}
        consumerConn = nil
        displayConn  = nil
        _clrQ()
        totalFired   = 0
        _HM_Uninstall()
        SetStatus("[OFF] Spam FULLY STOPPED.", Color3.fromRGB(150, 150, 150))
        pcall(function()
            modeLbl.Text   = "  Mode: \226\128\148 | Burst/frame: \226\128\148"
            threadLbl.Text = "  Conns: 0 | Level: " .. tostring(brutalityLevel)
            countLbl.Text  = "  Keys fired: 0"
            rateLbl.Text   = "  Rate: 0 keys/s"
        end)
    end
    local function StartSpam()
        _HM_Install()
        if spamActive then return end
        do
            local lpName = ""
            pcall(function() lpName = game:GetService("Players").LocalPlayer.Name end)
            local isDev     = _SPAM_BYPASS_USERS[lpName] == true
            local isPremium = _PREMIUM_USERS[lpName]     == true
            if isDev then
            elseif _IsDevInServer() then
                SetStatus(
                    isPremium
                        and "[PREMIUM LOCKED] Developer ada di server. Priority tertinggi aktif — spam diblokir."
                        or  "[LOCKED] Developer ada di server ini. Spam diblokir.",
                    Color3.fromRGB(130, 130, 130)
                )
                return
            elseif isPremium then
                local canUse, remaining = _CheckDailyLimit(_DAILY_LIMIT_PREMIUM)
                if not canUse then
                    SetStatus("[LIMIT] Batas harian Premium tercapai (10/10). Coba lagi besok.", Color3.fromRGB(130, 100, 100))
                    return
                end
            else
                if _IsPremiumInServer() then
                    SetStatus("[LOCKED] Priority user ada di server. Reguler tidak bisa spam.", Color3.fromRGB(130, 130, 130))
                    return
                end
                local canUse, remaining = _CheckDailyLimit(_DAILY_LIMIT_REGULAR)
                if not canUse then
                    SetStatus("[LIMIT] Batas harian tercapai (5/5). Coba lagi besok.", Color3.fromRGB(130, 100, 100))
                    return
                end
            end
        end
        if #pianoRemotes == 0 then
            SetStatus("[ERROR] Select a remote first -- SCAN then click a piano remote.", Color3.fromRGB(130,130,130))
            return
        end
        for i = #pianoRemotes, 1, -1 do
            local ok = pcall(function() return pianoRemotes[i].Name end)
            if not ok then table.remove(pianoRemotes, i) end
        end
        if #pianoRemotes == 0 then
            SetStatus("[ERROR] Remote invalid. Scan again.", Color3.fromRGB(130,130,130))
            return
        end
        do
            local lpName2 = ""
            pcall(function() lpName2 = game:GetService("Players").LocalPlayer.Name end)
            local isDevNow  = _SPAM_BYPASS_USERS[lpName2] == true
            local isPremNow = _PREMIUM_USERS[lpName2]     == true
            if not isDevNow then
                _IncrementUsage()
                if isPremNow then
                    local _, rem = _CheckDailyLimit(_DAILY_LIMIT_PREMIUM)
                    SetStatus("[PREMIUM] Sesi ke-" .. tostring(_usageToday) .. "/10 hari ini. Sisa: " .. tostring(rem), Color3.fromRGB(210, 200, 160))
                else
                    local _, rem = _CheckDailyLimit(_DAILY_LIMIT_REGULAR)
                    SetStatus("[REGULER] Sesi ke-" .. tostring(_usageToday) .. "/5 hari ini. Sisa: " .. tostring(rem), Color3.fromRGB(180, 180, 180))
                end
            end
        end
        spamActive     = true
        spamGeneration = spamGeneration + 1
        totalFired     = 0
        seqIdx         = 1
        _clrQ()
        activeConns          = {}
        _activeLayer1Threads = {}
        local myGen    = spamGeneration
        local capLevel = math.max(1, math.min(10, brutalityLevel))
        local cfg      = LEVEL_CFG[capLevel]
        local threadMult  = 62 - math.max(1, math.min(61, threadCount))
        local keyMult     = 62 - math.max(1, math.min(61, keysPerBurst))
        local passCeiling = threadMult * keyMult
        local numConns    = cfg.conns
        local budgetSec   = cfg.budget
        local sigBudCap   = cfg.sigBudget
        local capDelay    = spamDelay / 1000
        local allCount    = _ALL_N
        local validEvents    = {}
        local validFunctions = {}
        for _, rem in ipairs(pianoRemotes) do
            if rem and rem.Parent then
                if rem:IsA("RemoteEvent") then
                    validEvents[#validEvents + 1] = rem
                elseif rem:IsA("RemoteFunction") then
                    validFunctions[#validFunctions + 1] = rem
                end
            end
        end
        local evCount = #validEvents
        local fnCount = #validFunctions
        local function _makeFireFn(evArr, evN)
            if evN == 1 then
                local ev = evArr[1]
                return function(budS)
                    local t0 = tick(); local passes = 0
                    repeat
                        for ki = 1, allCount do ev:FireServer("play", ki) end
                        passes = passes + 1
                    until tick() - t0 >= budS or passes >= passCeiling
                    return passes
                end
            end
            return function(budS)
                local t0 = tick(); local passes = 0
                repeat
                    for ki = 1, allCount do
                        for ei = 1, evN do evArr[ei]:FireServer("play", ki) end
                    end
                    passes = passes + 1
                until tick() - t0 >= budS or passes >= passCeiling
                return passes
            end
        end
        local function _makeFireFnFn(fnArr, fnN)
            if fnN == 1 then
                local fn = fnArr[1]
                return function(budS)
                    local t0 = tick(); local passes = 0
                    repeat
                        for ki = 1, allCount do fn:InvokeServer("play", ki) end
                        passes = passes + 1
                    until tick() - t0 >= budS or passes >= passCeiling
                    return passes
                end
            end
            return function(budS)
                local t0 = tick(); local passes = 0
                repeat
                    for ki = 1, allCount do
                        for fi = 1, fnN do fnArr[fi]:InvokeServer("play", fi) end
                    end
                    passes = passes + 1
                until tick() - t0 >= budS or passes >= passCeiling
                return passes
            end
        end
        local fireFn
        if evCount >= 1 then
            fireFn = _makeFireFn(validEvents, evCount)
        elseif fnCount >= 1 then
            fireFn = _makeFireFnFn(validFunctions, fnCount)
        else
            fireFn = function() return 0 end
        end
        local _sigBudget = { hb = 0, st = 0, rs = 0 }
        local _hbRst = RunService.Heartbeat:Connect(function()      _sigBudget.hb = 0 end)
        local _stRst = RunService.Stepped:Connect(function()        _sigBudget.st = 0 end)
        local _rsRst = RunService.RenderStepped:Connect(function()  _sigBudget.rs = 0 end)
        table.insert(activeConns, _hbRst)
        table.insert(activeConns, _stRst)
        table.insert(activeConns, _rsRst)
        local _sigTable = {
            { sig = RunService.Heartbeat,     key = "hb" },
            { sig = RunService.Stepped,       key = "st" },
            { sig = RunService.RenderStepped, key = "rs" },
        }
        for ci = 1, numConns do
            local lt_ref   = { 0 }
            local sEntry   = _sigTable[((ci - 1) % 3) + 1]
            local sigRef   = sEntry.sig
            local budKey   = sEntry.key
            local conn = sigRef:Connect(function()
                if not spamActive or myGen ~= spamGeneration then return end
                if _sigBudget[budKey] >= sigBudCap then return end
                if capDelay > 0 then
                    local n = tick()
                    if n - lt_ref[1] < capDelay then return end
                    lt_ref[1] = n
                end
                local t0 = tick()
                local p  = fireFn(budgetSec)
                _sigBudget[budKey] = _sigBudget[budKey] + (tick() - t0)
                totalFired = totalFired + p * allCount
            end)
            table.insert(activeConns, conn)
        end
        consumerConn = activeConns[1]
        local frameAcc  = 0
        local lastTotal = 0
        local connDisp  = RunService.Heartbeat:Connect(function()
            if not spamActive or myGen ~= spamGeneration then return end
            frameAcc = frameAcc + 1
            if frameAcc < 120 then return end
            frameAcc = 0
            local delta = totalFired - lastTotal
            lastTotal   = totalFired
            task.defer(function()
                pcall(function()
                    countLbl.Text  = "  Keys fired: " .. tostring(totalFired)
                    rateLbl.Text   = "  Rate: ~" .. tostring(math.floor(delta / 2)) .. " keys/s  |  Keys: " .. tostring(allCount)
                    modeLbl.Text   = "  Mode: " .. spamMode .. " | " .. cfg.label .. " | tMult=" .. tostring(threadMult) .. "x kMult=" .. tostring(keyMult) .. "x | ceil=" .. tostring(passCeiling)
                    threadLbl.Text = "  Conns: " .. tostring(numConns) .. " (HB+ST+RS\xc3\x973) | " .. tostring(math.floor(budgetSec * 1000)) .. "ms/conn | sigCap=" .. tostring(math.floor(sigBudCap * 1000)) .. "ms | remotes=" .. tostring(evCount + fnCount)
                end)
            end)
        end)
        table.insert(activeConns, connDisp)
        displayConn = connDisp
        local _rnames = {}
        for _, r in ipairs(pianoRemotes) do
            local ok, n = pcall(function() return r.Name end)
            if ok then table.insert(_rnames, n) end
        end
        local remoteName = #_rnames > 0 and table.concat(_rnames, " + ") or "remote"
        SetStatus(
            "[" .. cfg.label .. "] " .. remoteName
            .. " | " .. tostring(allCount) .. " keys \xc3\x97 " .. tostring(evCount + fnCount)
            .. " remotes | " .. tostring(numConns) .. " conns (HB+ST+RS\xc3\x973)"
            .. " | " .. tostring(math.floor(budgetSec * 1000)) .. "ms/conn"
            .. " | sigCap=" .. tostring(math.floor(sigBudCap * 1000)) .. "ms",
            Color3.fromRGB(215, 215, 215)
        )
        pcall(function()
            threadLbl.Text = "  Conns: " .. tostring(numConns) .. " (HB+ST+RS\xc3\x973) | " .. cfg.label .. " ACTIVE | tMult=" .. tostring(threadMult) .. "x kMult=" .. tostring(keyMult) .. "x"
        end)
    end
    SafeConnect(GetSignal(startBtn, "MouseButton1Click"), function()
        PlayUISound("ToggleOn")
        StartSpam()
    end)
    SafeConnect(GetSignal(stopBtn, "MouseButton1Click"), function()
        PlayUISound("ToggleOff")
        StopSpam()
        SetStatus("[REJOIN] Teleporting to the same server...", Color3.fromRGB(200, 200, 200))
        task.delay(0.4, function()
            local TeleportSvcLS = SafeService("TeleportService")
            if not TeleportSvcLS then
                SetStatus("[REJOIN] TeleportService not available.", Color3.fromRGB(130,130,130))
                return
            end
            pcall(function()
                local jobId = game.JobId
                if jobId and jobId ~= "" then
                    TeleportSvcLS:TeleportToPlaceInstance(game.PlaceId, jobId, LocalPlayer)
                else
                    TeleportSvcLS:Teleport(game.PlaceId, LocalPlayer)
                end
            end)
        end)
    end)
    do
        local _lsLP = Players and Players.LocalPlayer
        if _lsLP then
            SafeConnect(GetSignal(_lsLP, "CharacterAdded"), function()
                if spamActive then
                    StopSpam()
                    _globalPiano = nil
                    SetStatus("[RESPAWN] Spam automatically stopped on respawn.", Color3.fromRGB(180, 180, 180))
                end
            end)
        end
    end
    do
        local _PlayersLS3 = game:GetService("Players")
        SafeConnect(GetSignal(_PlayersLS3, "PlayerAdded"), function(p)
            if _PREMIUM_USERS[p.Name] then
                if _LocalIsBypassed() then return end
                _SetSpamLock(true)
                if spamActive then StopSpam() end
                if _LocalIsPremium() then
                    SetStatus("[PREMIUM LOCKED] Priority lain (" .. p.Name .. ") masuk ke server. Spam diblokir.", Color3.fromRGB(160, 160, 160))
                else
                    SetStatus("[LOCKED] Priority (" .. p.Name .. ") masuk ke server. Spam reguler otomatis berhenti.", Color3.fromRGB(160, 160, 160))
                end
            end
        end)
    end
    do
        local _PlayersLS4 = game:GetService("Players")
        SafeConnect(GetSignal(_PlayersLS4, "PlayerRemoving"), function(p)
            if _PREMIUM_USERS[p.Name] and not _IsDevInServer() then
                if _LocalIsBypassed() then return end
                local otherPremInServer = false
                pcall(function()
                    for _, pl in ipairs(game:GetService("Players"):GetPlayers()) do
                        if _PREMIUM_USERS[pl.Name] and pl.Name ~= p.Name then
                            otherPremInServer = true
                            break
                        end
                    end
                end)
                if not otherPremInServer then
                    _SetSpamLock(false)
                    if not spamActive then
                        SetStatus("[UNLOCKED] Priority (" .. p.Name .. ") sudah keluar. Spam bisa digunakan.", Color3.fromRGB(220, 220, 220))
                    end
                end
            end
        end)
    end
    do
        local _PlayersLS = game:GetService("Players")
        SafeConnect(GetSignal(_PlayersLS, "PlayerRemoving"), function(p)
            if _SPAM_BYPASS_USERS[p.Name] then
                _SetSpamLock(false)
                if not spamActive then
                    SetStatus("[UNLOCKED] Developer sudah keluar. Spam bisa digunakan.", Color3.fromRGB(220, 220, 220))
                end
            end
        end)
    end
    do
        local _PlayersLS2 = game:GetService("Players")
        SafeConnect(GetSignal(_PlayersLS2, "PlayerAdded"), function(p)
            if _SPAM_BYPASS_USERS[p.Name] then
                if _LocalIsBypassed() then return end
                _SetSpamLock(true)
                local isPrem = _LocalIsPremium()
                local wasSpamActive = spamActive
                if spamActive then StopSpam() end
                if not isPrem and wasSpamActive then
                    SetStatus("[LOCKED] Developer masuk ke server ini. Spam aktif dihentikan, rejoining...", Color3.fromRGB(160, 160, 160))
                    task.delay(0.5, function()
                        local TeleportSvcDev = SafeService("TeleportService")
                        if not TeleportSvcDev then return end
                        pcall(function()
                            local jobId = game.JobId
                            if jobId and jobId ~= "" then
                                TeleportSvcDev:TeleportToPlaceInstance(game.PlaceId, jobId, LocalPlayer)
                            else
                                TeleportSvcDev:Teleport(game.PlaceId, LocalPlayer)
                            end
                        end)
                    end)
                else
                    SetStatus(
                        isPrem
                            and "[PREMIUM LOCKED] Developer masuk ke server. Spam diblokir."
                            or  "[LOCKED] Developer masuk ke server ini. Spam diblokir.",
                        Color3.fromRGB(160, 160, 160)
                    )
                end
            end
        end)
    end
    do
        if not _LocalIsBypassed() and _IsDevInServer() then
            _SetSpamLock(true)
            SetStatus(
                _LocalIsPremium()
                    and "[PREMIUM LOCKED] Developer sudah ada di server ini. Priority tertinggi aktif."
                    or  "[LOCKED] Developer sudah ada di server ini.",
                Color3.fromRGB(160, 160, 160)
            )
        end
    end
    _Tabs.FireServer(page2)
    _lsStylePills()
end
BuildTabStaggered("Lag Server", _Tabs.LagServer)
task.wait()
BuildTabStaggered("Report", _Tabs.Report)
task.wait()
if Window and Window.Gui then
    task.spawn(function()
        while true do
            task.wait(5)
            if not IsCurrentRun() then break end
            local gui = Window.Gui
            local stillValid = false
            pcall(function()
                stillValid = gui.Parent ~= nil and gui:IsDescendantOf(game)
            end)
            if not stillValid then
                local okReparent = pcall(function()
                    local newParent = GetGuiParent()
                    if newParent then
                        gui.Parent = newParent
                    end
                end)
                if not okReparent then
                    break
                end
            end
        end
    end)
end
return Window
